-- GENERATED by `wfj generate` from data/quest/quest-0006.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [6001] = { "肉体と精神", "Lunaclawを呼び出すため、AuberdineのMoonkin StoneにCenarion Moondustを使って下さい。そしてLunaclawと対峙し、Lunaclawが持つ肉体と精神の力を獲得しなくてはなりません。\n\nそれを終えたら、DarnassusのMathrengyl Bearwalkerと話して下さい。", "Auberdineのすぐ東に、moonkinの洞窟がたくさんあります。Auberdineに最も近い洞窟の中に、Moonkin Stoneがあります。Moonkin Stoneの守護者であるLunaclawは、Cenarion Moondustが石に使われたとき姿を現すでしょう。「爪」のひとつとして使わねばならない力を、Lunaclawは身に宿しています。\n\n{name}、あなたはCenarion Moondustを使う権利を得ました……さあ、示して下さい。肉体の力とドルイドとして必要な精神力を、自らに宿す権利を獲得したのだと!", "目の前にある試練に立ち向かったとき、肉体の強さと心の強さについてのあなたの理解は完全なものとなるでしょう。その時までは、これ以上あなたを助けることはできません。", "ついに広い世界へ大きな一歩を踏み出したのです、{name}。あなたの中にGreat Bear Spiritの教えを感じます。そして、Lunaclawが宿していた力を受け継いだことも。\n\nもはや障害はありません……それでは教えましょう。「爪」の{class}とは何であるかを!", 0x9109866f, 0xe7d92ce2, 0xd25471ff, 0xf431a09c, 0x5233b46d, "....." },
  [6002] = { "肉体と精神", "Lunaclawを呼び出すため、MulgoreとBarrensの間にあるMoonkin StoneにCenarion Lunardustを使って下さい。そしてLunaclawと対峙し、Lunaclawが持つ肉体と精神の力を獲得しなくてはなりません。\n\nそれを終えたら、Thunder BluffのTurak Runetotemと話して下さい。", "BarrensのTaurajoの西の地、Mulgoreへ入るちょうど手前のところに、Moonkin Stoneがあります。moonkinは特別な獣で、あの地域一帯に元々生息しているものではありません。Moonkin Stoneの守護者であるLunaclawは、Cenarion Lunardustが石に使われたとき姿を現すでしょう。「爪」のひとつとして使わねばならない力を、Lunaclawは身に宿しています。\n\n{name}、あなたはCenarion Lunardustを使う権利を得ました……さあ、示して下さい。肉体の力とドルイドとして必要な精神力を、自らに宿す権利を獲得したのだと!", "目の前にある試練に立ち向かったとき、肉体の強さと心の強さについてのあなたの理解は完全なものとなるでしょう。その時までは、これ以上あなたを助けることはできません。", "ついに広い世界へ大きな一歩を踏み出したのです、{name}。あなたの中にGreat Bear Spiritの教えを感じます。そして、Lunaclawが宿していた力を受け継いだことも。\n\nもはや障害はありません……それでは教えましょう。「爪」の{class}とは何であるかを!", 0x9109866f, 0xd7388bf3, 0x130e04b9, 0xf431a09c, 0x5233b46d, "....." },
  [6004] = { "やり残した仕事", "Scarlet Medicsを$N1体、Scarlet Huntersを$N2体、Scarlet Magiを$N3体、Scarlet Knightsを$N4体倒してから、Western PlaguelandsのKirsta Deepshadowのところへ戻って下さい。", "私は斥候として送られ、損害を与えつつHearthglenの防備の強さを探っていた。Allianceの中には、あの小さな町には歴史的な重要性以上のものがあると考える者もいる。その重要性が何なのかを問うのは私の仕事ではないが、いずれにせよ、休んで回復するまでは続けられる状態じゃない。\n\nその気があるなら、手伝ってくれればたっぷり払おう。まずはここから南、奴らが築いた小さな防塁の近くにある野営地から始めてくれ。十分に強いと証明できたら、私の本来の目的にも手を貸してもらえるかもしれない。", "調子はどうだ、{name}? 思っていたより手強いか? そうでないといいんだが。ここでやり遂げるつもりなら、これまで頼んできたことよりずっと多くの力が必要になるからな。", "よくやってくれた、{name}。こんなに早く片付けてくれるとは驚いた。ありがとう。\n\nScarlet Crusadeとそのやり方を認める者には、まだ会ったことがない。私もStormwindの誰にも負けないくらい光を信じているが、奴らは自分たちの運動に忠実でない者は誰であれ、罪のない者でさえ、殺したいだけなのだと示してきた。", 0xe0ec1241, 0x659ad929, 0x6771ee99, 0x38343473, 0x672f1da6, "....." },
  [6021] = { "Zaeldarr the Outcast", "Zaeldarr's HeadをLight's Hope ChapelのCaretaker Alenのところへ持って行って下さい。", "信じられるか？plaguelandsであれだけ苦労してるってのに……泥棒の心配までしなきゃならないなんて。それもただの泥棒じゃない、トロールの泥棒だ。\n\nしかもただのトロールの泥棒じゃない。死んだトロールの泥棒だ！\n\n奴らを率いているのはZaeldarr the Outcastっていう、でかい死んだトロールだ。夜になるとここへ来て、下の穴から死体を盗み、それを奴らの邪悪な死んだトロールの隠れ家――西にあるUndercroft――に持ち帰るんだ。\n\nそこへ行ってZaeldarrを片付けてくれ、{name}。あいつのいたずらにはもううんざりなんだ！", "隠れ家は見つかったか、{name}? Zaeldarrは始末したか?", "やった、あいつを仕留めたんだね! 手下どもにも思い知らせてくれたならいいんだけど!", 0x4f22991f, 0x5866d194, 0x3e70ba0d, 0x929d2bce, 0x3752d70b, "....." },
  [6022] = { "目的ある殺し", "東にあるCorin's Crossingへ行き、町に巣食うScourgeを殺戮する。$N2分以内にLiving Rotを$N1個集める。Mortar and Pestleを使ってLiving RotをすりつぶしてCoagulated Rotにする。", "私の農場にいる間、お前は目的を持って殺すのだ。\n\n最初の任務は、私の猟犬に餌をやることだ。\n\nこの乳鉢と乳棒を持ってCorin's Crossingへ行け。そこには屠るべきScourgeがよりどりみどりだ。奴らの新鮮な死骸からliving rotが要る。そのliving rotを乳鉢ですり潰し、置いて凝固させろ。そのcoagulated rotをここへ持ち帰れ。\n\nそれから愚か者、アンデッドから取ったliving rotはそう長くは「生きて」いないと心得ろ。素早く殺すのだ！", "泣いているのか? これがお前にとって「退屈」すぎるというのなら、「英雄」殿、Dark Ladyのもとへ戻って、私の農場でひどい扱いを受けたと報告することを勧めるぞ。\n\nさあ、私の前から消えろ!", "期待外れだな。お前を私の猟犬の餌にしてやれると思っていたのだが。\n\n<Nathanosはため息をつく。>\n\nまあ、少なくとも犬どもには食い物ができたわけだ。", 0x7a12f351, 0x0ff0b89c, 0x719c0fa7, 0x7acc712f, 0xd1ebac5f, "....." },
  [6023] = { "やり残した仕事", "Huntsman RadleyとCavalier Durgenを倒してから、Western PlaguelandsのKirsta Deepshadowのところへ戻って下さい。", "私の本当の任務は、Scarlet Crusadeの外郭部隊を弱らせ、それからHearthglenに潜入して奴らの兵力を探ることだった。まだ一人でやれる状態じゃないから、もう一度君に手を貸してもらえないだろうか、{name}？見つかる前に集めた情報によれば、Crusadeには町の外の部隊の要となる重要人物が二人いる。Huntsman RadleyとCavalier Durgenだ。こいつらを倒せば、前進できる。二人は町の外、Hearthglen Pass沿いにいるはずだ。", "もう見つかったか、{name}? あの2人を片付ければ、Hearthglenに入って奴らの配置をもっと詳しく調べられる。君の助けなしではできないんだ。頼む、RadleyとDurgenを見つけてくれ。", "ありがとう、{name}。期待していた以上に助けてもらった。ここの空気は意志を吸い取っていくようだ。疲れを感じるし、ここに長くいるほど良くならないのが分かる。\n\nHearthglenそのものにどうやって潜入して、Scarlet Crusadeの勢力がどれほど強いかを報告すればいいのか、正直よく分からない。\n\nだがそれは別の話だ。行く前に、ほら、これを受け取ってくれ……手伝ってくれた礼だ。改めてありがとう。", 0xe0ec1241, 0xbafd5572, 0xcd59769d, 0xe1d07dbf, 0x5f278f17, "....." },
  [6024] = { "Hameyaの嘆願", "Infiltrator Hameyaを倒す。彼の鍵をUndercroftの裏にあるMound of Dirtに使う。", "我を殺せ。手遅れになる前に。\n\n我はHameya。Zul'Masharへ旅する途中、兄弟たちと我は腐った肉を食べた……そして我らは変わってしまった。我らは感染している。\n\n今もリッチの言葉が聞こえる。Zul'Masharへたどり着き、同胞にさらに感染を広げよと急き立てている。我には抗えぬ。だから、意志が失われる前にこの巻物を書いた。\n\nこの墓所の裏にある荷馬車のそばの土に、箱を埋めた。だが、それを開けられるのは我の鍵だけだ。鍵は我が持っている。我の宝が欲しければ、我を見つけよ。\n\n我を殺せ。手遅れになる前に。", "ここに埋められた箱にはしっかりと鍵がかかっている。", "Hameyaの箱が開いた!!", 0xee455833, 0x60125197, 0xa2b42b67, 0x524048c5, 0x349f4764, "....." },
  [6025] = { "やり残した仕事", "Hearthglenに入り、町を見渡してScarlet Crusadeの戦力を見積もれる高い見晴らしの場所を見つけたら、Western PlaguelandsのKirsta Deepshadowのところへ戻って下さい。", "なんだって？本当に？もっと知りたいのか？でも、君はもう私のためにこんなに尽くしてくれたじゃないか、{name}。私のためにHearthglenそのものに入ってくれなんて、とても頼めないよ。\n\n本当にいいのか、{name}？HearthglenはPassよりずっと危険だ――君を守ってやることも、何に出くわすかの情報を渡すこともできない。\n\nまあ、本当に手伝ってくれる気があるなら、町に入って、町がよく見渡せる高い場所を見つけてくれ。そこから奴らの兵力を見積もって、私に報告してほしい。でも気をつけてくれよ……", "危険な任務だ、{name}。君の勇気がうらやましいよ。", "やってくれたな、{name}! ありがとう!\n\nできるだけ早くEllingに……いや、Stormwindに戻るよ。ほら、この金を受け取ってくれ。せめてものお礼だ。君は同胞の誇りだよ、{name}。ありがとう、幸運を祈る。", 0xe0ec1241, 0xfa067beb, 0x16a8c395, 0xb6a2f182, 0x696280bf, "....." },
  [6026] = { "大した頼みだ", "Smokey LaRueは、Thorium Barsを$N1個、Golden Rodを$N2個、Hi-Explosive Bombsを$N3個、Unstable Triggersを$N4個手に入れてほしいと言っています。\n\nこれらの品を手に入れるには、鍛冶屋と技術者を見つける必要がある。", "このArgent Dawnの連中が、ちょいとした解体仕事をこのSmokey様に頼んできたのさ。Smokeyのおふくろは馬鹿を育てたりしちゃいない。金貨がテーブルに叩きつけられりゃ、Smokeyはいつでも仕事を引き受ける。それが俺のモットーだ！\n\nさて、ちょいと足を使ってくれるなら、報酬を君と山分けしてもいい。こういう段取りだ。俺はPlaguewoodへ行って、ぶっ壊さなきゃならない建物に印をつけてくる。君は爆弾の部品を集めてくれ。全部揃ったら、ここでまた落ち合おう。どうだ、乗るか？", "このSmokeyを信じな、{race}。報酬はそれだけの価値があるさ。Argent Dawnの連中は、支払いに関してはいい加減なことはしないからな。", "報酬の半分は前払いで、残りの半分は仕事が終わってから払おう。", 0x5d72aed6, 0x693f04f8, 0xe8eab7ef, 0xda3f6ed0, 0xfc620627, "....." },
  [6027] = { "Book of the Ancients", "Book of the Ancientsを手に入れ、Ethel Rethorの塔にいるAzore Aldamortのところへ持って帰って下さい。", "{name}、Gem of the Serpentをあなたに託します。この宝石を、ここから北西にある小さな島、Ranazjar IsleにあるSerpent Statueの手に置いてください。置けば、Book of the Ancientsを守る者が呼び出されます。この書にはnagaの秘密、何世紀も守られてきた秘密が記されています。この書を私のもとへ持ってきてくれれば、鱗に覆われた敵について多くを学べるでしょう！", "ああ、{name}! また会えて嬉しいよ。Book of the Ancientsは持っているかい?", "長く失われていたBook of the Ancientsだ! この本は必ず最高評議会へ渡るようにしよう。今日はよくやってくれた。そのことに感謝せねばならん……英雄が感謝されるべきようにな!", 0x506094ee, 0x9ded0f2e, 0x0b6c3f2d, 0xb011a969, 0xf911986b, "....." },
  [6028] = { "Everlook Report", "Everlook ReportをWestern PlaguelandsのChillwind CampにいるArgent Officer Pureheartに届けて下さい。", "小さいながらも重要な用件を手伝ってくれる、責任感のある人物を探しています。私はArgent Dawnの利益を代表して、Everlookの地元の統治者のもとに来ています。Chillwind CampにいるArgent Officer Pureheartへ経過報告を届けなければなりません。ここからはかなり遠く、Western Plaguelandsの南の外れにあります。\n\n僭越ながら――これはあなたが私の上官に自己紹介し、ひょっとすると彼女から仕事をもらう絶好の機会になるかもしれませんよ！", "ようこそ、{class}。Argent Dawnを代表して、Chillwind Campにいる間のあなたの安全と宿を約束しよう。それに、あなたに頼みたい仕事もあるかもしれない……", "Gregorはとても機転の利く人です。彼はしばらく前からSteamwheedle Cartelと取引していて、ゴブリンとの交渉という「技」の達人になりました。ゴブリンの第一の忠誠が一番大きな財布を持つ者に向けられるのは確かですが、彼らは外交の価値も知っていて、それを尊重しています。何より、それで常連客ができるのですから……\n\nいずれにせよ、Argent Dawnはあなたの尽力を認めています。どうぞこれを、私たちの感謝とともに受け取ってください。", 0x0f48e274, 0x7c814620, 0x5ed36bac, 0x5219e014, 0xf4da6363, "....." },
  [6029] = { "Everlook Report", "Western PlaguelandsのBulwarkにいるArgent Officer GarushにEverlook Reportを届けて下さい。", "責任感のある方に、小さいながらも重要な用件を手伝っていただきたいのです。私はEverlookの地元当局に対するArgent Dawnの利益代表としてここにいます。進捗報告をBulwarkのArgent Officer Garushに届けなければなりません。ここからはかなり遠く、Western Plaguelandsの西の外れ、Tirisfal Gladesの東にあります。\n\n差し出がましいようですが――私の上官に自己紹介する絶好の機会ですし、もしかすると彼から仕事をもらえるかもしれませんよ！", "ようこそ、{class}。Argent Dawnを代表して、Bulwarkにいる間のあなたの安全と宿を約束しよう。それに、戦う価値のある大義のために戦う機会も与えられるかもしれないぞ!", "Gregorは人間にしては機転の利く人です。彼はしばらく前からSteamwheedle Cartelと取引していて、ゴブリンとの交渉という「技」の達人になりました。ゴブリンの第一の忠誠が一番大きな財布を持つ者に向けられるのは確かですが、彼らは外交の価値も知っていて、それを尊重しています。何より、それで常連客ができるのですから……\n\nいずれにせよ、Argent Dawnはあなたの尽力を認めています。どうぞこれを、私たちの感謝とともに受け取ってください。", 0x0f48e274, 0xa257e321, 0x14dacde8, 0x13244858, 0x79c7d3ac, "....." },
  [6030] = { "Duke Nicholas Zverenhoff", "Duke Nicholas Zverenhoffに'Studies in Spirit Speaking'を届けて下さい。彼はEastern PlaguelandsのLight's Hope Chapelにいます。", "この辺りにいるUmbranseという名の隠遁した霊媒が、Argent Dawnにたいそうな文学的傑作を提供してくれましてね……私がこれまで見た中で、おそらく最大のたわごとの集大成と言えるものです。\n\nDawnで最も尊敬される指導者の一人、Duke Nicholas Zverenhoffは優れた言語学者です。これを彼のところへ持っていっていただけませんか――もちろん、報酬は出します。Light's Hope Chapel――彼は今そこにいます。Eastern Plaguelandsの東部のずっと奥です。", "この苦難の時に光があなたを導きますように、{class}。闇と絶望のただ中にあるこの希望の灯火へ、どのような用件でいらしたのですか?", "これは……これはあなたが持ってきてくれた、とても特別な本だ。この場合の「特別」が「唯一無二で、おそらくは啓発的」という意味だと言ってやりたいところだが、それはまだ分からん。\n\n「Ooooooo?」まともな頭の持ち主が、こんなものを思いつくものか?\n\nさて、Gregorが話していたこのUmbranseという者のことは聞いたことがある。だからこれには意味がないわけではない。解読には全力を尽くそう。あなたには……どうかこれを。Argent Dawnからの心ばかりの品だ。ここにいる間に、ほかにも手を貸してもらえることがあるかもしれん。", 0x5cc33030, 0x06c37253, 0x462ef41a, 0x8979a1af, 0x24397ac7, "....." },
  [6031] = { "Runecloth", "Timbermaw HoldのMeiloshにRuneclothを30枚持って行って下さい。", "Timbermawで、私たちは満ち足りています。見知らぬ者は好みません。それは良いのですが、取引のためには良くありません。\n\nこの前、ナイトエルフの数少ない友人がTimbermawへやって来たんです。彼女はRuneclothの外套を羽織っていました。Runeclothは私たちにとって貴重なのですが、あまりに外套が素晴らしいものだから、一族の者がRuneclothの衣服を作ってほしがって。\n\nRuneclothをくれませんか?　充分持ってきてくれたら、代わりに何かあげましょう。", "runeclothは持っているか? 我が同胞たちはrunecloth製の品をもっと欲しがっているのだ!", "ああ、Runeclothを持ってきてくれたのですね。なんて素晴らしい素材なんでしょう!\n\nありがとう、{name}。あなたは本当の友達です。これを代わりに受け取って下さい。", 0x444397b6, 0xe7dafac5, 0x6b70b9c1, 0x6bdbfa90, 0xa3d5c17a, "....." },
  [6032] = { "神聖な布", "Timbermaw HoldのMeiloshにMooncloth 2枚を渡して下さい。", "Timbermawの者はruneclothの感触が大好きなのですが、あれは神聖なものではありません。しかしmoonclothは違います。\n\n聖なる布を少し持ってきて下さったら、秘密の製造技術をお教えしましょう。", "moonclothは持ってきたか、{name}?", "おお、とても良いですね。このmoonclothは我々の神聖な衣服を作るために使います。ありがとうございます、{name}。それではお教えしましょう。", 0x880d6d08, 0x538dba9c, 0x24f5a2c1, 0x92295359, 0x1ecc185c, "....." },
  [6041] = { "Smokeyが歌うと、暴れたくなる", "Light's Hopeの北西にあるPlaguewoodへ行く。各建物の中に仕掛けられたMark of DetonationでSmokey's Special Compoundを使い、Scourge Structuresを$N1棟破壊する。SmokeyはZigguratsとSlaughterhousesに印をつけておいた。\n\n爆弾を仕掛けたら建物から出て、自分の仕事ぶりに見とれるといい。\n\nところで、Smokey's Special Compoundはかなり……不安定だ。", "君が材料を集めてる間に、うちの連中に、取り壊さなきゃならないScourgeの建物に印をつけさせておいた。\n\n段取りはこうだ。俺の特製の調合物を十本渡す。君はそれをPlaguewoodへ持って行って、俺が爆破用に印をつけさせたScourgeの建造物の中に仕掛けてくるんだ。\n\n<Smokeyが指を鳴らす。>\n\nパチン！それだけのことさ。", "special compoundをあと数本作れるだけの材料が残ってるんだ。もっと必要ならこのSmokeyに言ってくれ。", "記憶よりずいぶん黒くなったな。いい感じの見た目になってるぜ。『高性能爆弾で焦がされました』って顔だ。\n\n<Smokeyは笑う。>\n\nともかく! これがお前の取り分だ。火傷を和らげる足しに、ちょっとおまけもつけておいたぜ。", 0x10218999, 0x03dc765e, 0x287b84cb, 0x193414ea, 0x4b93f9f8, "....." },
  [6042] = { "Un-Lifeのささやかな悩み", "Noxious Plaguebatsを$N1体とMonstrous Plaguebatsを$N2体倒す。終わったらNathanos Blightcallerのところへ戻って下さい。", "この農場から二歩も出れば、あの忌々しいコウモリどもに出くわす。私は猟犬を連れ出してScourgeを屠りたいのだ。汚らわしい薄汚いコウモリどもにつきまとわれずにな。言うまでもなく、私には毎日毎日ただ無心にコウモリを殺すより、ましな時間の使い道がある。だが、お前にはない。\n\nなんだ？訓練だと？これがお前の訓練だ！さっさと私の前から消えろ。あの翼の生えた悪魔どもを相当な数殺すまで戻ってくるな。私を失望させるなよ。", "もっとひどいことになっていたかもしれんぞ。コウモリの糞を集めさせることだってできたのだからな。\n\n<Nathanosは考え込むようにあなたを見つめる。>\n\nふむ……おい! ちょっと待て。どこへ行く?", "ちょっとした怒りと激情でどれほどのことが成し遂げられるか、信じられないほどだ。", 0x7e356812, 0xa0a21001, 0x73cb40be, 0xfdc24c18, 0xc1f870dd, "....." },
  [6061] = { "動物馴らし", "Adult Plainstriderの調教にTaming Rodを使って下さい。スキルを磨き、Bloodhoof VillageのYaw SharpmaneにTaming Rodを返却して下さい。", "トーレンとして、強大な生き物と戦うことで祖先の伝統に従うことは大切だ。これらの生き物を打ち負かすことで、我々はその魂を取り込み、Earthmotherにより近づくことができる。\n\n同じように、獣を手なずけて共に戦わせることは、我々を取り巻く自然と一つになる助けとなる。いずれお前は、自分の選んだ獣を手なずけられるようになるだろう。だが何事にも修練が必要で、お前には学ぶことが多い。まずはこのtaming rodを持っていけ。adult plainstriderを手なずけるのだ。", "技を磨け、{name}。成体のplainstriderを手なずけるのだ。", "Earthmotherからの印が現れたよ。よくやった。", 0xecd97a9a, 0x7e3b8d01, 0x02e5038d, 0xaa8943a4, 0xe57154b4, "....." },
  [6062] = { "動物馴らし", "Dire Mottled Boarの調教にTaming Rodを使って下さい。スキルを磨き、Razor HillのThotarにTaming Rodを返却して下さい。", "自然に対して己の権威を振るうことは称賛に値する技だ。ハンターとして、お前は自分の選んだあらゆる生き物に宿る力と勢いを使いこなせるよう努めねばならない。\n\n動物を支配するのは容易なことではない。強い決意をもって取り組まねばならない務めだ。\n\n最初の課題として、このtaming rodを持っていき、dire mottled boarを手なずけろ。Razor Hillのすぐ近くで見つかるはずだ。boarを傍らに置いて戦いで腕を磨き、それから私のもとへ戻れ。", "幸運を祈る、若きハンターよ。", "よくやったぞ、{name}。いつでも次の課題に取りかかれるだろう。", 0xecd97a9a, 0xbdba9086, 0x62c476e9, 0xd07d6bc7, 0xac1c2d65, "....." },
  [6063] = { "動物馴らし", "Webwood Lurkerの調教にTaming Rodを使って下さい。スキルを磨き、DolanaarのDazalarにTaming Rodを返却して下さい。", "ハンターとして、自らの手に握る責任を忘れてはならない。自然は我々の望みに従わせられる力ではない。敬い、自らの存在よりも強いものとして認めるべき力なのだ。\n\n{name}、動物を手なずけて相棒にする能力を得る前に、このことを理解していると証明せねばならない。\n\n最初の務めは、このtaming rodを持っていくことだ。これでwebwood lurkerを手なずけられる。手なずけて、ハンターとしての腕を磨け。", "あなたは学んでいくでしょう、{name}。そしていつの日か、偉大なハンターになるのです。", "よくできたぞ、{name}! 君は本当に飲み込みが早いな。", 0xecd97a9a, 0x72db5042, 0x39ad25e9, 0x407acae4, 0x7f1a8496, "....." },
  [6064] = { "獣を手なずける", "Taming Rodを使ってLarge Crag Boarを手なずける。技を練習したら、KharanosのGrif WildheartにTaming Rodを返す。", "やあ、若いの！ で、自分のペットを手に入れる方法を知りたいってわけかい？\n\nよし、始めようか。狩りとなりゃ、装備より大事なもんはないんだが、俺の新しいShrapnel Blasterの話はまた今度にしよう。今は、お前さんが興味津々に違いないことに集中しようじゃないか。ペットだ！\n\n一番の学び方は、いろんな生き物を相棒として試してみて、何が気に入るか確かめることさ。ってことで、大きなcrag boarを見つけて、taming rodを使って手なずけてみな。", "心配するな、若いの! 1匹に決める前に、いくつか試してみられるさ。", "分かってる、分かってるよ。次は何かって気になってるんだろ?!", 0xecd97a9a, 0x19250c04, 0x4bb3619f, 0x2a062314, 0x7fe27a35, ".....", nil, nil, 0x1065c71d, nil, nil },
  [6065] = { "ハンターの道", "Bloodhoof VillageにいるYaw Sharpmaneと話して下さい。", "こんにちは、若きハンターよ。獣を扱い、相棒として鍛えられるだけの腕はありそうだな。\n\nBloodhoof VillageのYaw Sharpmaneに会うといい。自分のペットを得る道へ導いてくれるだろう。", nil, "そうだ、お前はもう準備ができていると信じているぞ……", 0xe59cef47, 0x44416cc1, 0xcdcddc29, nil, 0x97654cb4, "...m." },
  [6066] = { "ハンターの道", "Bloodhoof VillageにいるYaw Sharpmaneと話して下さい。", "こんにちは、若きハンターよ。獣を扱い、相棒として鍛えられるだけの腕はありそうだな。\n\nBloodhoof VillageのYaw Sharpmaneに会うといい。自分のペットを得る道へ導いてくれるだろう。", nil, "よし、準備はできているな。", 0xe59cef47, 0x44416cc1, 0xcdcddc29, nil, 0x97654cb4, "...m." },
  [6067] = { "ハンターの道", "Bloodhoof VillageにいるYaw Sharpmaneと話して下さい。", "こんにちは、若きハンターよ。獣を扱い、相棒として鍛えられるだけの腕はありそうだな。\n\nBloodhoof VillageのYaw Sharpmaneに会うといい。自分のペットを得る道へ導いてくれるだろう。", nil, "よし、準備はできているな。", 0xe59cef47, 0x44416cc1, 0xcdcddc29, nil, 0x97654cb4, "...m." },
  [6068] = { "ハンターの道", "Razor HillにいるThotarと話して下さい。", "こんにちは、若きハンターよ。獣を扱い、相棒として鍛えられるだけの腕はありそうだな。\n\nRazor HillのThotarに会うといい。自分のペットを得る道へ導いてくれるだろう。", nil, "よし、訓練を始めよう。", 0xe59cef47, 0xccc0cc0b, 0xa19701ce, nil, 0x2462bb57, "...m." },
  [6069] = { "ハンターの道", "Razor HillにいるThotarと話して下さい。", "こんにちは、若きハンターよ。獣を扱い、相棒として鍛えられるだけの腕はありそうだな。\n\nRazor HillのThotarに会うといい。自分のペットを得る道へ導いてくれるだろう。", nil, "よし、訓練を始めよう。", 0xe59cef47, 0xccc0cc0b, 0xa19701ce, nil, 0x136d5bec, "...m." },
  [6070] = { "ハンターの道", "Razor HillにいるThotarと話して下さい。", "こんにちは、若きハンターよ。獣を扱い、相棒として鍛えられるだけの腕はありそうだな。\n\nRazor HillのThotarに会うといい。自分のペットを得る道へ導いてくれるだろう。", nil, "よし、訓練を始めよう。", 0xe59cef47, 0xccc0cc0b, 0xa19701ce, nil, 0x2462bb57, "...m." },
  [6071] = { "ハンターの道", "DolanaarのDazalarと話す。", "こんにちは、若きハンターよ。あなたは獣を扱い、相棒として訓練できるだけの腕を持っているように見えます。\n\nDolanaarのDazalarに会わなければなりません。彼があなたを自分のペットを手に入れる道へと導いてくれるでしょう。", nil, "そうだ、時が来たぞ、{class}。", 0xe59cef47, 0xacb77771, 0x57c4b6af, nil, 0xca92f25f, "...m." },
  [6072] = { "ハンターの道", "DolanaarのDazalarと話す。", "こんにちは、若きハンターよ。あなたは獣を扱い、相棒として訓練できるだけの腕を持っているように見えます。\n\nDolanaarのDazalarに会わなければなりません。彼があなたを自分のペットを手に入れる道へと導いてくれるでしょう。", nil, "そうだな、時が来たと思う……", 0xe59cef47, 0xacb77771, 0x57c4b6af, nil, 0x467a6a72, "...m." },
  [6073] = { "ハンターの道", "DolanaarのDazalarと話す。", "こんにちは、若きハンターよ。あなたは獣を扱い、相棒として訓練できるだけの腕を持っているように見えます。\n\nDolanaarのDazalarに会わなければなりません。彼があなたを自分のペットを手に入れる道へと導いてくれるでしょう。", nil, "そうだ、時が来たぞ、{class}。", 0xe59cef47, 0xacb77771, 0x57c4b6af, nil, 0xca92f25f, "...m." },
  [6074] = { "ハンターの道", "KharanosのGrif Wildheartと話す。", "やあ、若きハンターよ。お前さんは獣を扱い、相棒として訓練できるだけの腕を持っているように見えるな。\n\nKharanosのGrif Wildheartに会わなきゃならんぞ。彼がお前さんを自分のペットを手に入れる道へと導いてくれるだろう。", nil, "ああ、お前も準備ができていると思うぞ……", 0xe59cef47, 0x7378e497, 0x892ec4fe, nil, 0xc84c7dad, "...m." },
  [6075] = { "ハンターの道", "KharanosのGrif Wildheartと話す。", "やあ、若きハンターよ。お前さんは獣を扱い、相棒として訓練できるだけの腕を持っているように見えるな。\n\nKharanosのGrif Wildheartに会わなきゃならんぞ。彼がお前さんを自分のペットを手に入れる道へと導いてくれるだろう。", nil, "ああ、お前も準備ができていると思うぞ……", 0xe59cef47, 0x7378e497, 0x892ec4fe, nil, 0xc84c7dad, "...m." },
  [6076] = { "ハンターの道", "KharanosのGrif Wildheartと話す。", "やあ、若きハンターよ。お前さんは獣を扱い、相棒として訓練できるだけの腕を持っているように見えるな。\n\nKharanosのGrif Wildheartに会わなきゃならんぞ。彼がお前さんを自分のペットを手に入れる道へと導いてくれるだろう。", nil, "ああ、お前も準備ができていると思うぞ……", 0xe59cef47, 0x7378e497, 0x892ec4fe, nil, 0xc84c7dad, "...m." },
  [6081] = { "獣の訓練", "OrgrimmarのOrmak Grimshotと話して下さい。", "お前はペットを手なずける力を得たが、それを鍛える技も身につけねばならない。\n\nOrgrimmarへ行け。そこで我らの最も尊敬されるハンターの一人、Ormak Grimshotと話すのだ。新しいペットを鍛える能力を授けてくれるだろう。Hall of the Braveの近くにいる。\n\n幸運を祈る、{name}。", nil, "若きハンターか。よろしい、ペットを訓練し導くために必要な技を授けよう。ペットに新たな能力を教えられるようになるだけでなく、餌を与えることも、戦いで倒れたときに蘇生させることもできるようになる。\n\nさあ、行け、ハンターよ。またいずれ話すとしよう。", 0xdbeedc0e, 0x2fb3c65d, 0x4f2112ec, nil, 0x455cd3ee, "...m." },
  [6082] = { "動物馴らし", "Armored Scorpidの調教にTaming Rodを使って下さい。スキルを磨き、Razor HillのThotarにTaming Rodを返却して下さい。", "最後に手なずけるべき生き物は、お前が見習うべきもの、armored scorpidだ。素早く、自信をもって攻撃する。このような力を支配することこそ、ハンターとしてのお前の宿命だ。\n\n戻ってきたら、自分の選んだ動物を手なずけるのに必要な技を授けよう。その生き物はお前の意のままになる。お前の支配下で、ペットはお前と共に経験を積む。呼び出し方と、好きな時に帰す方法も教えてやろう。", "scorpidは手なずけられたか?", "お前は私が教えられることをすべて学んだ、{name}。ここで学んだことを携えて、自分自身のペットを選ぶときだ。\n\nさあ、受け取れ、{name}。これよりお前に、獣を手なずける力と、思うままに呼び出し、送り返す力を与えよう。新たな技を誇りとともに使え。お前はそれを勝ち取ったのだ。", 0xecd97a9a, 0x2768b0fc, 0x861877c1, 0x5354bf2d, 0xf50c040e, "....." },
  [6083] = { "動物馴らし", "Surf Crawlerの調教にTaming Rodを使って下さい。スキルを磨き、Razor HillのThotarにTaming Rodを返却して下さい。", "ペットがライバルに対してもたらす利点はよく知られている、{name}。他の生き物を支配すれば、それは自分自身の力を増すことになる。ペットはお前自身の延長とならねばならない。\n\n次の課題では陸から目を転じてもらう。次の生き物は沖合の海にいる。Sen'jin Villageの向かい、Echo Islesの近くで、surf crawlerと呼ばれる元気なカニを探せ。taming rodを使って手なずけ、腕を磨くのだ。", "ペットを思い通りに操る技術を身につけるには、練習が必要だ。surf crawlerは手なずけたか?", "飲み込みが早いな、{name}。よくやったぞ。", 0xecd97a9a, 0x79ae328f, 0x2fe7f794, 0x317634b5, 0x65d417ae, "....." },
  [6084] = { "獣を手なずける", "Taming Rodを使ってSnow Leopardを手なずける。技を練習したら、KharanosのGrif Wildheartのところへ戻る。", "あのcrag boarはかなりごついからな。もうちょっと繊細なやつがいいか？ よし、それならぴったりのがあるぞ。ここから南東に、snow leopardって呼ばれる大きな白い猫がいる。見事な彫刻を施したライフルと同じで、美しい見た目の裏には、凄まじいダメージを与えられる強い戦士が隠れてるんだ。お前さんが手なずけた猪より、ずっと身軽で素早いと分かるだろうよ。\n\nこのtaming rodを持っていって、snow leopardが気に入るか試してみな。", "snow leopardはどうだった、{name}?", "お前が十分に学んだと感じたら、好きなペットを選べる力を授けてやろう。", 0xecd97a9a, 0x71c04a53, 0x18410c9d, 0x00a7c273, 0xa900ecfd, "....." },
  [6085] = { "獣を手なずける", "Taming Rodを使ってIce Claw Bearを手なずける。技を練習したら、KharanosのGrif WildheartにTaming Rodを返す。", "もしかしたら、腕力だけが取り柄みたいな生き物のほうがいいかもな。ice claw bearは、お前さんみたいな駆け出しのハンターにはもってこいの相棒で、Kharanosの東にいる。ほら、taming rodだ。この動物をペットとして試してみて、気に入るか確かめてみな！\n\n戻ってきたら、好きな動物を手なずけるのに必要な技を教えてやろう。その生き物はお前さんが立ち向かう試練に一緒に立ち向かい、お前さんと一緒に経験を積んでいく。好きな時に呼び出したり帰したりする方法も教えてやるよ。", "ice claw bearはもう手なずけたか?", "ほらよ、{name}。これで獣を手なずけ、好きなときに呼び出したり帰したりする力を授けてやる。\n\n良い、忠実なペットを見つけて、狩りを楽しめよ!", 0xecd97a9a, 0xe2aae2d4, 0x732759ee, 0x687f27e9, 0x427d0b77, "....." },
  [6086] = { "獣を訓練する", "IronforgeのBelia Thundergraniteと話す。", "{name}、お前さんはもうペットを手なずける力を持ってる。だが、そいつを訓練する技も身につけなきゃならん。\n\nIronforgeへ行って、Hall of Armsを探しな。そこで我らの最も尊敬される動物の調教師の一人、Belia Thundergraniteと話すんだ。新しいペットを訓練する力を授けてくれるから、さっさと行きな、若いの！\n\nBeliaは気さくな人だから、認めてもらうのに苦労はないはずだ。幸運を祈るよ、{name}。", nil, "新入りか、ん? 立派な{class}への道を歩んでいるようだな。\n\nよし、ペットを訓練し導くのに必要な技能を授けてやろう。ペットに新しい能力を教えられるだけでなく、ペットに餌をやったり、戦いで倒れたときに蘇生させたりもできるようになる。\n\n新しいペットの力を最大限に引き出す鍵は、ペットを尊重し大切に扱うことだと覚えておけ。そうすれば、ペットはお前の最も忠実な友になる。", 0xdbeedc0e, 0x4c05bef3, 0x77988ad7, nil, 0x760bb7bd, "...m.", nil, nil, 0xf137678c, nil, nil },
  [6087] = { "動物馴らし", "Prairie Stalkerの調教にTaming Rodを使って下さい。スキルを磨き、Bloodhoof VillageのYaw SharpmaneにTaming Rodを返却して下さい。", "お前は燃えるような魂を持っているな、ハンターよ。次の挑戦を今か今かと待っている。\n\n次の務めは、prairie stalkerとして知られる狼を相棒にすることだ。この生き物は素早く恐れを知らない。この獣をペットにするなら、お前もその資質を身につけねばならない。\n\n戦いの中で、お前とペットがどうやって一つのチームになるかを学ぶだろう。最後には、筋肉と筋肉が一体となって、一つになって戦わねばならない。\n\nこれがtaming rodだ、{name}。prairie stalkerを手なずけ、腕を磨け。", "prairie stalkerは見つかったか?", "よし……Earthmotherは君が次の訓練にとりかかれると思し召しだ。", 0xecd97a9a, 0x4c6a673d, 0xcbcfeb92, 0xf06164c3, 0x0370a830, "....." },
  [6088] = { "動物馴らし", "Swoopの調教にTaming Rodを使って下さい。スキルを磨き、Bloodhoof VillageのYaw SharpmaneにTaming Rodを返却して下さい。", "最後の務めとして、空に棲む生き物を手なずけてもらう。swoopは手強い相手だが、味方にすれば、その鋭い攻撃と威圧的な存在感を手に入れられるだろう。\n\nEarthmotherの御心により、戻ってきた時には、自分の選んだ動物を相棒として手なずけるのに必要な技を授けよう。その生き物はお前が直面する試練に共に立ち向かい、お前と共に経験を積む。呼び出し方と、好きな時に帰す方法も教えてやろう。", "もうすぐ準備が整うだろう、{name}。", "お前は私が教えられることをすべて学んだ、{name}。ペットを選ぶにあたり、Earthmotherの祝福がお前を導かんことを。\n\nさあ、受け取れ、{name}。これよりお前に、獣を手なずける力と、思うままに呼び出し、送り返す力を与えよう。新たな技を誇りとともに使い、Earthmotherに敬意を示せ。", 0xecd97a9a, 0x64c2eb6a, 0x3d7058f9, 0x3bda1794, 0x834b33ff, "....." },
  [6089] = { "獣の訓練", "Thunder BluffのHunter RiseにいるHolt Thunderhornと話して下さい。", "お前はペットを手なずける力を得たが、それを鍛える技も身につけねばならない。\n\nThunder Bluffへ行け。そこで我らの最も尊敬されるハンターの一人、Holt Thunderhornと話すのだ。お前がふさわしいと認めれば、新しいペットを鍛える能力を授けてくれるだろう。\n\nHoltはAzerothで最も強大で恐れられる獣たちを打ち負かし、自らも多くの強い生き物を従えている。Earthmotherとの絆も強く、彼から学べることは多い。幸運を祈る、{name}。", nil, "若き{class}か。よろしい、ペットを訓練し導くために必要な技を授けることができる。ペットに新たな能力を教えられるようになるだけでなく、餌を与えることも、戦いで倒れたときに蘇生させることもできるようになる。\n\nさあ、行くがいい。Earthmotherがお前の道を導かんことを。またいずれ話すとしよう。", 0xdbeedc0e, 0x9f1dae7e, 0xc78eab1d, nil, 0x104e785e, "...m." },
  [6101] = { "獣を手なずける", "Taming Rodを使ってNightsaber Stalkerを手なずける。技を練習したら、DolanaarのDazalarにTaming Rodを返す。", "自然の多様さは、頼りにできるものです、{name}。決して同じままでいないという点で、それは予測できるのです。自然は常に変わり続けています。\n\n私が与える課題は、あなたが相棒として選ぶかもしれない生き物たちの大きな違いを見て、それを理解する助けになるでしょう。\n\nこのtaming rodを持っていき、南にいるnightsaber stalkerを手なずけてください。ハンターとしての技を磨くのです。そうすれば、自然の似ているところと違うところが分かり始めるでしょう。", "自然と己との調和を理解することは、すべてのナイトエルフにとっての生き方なのです。", "お前の献身と、私が教えたことを理解したことが分かったぞ、{name}。", 0xecd97a9a, 0xd54ea322, 0x4cf39634, 0x2bb052d9, 0xe3639023, "....." },
  [6102] = { "獣を手なずける", "Taming Rodを使ってStrigid Screecherを手なずける。技を練習したら、DolanaarのDazalarにTaming Rodを返す。", "あなたは地上に棲む生き物を二匹手なずけました。今度は空を舞う生き物を手なずけなければなりません。taming rodを使って、ここから西にいるstrigid screecherを手なずけてください。この力強いフクロウをそばに置いて、技を磨くのです。\n\n戻ってきたら、あなたが相棒に選んだ動物を手なずけるのに必要な技を授けましょう。その生き物はあなたが立ち向かう試練に共に立ち向かい、あなたと共に経験を積んでいきます。望む時に呼び出したり帰したりする方法も教えましょう。", "あなたの成し遂げたことを誇りに思いますよ、{name}。私が与えた最後の課題は終わりましたか?", "私が教えられることはすべて学んだな、{name}。もう1つ助言をさせてくれ。最初のペットを選ぶときは慎重にな。陸の生き物か、水の生き物か、それとも空の生き物か? 何を選ぶにせよ、間違いなく、ペットはこれから長い間お前と共にいることになる。\n\nさあ、{name}。これで獣を手なずけ、思うままに呼び出したり帰したりする力を授けよう。新たな技能を誇りを持って使え。お前が勝ち取ったものだ。", 0xecd97a9a, 0xe53bb451, 0x3445b668, 0xc9470946, 0xdeb475c1, "....." },
  [6103] = { "獣を訓練する", "DarnassusのCenarion EnclaveにいるJocasteと話す。", "あなたはもうペットを手なずける力を持っています。ですが、それを訓練する技も身につけなければなりません。\n\nDarnassusへ向かってください。そこで私たちの最も尊敬されるハンターの一人、Jocasteと話すのです。新しいペットを訓練する力を授けてくれますから、急いでください。\n\nJocasteは厳しく見えるかもしれませんが、また一人ハンターが腕を上げてくるのを見るのをいつも喜んでいます。敬意をもって接すれば、彼女も同じように応えてくれるでしょう。幸運を、{name}。", nil, "駆け出しのハンターだな。よし、ペットを訓練し導くのに必要な技能を授けよう。ペットに新しい能力を教えられるだけでなく、ペットに餌をやったり、戦いで倒れたときに蘇生させたりもできるようになる。\n\n覚えておけ、{name}、常に調和を重んじ、周りの自然に畏敬の念を持って生きるのだ。さあ、行け。また後日話そう。", 0xdbeedc0e, 0x6e901431, 0x3d135ae6, nil, 0xce7253c1, "...m." },
  [6121] = { "修行再び", "Moongladeへ行き、village of NighthavenのDendrite Starblazeと話して下さい。", "毒と我々がドルイドとして毒に打ち勝ってきた力について、あなたはもう習得する準備ができていますね、{name}。最も汚れた毒でさえ、ほんのちょっとした呪文で浄化する能力をCenariusは我々に授けて下さいました。この贈り物を軽々しく扱ってはなりません……そして、この修行を確実なものにするには、素人がするように中毒の効力について取り組まねばならないでしょう。\n\nMoongladeへ行き、Dendrite Starblazeと話して下さい。彼は修行を始めるために、あなたの到着を待っていますよ。", nil, "ご機嫌よう、若き{class}。毒の治療について熱心に学ぶために、準備してきてくれたことを嬉しく思う。\n\n過去、ほとんどのドルイドはあらかじめ用意された試練を越えてきたが、あなたがやるべき事はそういったことではない。Auberdineで中毒を起こす動物が多く発生し、村では治療しきれなくなっているという。代表者がMoongladeへ助けを求めてきたゆえ、我々はあなたを派遣しようと思う。これは練習ではないぞ……この仕事はまったくの現実なのだ。それを覚えておくことだ。", 0xe3814355, 0xb25e3d68, 0x738324f8, nil, 0xe3b1d128, "...m." },
  [6122] = { "主要因", "Empty Cliffspring Falls Samplerを使い、滝のそばにある洞窟の入り口から水のサンプルを採取して下さい。\n\nDarkshoreのAuberdineにいるAlanndarian NightsongにFilled Cliffspring Falls Samplerを届けて下さい。", "DarkshoreのCliffspring Fallsは、あの地域で飲み水の主要な源泉として使われている。そして今、地元の動物群、特に鹿へ害を及ぼしている毒の主要因は滝だと私は踏んでいる。この試料採取装置を使って、洞窟の入り口から水を採取するのだ。洞窟の中には危険なnagaが住んでいるから、充分注意するのだぞ。\n\nいっぱいになったら、AuberdineのAlanndarian Nightsongへ届けよ。彼女は我々に助けを求めた一人だ、彼女とともに病に取り組めるだろう。", "あなたがMoongladeのCenarion Circleから派遣された方ですか? 素晴らしいわ! かわいそうな鹿たちのことで、ここはかなりの危機に陥っているんです。どんな助けでもありがたいわ。\n\nDendrite Starblazeが言っていた水のサンプルはお持ちですか? 一緒に治療法を研究できるように、あなたが1つ採取してくると知らせてくれたんです……", "Eluneにかけて、この水は最低よ!　鹿たちが病気になるのも当然だわ。\n\n何かが水を汚染してる。そして、順々にDarkshoreの地下水すべてを腐敗させたのね。病気の鹿は、川のそばだけじゃなく地域全体で発見されてる。恐らくこの水が病気拡大の主な原因だけど、別の何かがここで作用してるようね。\n\nこの水、信じる信じないはともかく、治療法を考えるのに役立ちそう。この水について調べるんだけど、治療法を練るのにいくつか物が必要ね……", 0xfe91905d, 0xed0bc128, 0xe6b38f20, 0x7f300676, 0xc7a9f8eb, "....." },
  [6123] = { "薬の素材集め", "Earthroot5個とLunar Funguses12個を集め、AuberdineのAlanndarian Nightsongに渡して下さい。そうすれば彼女は治療用軟膏を作れるでしょう。", "鹿たちのために作ろうとしている治療用軟膏のベースとして、この水が役立ちそうね。薬効成分としてはearthrootが必要。Herbalistたちなら見つけ方を知っているから、もしあなたが薬草学に明るくないなら、手助けしてくれる人を探さなきゃならない。\n\n最後に効力のために、lunar fungusが要る。lunar fungal bloomを見つけるのはすごく簡単。ここからちょうど東へ行ったところの洞窟の周り一帯にあるから。Moonkinが洞窟の中に住んでるんだけど、彼ら最近気が短くなっているから、気をつけてね。", "軟膏を作るのに必要な材料は手に入りましたか? 鹿たちは自然には良くならないので、急いで助けてあげないと!", "これはいいわ、{name}。軟膏をたっぷり作るのにありあまるほど充分あるわね。少なくとも、現状をより良く変えるくらい充分に。\n\n毒の治療薬を作るのは、とても難しい場合がある。それぞれの毒に対して、特定の解毒剤を必要とすることがたまにあるからね。解毒剤が正しい成分であるか心配しなくていいから、思うがままに毒を治療できると想像して。\n\nさあ、やってみましょう!", 0xc0a4b4dc, 0x14a92d63, 0xd43adcc8, 0xd5399fb4, 0x0d585714, "....." },
  [6124] = { "病気の治療", "DarkshoreにいるSickly Deer10頭にCurative Animal Salveを使って下さい。そうすると彼らを治療できます。Sickly Deerは、Auberdineの北からCliffspring Riverの南にかけて、Ashenvaleとの境界に至る南Darkshoreまで報告されています。", "あなたが持ってきてくれた試薬で、たっぷり10回分の治療用軟膏が作れたわ、{name}。もっと軟膏を作るために私が村で働いているあいだ、あなたは私たちが有利に事を進められるよう協力してちょうだい。Darkshore一帯は病気の鹿だらけ。この軟膏を使って、彼らの病を治療してちょうだい。\n\nこれが終わったら、MoongladeのDendrite Starblazeはあなたと話がしたいと思うはず。きっとね。あそこのCenarion Circleに、私たちが感謝していると伝えて……それと、あなたに直接言わせて。おかげさまで助かったわ、ありがとう。", "AuberdineのAlanndarian Nightsongに頼まれたことは終わりましたか? それが済まない限り、あなたの仕事は完了しません。", "Darkshoreの病んだ鹿の面倒をよく見て下さった。あの鹿たちは何も知らず、大地に広がる腐敗と汚染の犠牲となったのだ。Darnassusに、その脅威を受け入れることを選んだ者がいる……そして、その兆候を無視した者がいたのだ。あなただけは、目の前の事実に対して見て見ぬふりをするような者になってほしくない。\n\n何はともあれ、あなたはCenarion Circleと自然の友として値することを示してくれた。そのしるしとして、これを受け取ってくれ。", 0x0116fddd, 0x20fba3fe, 0xbc2e713b, 0xb12ec810, 0x848c8bee, "....." },
  [6125] = { "毒を支配する力", "DarnassusのCenarion EnclaveにいるMathrengyl Bearwalkerのところへ戻って下さい。", "精神的援助の見返りなしに毒を治癒することの意味を学んだのだな。しかしこれは覚えておいてほしい。あなたは毒を支配する新たな力をすぐ得られるが、他人は毒の苦痛に耐えなくてはならないということを。\n\n今すぐDarnassusのMathrengyl Bearwalkerのところへ戻るのだ、{name}。課せられた修行を理解している生徒に教えるための大切な呪文を、彼は間違いなく知っている。\n\nさらば、若きドルイドよ。また語り合おう。", nil, "よくぞ戻られました、私はあなたがここを離れてから修行の進み具合を追っていました。Auberdineでの難問について聞き及び、驚いたことを認めねばなりませんね。環境へあのような毒が侵入することこそ最も均衡を揺るがすものですから、さらなる詳しい調査が必要です。\n\nあなたは苦難の中にありながら、徳をもって己を律しました。毒を支配する不変の力を贈るより他に、良い方法はありません。上手に使うのですよ、{name}……上手に使うのです。", 0xfaefb521, 0x6562a80b, 0xf6d4f854, nil, 0x02ded2c7, "...m.", nil, nil, 0xe5d51b88, nil, nil },
  [6126] = { "修行再び", "Moongladeへ行き、village of NighthavenのDendrite Starblazeと話して下さい。", "毒と我々がドルイドとして毒に打ち勝ってきた力について、あなたはもう習得する準備ができていますね、{name}。最も汚れた毒でさえ、ほんのちょっとした呪文で浄化する能力をCenariusは我々に授けて下さいました。この贈り物を軽々しく扱ってはなりません……そして、この修行を確実なものにするには、素人がするように中毒の効力について取り組まねばならないでしょう。\n\nMoongladeへ行き、Dendrite Starblazeと話して下さい。彼は修行を始めるために、あなたの到着を待っていますよ。", nil, "ご機嫌よう、若き{class}。毒の治療について熱心に学ぶために、準備してきてくれたことを嬉しく思う。\n\n過去、ほとんどのドルイドはあらかじめ用意された試練を越えてきたが、あなたがやるべき事はそういったことではない。BarrensのCrossroadsで中毒を起こす動物が多く発生し、抑えられなくなっているという。そこの誰かがMoongladeへ助けを求めてきたゆえ、我々はあなたを派遣しようと思う。これは練習ではないぞ……この仕事はまったくの現実なのだ。それを覚えておくことだ。", 0xe3814355, 0xb25e3d68, 0x738324f8, nil, 0x0d09f282, "...m." },
  [6127] = { "主要因", "Empty Dreadmist Peak Samplerを使い、頂上の水たまりから水のサンプルを採取して下さい。\n\nBarrensのCrossroadsにいるTonga RunetotemにFilled Dreadmist Peak Samplerを届けて下さい。", "汚染拡大の発生源として、Crossroadsの北西にあるDreadmist Peakが恐らく第一候補となろう。あの空高くそびえる峰には、天候の型に影響する水たまりがあるのだ。あそこで今、悪魔崇拝集団のBurning Bladeが水を汚染しているのではないかと私は踏んでいる。\n\nこの試料採取装置を使って、頂上の水たまりから水を採取するのだ。いっぱいになったら、CrossroadsのTonga Runetotemへ届けよ。彼は我々に助けを求めた一人だ、彼とともに病に取り組めるだろう。", "あなたがMoongladeのCenarion Circleから派遣された方ですね? これは我々にとってまさに幸運です! 北Barrensをさまよう病んだガゼルたちに調和を取り戻そうとしているのですが、行き詰まっているのです。どんな助けでもありがたく思います。\n\nDendrite Starblazeが言っていた水のサンプルはお持ちですか? 一緒に治療法を研究できるように、あなたが1つ採取してくると知らせてくれたのです……", "先祖にかけて、この水は胸くそ悪くなるほど最悪だ!　ガゼルたちが病気になるのも当然だな。\n\n何かが水を汚染してる。そして、順番に北Barrensの生態系を破壊し始めたんだ。病気のガゼルはここの東西道路の北でみかける。恐らくこの水が病気拡大の主な原因なんだが、別の何かがここで作用してるな。\n\nこの水、信じる信じないはともかく、治療法を考えるのに役立つぞ。この水について調べるんだが、治療法を練るのにいくつか物が必要だ……", 0xfe91905d, 0xc7e4ec6f, 0x35e50bed, 0x7afc3fe5, 0xa5296c0c, "....." },
  [6128] = { "薬の素材集め", "EarthrootとKodo Hornをそれぞれ5つ集め、CrossroadsのTonga Runetotemに渡して下さい。そうすれば彼は治療用軟膏を作れるでしょう。", "ガゼルたちのために作ろうとしている治療用軟膏のベースとして、この水が役立つだろう。薬効成分としてはearthrootが必要だ。Herbalistたちなら見つけ方を知っているから、もし君が薬草学に明るくないなら、手助けしてくれる人を探さなきゃならんよ。\n\n最後に効力のために、Kodo Hornが要る。ただし粉々のかけらや破片ではだめだ。君に扱えるKodoはBarrensの北部をうろついてるから、均衡の大義のために、何頭か倒して角を持ってきてくれ。", "軟膏を作るのに必要な材料は手に入りましたか? ガゼルたちは自然には良くなりませんから、救うためにぐずぐずしてはいられません!", "これはいい、{name}。軟膏をたっぷり作るのにありあまるほど充分ある。少なくとも、現状をより良く変えるくらい充分にね。\n\n毒の治療薬を作るのは、とても難しい場合がある。それぞれの毒に対して、特定の解毒剤を必要とすることがたまにあるからな。解毒剤が正しい成分であるか心配しなくていいから、思うがままに毒を治療できると想像してくれ。\n\nさあ、やってみようじゃないか!", 0xc0a4b4dc, 0xc7410c2b, 0x8faf0ffa, 0x38c77760, 0x0d585714, "....." },
  [6129] = { "病気の治療", "Barrens北部にいるSickly Gazelle10頭にCurative Animal Salveを使って下さい。そうすると彼らを治療できます。Sickly Gazelleは、Crossroadsを東と西に横断する道の北に見られます。", "たっぷり10回分の治療用軟膏が作れたぞ、{name}。もっと軟膏を作るために私がここで働いているあいだ、君は我々が有利に事を進められるよう協力してほしい。Barrens北部一帯は病気のガゼルだらけだ。この軟膏を使って、彼らの病を治療してくれ。\n\nこれが終わったら、MoongladeのDendrite Starblazeは君と話がしたいと思うはずだ。きっと。あそこのCenarion Circleに、我々が感謝していると伝えてほしい……それと、君に直接言わせてくれ。おかげさまで助かった、ありがとうと。", "CrossroadsのTonga Runetotemに頼まれたことは終わりましたか? それが済まない限り、あなたの仕事は完了しません。", "Barrensの病んだガゼルたちの面倒をよく見て下さった。あのガゼルたちは何も知らず、大地に広がる腐敗と汚染の犠牲となったのだ。あなた方{race}は、Cenariusの考え方を理解することに対して、最も意欲的だ。Thunder Bluffの長老方のように、あなたは証明してくれた。均衡の必要性というものは、見せかけの種族の壁など超越してしまうことを。\n\n{name}、あなたはCenarion Circleと自然の友として値することを示してくれた。そのしるしとして、これを受け取ってくれ。", 0x0116fddd, 0xeeed1d31, 0x6c76cb22, 0x8899d0db, 0x384368d9, "....." },
  [6130] = { "毒を支配する力", "Thunder BluffのElder RiseにいるTurak Runetotemのところへ戻って下さい。", "精神的援助の見返りなしに毒を治癒することの意味を学んだのだな。しかしこれは覚えておいてほしい。あなたは毒を支配する新たな力をすぐ得られるが、他人は毒の苦痛に耐えなくてはならないということを。\n\n今すぐThunder BluffのTurak Runetotemのところへ戻るのだ、{name}。課せられた修行を理解している生徒に教えるための大切な呪文を、彼は間違いなく知っている。\n\nさらば、若きドルイドよ。また語り合おう。", nil, "よくぞ戻られました、私はあなたがここを離れてから修行の進み具合を追っていました。Crossroadsでの難問について聞き及び、驚いたことを認めねばなりませんね。環境へあのような毒が侵入することこそ最も均衡を揺るがすものですから、さらなる詳しい調査が必要です。\n\nあなたは苦難の中にありながら、徳をもって己を律しました。毒を支配する不変の力を贈るより他に、良い方法はありません。上手に使うのですよ、{name}……上手に使うのです。", 0xfaefb521, 0xeb5d1d3a, 0xc0a0d74f, nil, 0x0b177411, "...m.", nil, nil, 0x2bc5137a, nil, nil },
  [6132] = { "ここから連れ出して!", "Melizza Brimbuzzleを護衛し、その後DesolaceのKodo GraveyardにいるHornizz Brimbuzzleと話してください。", "ここから出してくれ！\n\nMaraudineと話をしにValley of Spearsまで来たんだ。ちょっとした商売ができると思ってね……なのにあいつら、話を聞こうともしない！私を食う気だと思う！\n\nここから出してくれたら、兄弟のHornizzがたんまり払ってくれる！あいつは東のkodoの墓場のそばにある私たちの野営地にいるんだ。\n\n急ごう、{name}。ほんの2分前、centaurどもが鍋用の薪を取りに行くって話してるのを聞いたんだ……", "妹のMelizzaを見なかった? いつも動き回ってばかりで、しょっちゅう面倒ごとに巻き込まれるのよ。", "Melizza から君が来るって聞いてたぜ。姉をピンチから救ってくれて本当にありがとう。残念ながら、もう別のピンチに陥ってるみたいだけどな!", 0x6d185bdb, 0x31688590, 0x4440fa0b, 0x7e758e1f, 0xc3f8b2ba, "....." },
  [6133] = { "レンジャーの長の命", "Eastern Plaguelandsの北の境へ行き、Quel'Thalas Registryを取り戻す。その品はQuel'Lithien lodgeのどこかにある。\n\nさらに、Rangersを$N1体、Pathstridersを$N2体、Woodsmenを$N3体倒さなければならない。", "Quel'Lithienのロッジのハイエルフどもが、私のものを持っている、{class}。人間だった頃の私の生涯を詳しく記した文書だ。\n\n先に言っておくが、いや、お前にそのような情報を知る資格など断じてない。言われた通りにしろ、虫けら。記録簿を取り戻せ。\n\nそれから愚か者、去り際にはできる限りの争いと悲しみを残していけ。奴らを苦しませておけ……", "待たせるなよ、{class}。", "registryを読んでいないだろうな。いくらお前でも、そこまで愚かなことはしないはずだ……", 0x5fffe202, 0x7df0e95c, 0xc6a90b80, 0xd7dab34e, 0x114c9e8a, "....." },
  [6134] = { "Ghost-o-plasm 集め", "Ghost-o-plasmを8個とCrate of Ghost MagnetsをDesolaceのHornizz Brimbuzzleのところへ持って行ってください。", "南東にValley of Bonesって谷があって、Magramの幽霊が出るんだ。怖そうだろ？でも、Magramにとってはどれだけ怖いか考えてみなよ！あそこで幽霊のエネルギーを捕まえられたら、あのcentaurどもにきっと高く売れるぜ。\n\nほら、このCrate of Ghost Magnetsを持っていきな。谷にある2体の大きな骸骨、Dead Goliathsの間に1つ置けば、幽霊が寄ってくる。距離をとって幽霊を倒し、Ghost-o-plasmを集めてくれ――それをMagramに売るんだ。", "ghost-o-plasmはどこだい、{name}?", "それだよ！お前さんにもちょっとくっついてるみたいだな。なんかぬるぬるしてるだろ？\n\nいやあ、手間をかけさせて悪かったな、{name}。こいつはひと財産になるぞ……centaursにこれが何なのか納得させられればな！", 0x417173f4, 0x0fee26ad, 0x25e62823, 0x5e12b43b, 0x7fb9819e, "....." },
  [6135] = { "Duskwing、ああ、なんと憎らしい……", "Duskwingを見つけて倒す。その死体からPatch of Duskwing's Furを回収し、Nathanos Blightcallerのところへ持って帰って下さい。\n\nDuskwingはMarris Steadの北の田園地帯をうろついていると言われている。", "これまでのところ、お前は私が与えた任務をこなしてきた。最も手際よく、とはいかなかったがな。\n\n自分は試練を受ける準備ができているとでも思っているのだろう。そうだな……そうだ、愚か者、もっと込み入った任務に取りかかる準備はできているのかもしれん。\n\nアルビノの悪魔コウモリ、Duskwingが、ここからすぐ北の田園地帯をうろついている。奴を追い詰めて始末しろ。奴の白い毛皮を一房持って戻れば、褒美をくれてやろう。", "この試練に一人で挑むのはお勧めしない、{class}。", "上出来だ、愚か者。このfurをお前が使えるものに仕立ててやろう。", 0x9ac167a0, 0x957f29e6, 0x227e225a, 0x4d2de6ae, 0x34730165, "....." },
  [6136] = { "肥満の者", "Eastern Plaguelandsの北の荒野でBorelgoreを見つけて倒す。任務を終えたらNathanos Blightcallerのところへ戻って下さい。", "Argent Dawnの野営地Light's Hopeを過ぎ、Northdaleの西へ行けば、でっぷり太ったウジ虫の獣、Borelgoreが見つかる。\n\nあの怪物には連隊をまるごといくつも失った。奴の図体には限りがない！食えば食うほど、腹回りが大きくなっていく……\n\nその獣がお前を食らったところで私の心は少しも痛まんが、お前が勝つ方が望ましい。この任務には他の者の助けを募ることを勧める。Borelgoreは、奴を襲うほど愚かな小部隊を食らうことで知られているのだ。", "最近、お前が大嫌いだって言ったっけか?", "この調子なら、お前を愚か者から一級の低能に昇格させてやらねばならんかもしれんな。", 0x75acd1d0, 0x19dcc77a, 0x0c44002a, 0x6650e59d, 0xdde03616, "....." },
  [6141] = { "Brother Anton", "DesolaceのBrother Antonと話して下さい。", "私の戦友Brother Antonは、遠くKalimdorの、Desolaceと呼ばれる地でアンデッドがはびこっているという噂を耳にしました。Antonはすぐにその地への船旅を手配し、アンデッドの脅威を探し出して滅ぼしに向かったのです！\n\n彼は、手を貸してくれる勇気と決意を持つ者を探しています。あなたの心が真っすぐなら、Antonと話してください。彼はDesolaceの、Allianceの町Nijel's Pointにいます。", nil, "東から援軍が来るという知らせを受けた。その噂の出どころはお前か? Scarlet Brotherの聖戦を助けるためにここへ来たのか?\n\nそうなら、よく聞け……", 0x43a2f68d, 0x56ae9363, 0x614b91fc, nil, 0xdede434a, "...m." },
  [6142] = { "二枚貝餌", "Soft-shelled Clam Meatを10個見つけ、Shadowprey VillageのMai'Lahiiのところへ持ち帰る。", "釣り人の顔つきをしてるな、{class}！私は釣りが大好きでね――生まれてこのかた釣りばかりさ。一番の餌はSoft-shelled Clam Meatだ。魚はどうしても我慢できないんだよ。わかるだろ？\n\n北へ行くと沖に難破船がある。そのあたりにはsoft-shelled clamがそこら中に転がってる。Soft-shelled Clam Meatを10個持ってきてくれたら、お返しに何かやるよ。", "新鮮なsoft-shelled clam meatを持って釣りに行くのが待ちきれないよ。必要な10個は持ってきてくれたかい?", "完璧だぜ、なあ。これこそ呪術医が俺の頭痛に効くって言ったことさ。あいつはこう言うんだ、『Mai'Lahii、釣りに行け。気分が良くなるぞ』ってな。\n\nいやあ、もう気分が良くなったよ、ありがとな！", 0x50517e58, 0x968616fc, 0x0f7c78d9, 0xa9eaf0ae, 0x430ca444, "....." },
  [6143] = { "他にやるべきこと", "Slitherblade Myrmidonを7体、Slitherblade Nagaを7体、Slitherblade Sorceressを5体倒し、DesolaceのShadowpreyにいるDrulzegarと話す。", "聞いたことがあるかもしれないし、ないかもしれないが……私と仲間は、北の沖の難破船のさらに北、Ranazjar Isleの近くで漁をしてたんだ。昔はしょっちゅうあそこで釣りをしてたもんさ。今じゃ、死んだ仲間の仇を討つ方法ばかり考えてる。\n\nある朝、nagaが襲ってきて、私以外は皆殺しにされた。\n\nこの罪悪感に良心が耐えられないんだ、{class}。あのnagaどもを焼き払ってきてくれ。骨折りに見合う礼はする。手を貸してくれるか？", "nagaが我々に混沌を解き放ったとき、助けを求めて叫んでいた声が今も聞こえるんだ。この悪い膝さえなければ、あのいまいましいnagaどもを倒しに一緒に行くんだがな!\n\n奴らはたいてい、海面下の珊瑚礁の奥深くにいる……潜んで……企んでいるんだ……", "nagaどもが討ち取られたって知らせは甘美だが、それでも俺の心はまだ空っぽだ。残りの人生をかけて、あいつらを皆殺しにしてやるつもりだ。\n\nほらよ、約束の報酬だ。nagaどもが俺の仲間にしたあの憎むべき行いの報いを受けたと知った満足に比べりゃ、ささやかなもんだがな。", 0xfc3e7576, 0x61ced3a6, 0x01c155be, 0xba7a3190, 0xdf51b5e5, "....." },
  [6144] = { "指揮への召集", "Undercityへ行き、Varimathrasと話して下さい。", "命令が下った、{class}。Varimathras自らが、非常に機密性の高い戦術作戦のため、私の最も「有能な」手先をUndercityへ送り返すよう求めてきた。\n\nあいにく、私の最も有能な手先たちは三年以上前に殺された。その代わりに私の手元にいるのは、脳の死んだ有象無象の寄せ集めだ。\n\n<Nathanosが冷ややかにあなたを見つめる。>\n\n直ちにUndercityへ行き、Varimathrasに報告しろ。私に恥をかかせるなよ、{class}！", nil, "大十字軍長はScarlet Bastionで安全に座したまま、その軍勢はお前たちの地になだれ込み、建物や記念碑を冒涜し、お前たちの民を殺している。\n\nDark Ladyは、この虫けらを今度こそ始末するよう私に命じた。お前がForsakenの報復の道具となるのだ。", 0x6dfc8040, 0x73acbf95, 0x804bd992, nil, 0xd1fdc659, "...m." },
  [6145] = { "Crimson Courier", "Eastern Plaguelandsへ戻り、Crimson Courierを追跡する。その伝令を倒し、Grand Crusader's Commandを取り戻す。\n\nさらなる指示を受けるため、その命令書をNathanos Blightcallerのところへ持って行って下さい。", "体が頭なしでは生きられぬように、頭も体なしでは生きられぬ。Stratholme内部にあるScarlet Crusadeの司令部の守りは、ほぼ難攻不落だ。ならば代わりに、頭の下から体を切り離さねばならん。\n\n私のDeathstalkersが、Stratholmeの外でのCrusadeの活動について情報を集めてきた。毎日、奴らの中央司令部からTyr's Handへ報告が送られている。この報告こそが鍵だ、{race}！Crimson Courierを見つけて、その報告を取り戻せ。それをNathanosのもとへ持ち帰るのだ。", "今度成功すれば、私の敬意をほぼ得られるだろう、{class}。", "<Nathanosは笑う。>\n\n素晴らしい! ついにだ! Scarlet Oracleを滅ぼす好機だ!", 0xa3d0e449, 0x6a108010, 0x2b17abae, 0xb5ecff12, 0x91191c74, "....." },
  [6146] = { "Nathanosの策略", "Marris Steadの南東にあるTyr's Handへ行く。そこに着いたらRotten Appleをひと口かじる。Scarlet Crusadeに成りすましている間に、Grand Crusader's CommandをCrusader Lord Valdelmarに届けて下さい。", "この命令書に少し手を加えておいた。我らのささやかな策略がうまくいけば、奴らはScarlet Oracleを表に出す。そこを討つのだ！\n\nよく聞け、{class}。お前はこの命令書をCrusader Lord、Valdelmarに届けるのだ。\n\nどうやって？手渡しするに決まっているだろう、愚か者。\n\n命令書とこの腐ったリンゴを持ってTyr's Handへ行け。街に入ったら、リンゴを食べろ。お前は人間どもにとって、もう少し……口当たりのいいものに姿を変えるだろう。命令書を持って、Crusader Lord、Valdelmarに手渡すのだ。", "これは許しがたいぞ、兵士!", "どこへ行っていた? Scourgeに捕まったのかと思っていたぞ。", 0x92ee3d1e, 0x4b5e8476, 0xe3d73292, 0x448f001a, 0xdc91379b, "....." },
  [6147] = { "Nathanosのもとへ戻る", "新たな情報を持ってNathanos Blightcallerのところへ戻って下さい。", "大十字軍長が妙な要請をしてくるものだ。ふむ、いずれにせよ……あの方のお求めとあらば従うまで。Scarlet Bastionへ戻り、Oracleがまもなくそちらへ向かうとお伝えしろ。\n\n彼女が無事にStratholmeへたどり着けるよう、あらゆる手を尽くそう。", nil, "愚か者どもめ! 私の欺瞞には気付かなかったようだ! 覚悟しろ、{class}。冷徹な狡猾さで打って出るぞ!", 0xea97ce6a, 0xe2026b1f, 0x2954b5af, nil, 0x44f34480, "...m." },
  [6148] = { "Scarlet Oracle, Demetria", "Scarlet Crusadeが動き出している。Tyr's HandからStratholmeへ向かう道のどこかで、OracleのDemetriaとその一行が見つかるはずだ。彼女を追い詰めて倒す。成功したらNathanos Blightcallerのところへ戻って下さい。", "Demetriaは大十字軍長の筆頭顧問だ。「異界の」感覚を持つことから、Oracleと呼ばれている。彼女はScourgeに対するCrusadeの勝利のいくつかに、見事に貢献してきた。\n\nこの策略で彼女を表に引きずり出すことには成功したが、本当に霊能力を持っているなら、何らかの厄介事を予期しているに違いない。その「厄介事」を与えてやるのがお前だ。\n\nOracleを追い詰めて始末しろ。今この瞬間にも、奴らはTyr's Handを出発しているはずだ。私を誇らせてみせろ、虫けら。", "状況はどうだ、{name}?", "奴らはこの一撃から何年も立ち直れまい! よくやった、{name}! お前は私の敬意だけでなく、この報酬も勝ち取った。", 0x8bbb1750, 0x0e0bfa77, 0x521dd337, 0x099381a6, 0x6dd61f23, "....." },
  [6161] = { "Rackmoreの財宝を手に入れろ！", "Rackmore's Silver Keyを見つける。Rackmore's Golden Keyを見つける。Rackmore's Chestを見つけて開ける。", "Rackmoreの航海日誌には、彼の船がFeathermoon Strongholdへ向かっていた時、海の生き物に襲われた経緯が記されている。宝が敵の手に渡るのを防ぐため、彼はRanazjar Isleに箱を隠したのだ。\n\n箱を開けるには、銀と金の二つの鍵が必要だ。鍵は失われてしまったが、鍵と箱が見つかれば、宝が待っている！", "この箱にはしっかりと鍵がかかっている。", "箱が開き、Rackmoreの宝が現れた!", 0x9e9779af, 0x0255b29e, 0xb6b2aff5, 0x24ee971a, 0xa231516f, "....." },
  [6162] = { "夫の最後の戦い", "Overlord Rorを仕留めて、Felwoodの Bloodvenom Postにいる、Dreka'SurにそのClawを渡しなさい。", "私の夫は、私たちのクランの名誉のためFelwoodに赴き、Shadow Councilや他の汚染による残虐行為に対して戦いを挑んだ！\n\nあのひとは何度も何度も死線をくぐり抜けた後、私に一通の手紙を送ってよこしたの。そこには、Overlord Rorという名の巨大で薄汚れたfurbolgに対するための支援要請をドルイドから受けたことが書かれてたわ。--２度目の連絡はなかった。私はRorのClawが欲しい、{name}。それが私を未亡人としたことの代償なの！ きっとあの化け物は南にいるわ ... Ashenvaleとの境界近くに。", "獣の爪はもう手に入れたか、{name}? あいつには罪を償わせてやる。堕落していようが、あんな陰気な森に住んでいて怒り狂っているだけだろうが、知ったことか。私の家族にあんな罪を犯したfurbolgを長生きさせはしない!", "約束を守ってくれたことで、あなたは私に名誉をもたらしてくれました。夫は戦いで死にました……彼ならきっと誇りに思ったでしょう。でも、私にひとりで生きることを強いたあの生き物が、その報いを受けたと知るまでは、私は安らぐことができなかったのです。\n\n改めてありがとう、{name}。", 0x2a69edfc, 0x470d8aae, 0x2040c5d3, 0x44d759ff, 0x889e236c, "....." },
  [6163] = { "Ramstein", "Stratholmeへ向かいRamstein the Gorgerを討ち取って下さい。Nathanosへの土産として首を手に入れて下さい。", "私は圧倒された。まさにこの農場で、私は立っていた……Lordaeronを守るため、一歩も退かずに。農場とそこにいたすべてのものが、Scourgeの巨大な波に襲われた。\n\nあの卑劣な者。あの汚物。そいつは私の上に浮かび、ぽっかり開いた胸腔から臓物を垂らしていた。\n\n目覚めた時、私はScourgeになっていた。長い間、私は無力だった。私の心はLich Kingの心と溶け合っていた。\n\n彼女が私を迎えに来た……どこかで、どうにかして、彼女が来ると分かっていた。自由だ。\n\nそして今、私は復讐を果たさねばならない――私から命を奪ったものへの復讐を。それを滅ぼせ。", "Sylvanasに解放されてから、何か月もこの荒野中であの獣を追い続けた。奴はStratholmeへ逃げ込んだのだ。あの畜生め……", "どうかな……あれは慈悲を乞うたか? 慈悲が何かを知ることができたのか?\n\n<Nathanosが唾を吐く。>\n\nこの獣の頭は我が壁に掛けておくとしよう。\n\nお前は我が精鋭の一人としての座を勝ち取った、{name}。\n\n<Nathanosが敬礼する。>", 0xc3b49104, 0xeac63321, 0xfc251360, 0x0daee5b8, 0x2c45f03c, "....." },
  [6164] = { "Augustus' Receipt Book", "Augustus' Receipt BookをTerrordaleのAugustus the Touchedのところへ持って行って下さい。", "商売の準備はできてるよ！何がほしいんだい？\n\nおっと待った……帳簿がなきゃ店を開けられない。帳簿なしでどうやって商売の記録をつけろってんだ？\n\n町のどこかに置いてきたに違いない。宿屋に部屋を取ってたんだ……帳簿はきっとそこだ。\n\n帳簿を持ってきてくれ。頼む、持ってきてくれ！帳簿を持ってきてくれれば、分かるさ！店を開いたら、うちの値段がとんでもなくイカれてるってことが分かるよ！", "私のreceipt bookは持ってきてくれた? 早く商売に戻りたくてたまらないよ!", "あった! おやまあ! こんなにびっしり書き込んであったのを忘れていたよ!\n\n今日は素晴らしい日だ、{name}! 最高だ! とんでもなく素晴らしいぞ!", 0xfeff3f27, 0xe6301b68, 0x4e549251, 0x6cf97626, 0xbfcf70e2, "....." },
  [6181] = { "速達伝令", "Lewis' NoteをThor the gryphon masterに届ける。", "俺達はStormwindからは直接、物資を多くもらっているわけではないが、軍用品を提供してくれる人が町にいるんだ。彼の名前はOsric Strang。彼の店はLimited Immunityといって、StormwindのOld Townにあるんだ。\n\n軍用品の提供量が徐々に減ってきていて、Osricにその件で相談する必要があるんだが、よければこの手紙を彼に届けてくれないか？\n\nStormwindへ行く一番早い方法を教えてやろうか？Thorのところへいってみな。あいつはgryphon masterなんだよ。この丘のすぐ下にいるから、俺が書いたメモを渡してみてくれ。gryphonに乗せてくれるはずさ。", "急いでいるみたいだね。それなら、ちょうどいいところに来たよ!", "Stormwindに行きたいってか？ちょろいもんだぜ。さあ、オレ様のgryphonに乗るんだ！", 0xd0027ff1, 0xacee0705, 0x971b5160, 0x5c4d4ffe, 0x13821bcd, "....." },
  [6182] = { "最初にして最後", "StormwindのOld TownにいるMathias Shawと話して下さい。彼はBarracksにいる。", "Nathanos Marrisは、人間のレンジャーロードの最初にして最後の一人だった。Sylvanas Windrunnerの弟子で、彼女は今やForsakenのBanshee Queenだ。\n\nNathanosは五年前、Lordaeronの防衛戦で戦死したものと我々は考えていた。遺体は結局回収されなかったが、Eastern Plaguelandsから脱出できなかったものと見なされていた。\n\nMathias Shawがその失踪を調査しており、何か新しい情報を持っているかもしれない。直ちに彼のもとへ報告に行け。彼はOld TownのBarracksにいる。", nil, "Eastern PlaguelandsでForsakenの不審な動きが報告されたのを受けて、SI:7の工作員が調査に派遣された。その調査結果は不穏なものだ。", 0x79d07d7d, 0x896b2154, 0xf98d351b, nil, 0xe83b7f3e, "...m." },
  [6183] = { "死者に敬意を", "彼の任務を引き受けるなら、もう一度Mathias Shawと話して下さい。", "私の最も優秀な現場工作員五人がMarrisの件を担当した。戻ってきたのは一人だけで、その男も三日後に眠ったまま死んだ。\n\nどうにか聞き出せたわずかな情報も、支離滅裂なうわ言だった。聞き取れたのは二つの言葉だけだ。「Nathanos」と「Blightcaller」。\n\nこの調査を続けるだけの人手はないし、Ravenholdtは手を貸さないだろう。何としても真相を突き止めねばならない。せめて亡くなった者たちの家族に区切りをつけてやるためにも。手を貸してくれるか？", nil, "<Mathiasはうなずく。>\n\nBolvarなら、名誉ある男女、Allianceで最も献身的な兵士たちを送ってくれると信じていた。", 0xabd1351c, 0x4ac23430, 0x0f11aa78, nil, 0x4bc4d491, "...m." },
  [6184] = { "Flint Shadowmore", "Western PlaguelandsのChillwind Campへ行き、連絡役のFlint Shadowmoreと会って下さい。", "となると、今のところ分かっているのは、Nathanos MarrisがこのBlightcallerに殺されたかもしれないということだけだ。Blightcallerは、私の工作員たちを始末したのと同じ悪党だと見ている。\n\nもう一人のSI:7工作員、Flint Shadowmoreが、Western PlaguelandsにあるAllianceの野営地Chillwind Pointに駐在している。彼を訪ねろ。Plaguesの現状を説明し、任務を与えてくれるはずだ。\n\n幸運を祈る、{name}。", nil, "最初の任務は単純だ、{name}。潜入して、戻ってくる。偵察だ……", 0x065813ab, 0xe649a5a0, 0xe08ff202, nil, 0x227d8a04, "...m." },
  [6185] = { "東方の疫病", "Eastern Plaguelandsをくまなく探し、「Blightcaller」と行方不明のSI:$N1の諜報員についての手がかりを見つける。SI:$N2 Insigniasを見つけたら、Chillwind CampのFlint Shadowmoreのところへ持って行って下さい。", "言ったとおり、最初の任務は偵察だ。大したことじゃない、{name}。Eastern Plaguelandsへ行って、このBlightcallerの手がかりを探してくれ。\n\n行方不明の工作員たちに関する情報にも目を光らせておいてくれ。彼らは死んだと考えるしかないし、死んだのなら、遺体があるはずだ……どこかに。\n\n<Flintはごくりと唾を飲み込む。>\n\nSI:7の工作員は皆、この記章を身に着けている。\n\n<FlintはあなたにSI:7の記章を見せる。>\n\n見つけたものがあれば、何でも私のところへ持ってきてくれ。", "ど……どうだった??", "Rutger。Fredo。Turyen。皆……死んだ……\n\n<Flintは記章を固く握りしめる。>\n\n彼らはどこにいた? このろくでなし、Blightcallerについて、何か他に分かったことはあるか?", 0x4c499f21, 0x58118db1, 0x80c06b69, 0x098a41c8, 0xc319792f, "....." },
  [6186] = { "Blightcaller来たる", "Stormwindへ戻り、Nathanos Marrisの運命をHighlord Bolvar Fordragonに知らせて下さい。", "<Flintの顔から血の気が完全に引いたように見える。>\n\nNa……Nathanosがこれを？NathanosがBlightcallerだと？\n\nなぜだ？彼は……とても高潔な人だった――皆に尊敬されたレンジャーロードだ。ハイエルフのもとで訓練を受けることを許された唯一の人間だった。それが今や、Forsakenの冷酷な手先だと？\n\n私……すまない、こんなことを頼んで、{name}。だが、この事態はすぐにHighlord Fordragonに知らせなければならない。頼む、Stormwindへ戻ってこの知らせを届けてくれ。", nil, "違う。そんな……違う! どうして? Forsakenの手先だと? Banshee Queenの勇者だと???\n\n<Highlord Bolvar Fordragonは打ちひしがれてうなだれる。>", 0xa9ba516f, 0xbd9e3e1d, 0x189b32d7, nil, 0x7872b9fb, "...m." },
  [6187] = { "秩序は回復されねばならない", "軍を集めてEastern Plaguelandsへ向かう。Nathanos Blightcallerと、彼を守ろうとするHordeのクズどもに総攻撃をかける。\n\n油断しないように、{name}。Hordeは命がけでレンジャーの主を守るだろう。", "この世界にレンジャーロードがどれほどいるか知っているか？人間のレンジャーロードがこれまでに何人存在したか？\n\nNathanosの功績は前例のないものだった。彼は戦術の天才で、十年にわたる戦いでAllianceに勝利をもたらしてきた。\n\nそれが今や……Forsakenの勇者とは。\n\nいや。こんなことがあってはならん。秩序を取り戻さねばならん。\n\n軍を集めよ、{name}。軍を率いてPlaguesへ戻り、Blightcallerを滅ぼすのだ。\n\n幸運を祈る、{name}。この戦いには、まことにそれが必要になるだろう。", "<Highlord Bolvar Fordragonは物思いにふけっている。>", "悲劇だ。思うに……我々の同胞は呪われているのだろう、{name}。最も偉大なウォリアーを、最も高潔な英雄を、最も才能ある学者を失う呪いにな。\n\n我々は君に恩がある。そして断言しよう、{name}、Nathanos Marrisが今どこにいようとも、彼は君に微笑みかけている。", 0xa805e50b, 0xc706a84e, 0x37c61b0a, 0x3462e28c, 0x86761e86, "....." },
  [6261] = { "Dungar Longdrink", "Gryphon masterのDungar Longdrinkに、Osric's Crateを届ける。", "{name}さんよ。Lewisから依頼されていた物をこの箱に入れておいたんだけど、これをあいつに届けてくれないかい？\n\nWestfallにいるThorと一度でも話をしてるなら、ここからgryphonに乗ってあいつのところへ戻れるだろ。Dungar LongdrinkはTrade DistrictにいるGryphon masterで、まずはそいつに話をしてくれ。\n\nDungarに相談すれば、Lewisにこの箱を早く届けられるだろうな。俺たちはWestfallの戦士らに、ピカピカの装備品なしで戦わせたくはないんだよ。", "額に汗をかいているじゃないか、あんた。走りすぎだよ。次はgryphonに乗っていきな!", "Westfallへ届ける物資かい？以前にWestfallに行ったことはあるのかい？あるなら問題ねえな。あそこへ行くルートなら、訓練されたgryphonがよく知ってるぜ！", 0x99cf1567, 0x7f71eb16, 0x150a7f07, 0xd7a18628, 0xfce80486, ".....", nil, nil, nil, 0x276c0f6b, nil },
  [6281] = { "Stormwindへ", "Gryphon masterのThorからStormwindへのgryphon騎乗券を購入し、Old TownでLimited Immunityという店を経営しているOsric StrangにLewis' Noteを届ける。", "低料金で、Stormwind行きのgryphonに乗れるぜ。オマエさん、OsricにLewis' noteを届けるんだろ？コイツに乗ると、すぐに着いちまうぜ。\n\n乗りたいなら、オレ様に声をかけてくれ。特別低料金で乗せてやる。絶対に損はさせないぜ！", "旅をしてきたのかい? どこか面白いところへは行ったかい?", "あ、Quartermaster Lewisからの手紙かい？やっぱり物資に関する内容だろ？Sentinel Hillは遠いし、Stormwindが見捨ててる場所なんだよな。\n\n届けてくれてありがとな、{name}さん。ここまでのgryphon代だ、受け取ってくれ。", 0x950eaddd, 0x9a2be79a, 0xd7241ffb, 0xd55888b8, 0x83dfa7ed, "....." },
  [6282] = { "Harpiesの脅威", "Sun Rock RetreatのMaggran Earthbinderは、Bloodfury Harpies・Bloodfury Ambusher・Bloodfury Slayer・Bloodfury Roguefeatherをそれぞれ7羽討ち取るよう求めています。", "トーレンはこの地の守り手であることを誇りとしている。私がなぜここStonetalonに棲むharpiesの数に心を痛めているか、君にも察しがつくだろう。\n\nKalimdorでharpiesが増え続けている元凶はBloodfuriesだ。奴らはあらゆる生き物の領域を侵し、罪なき者たちが自分の縄張りから出られないようにしている。\n\nharpiesを間引いてきてほしいのだ、{name}！", "Charred Valeを侮るでないぞ。あの丘には多くの邪悪な生き物が棲んでいる。強くあれ、{name}。そうすれば、我らの民へのこの脅威に打ち勝てるだろう。さあ行って、激しく打ちのめすのだ。我らの子らが、かつての悪を知ることが決してないように。", "これは素晴らしい知らせだ! 汚らしいharpiesどもの冷たい心臓へ如何にして恐怖を叩きつけたのか、もう一度教えてくれ。Bloodfury族は大打撃を食らったのだな!", 0x1341afda, 0x40e68446, 0x0e2c7c1c, 0x2cd50b9f, 0x85595902, "....." },
  [6283] = { "Bloodfury族の血統", "Sun Rock RetreatのMaggranは、Bloodfury Ripperを討ち取ってその証拠として遺骸を持ってくるよう望んでいます。", "Bloodfury Harpiesの数を減らすだけでは足りない。奴らという病を根絶する唯一の方法は、その頭目、Bloodfury Ripperを討つことだ！\n\nあれはあの汚らわしい生き物どもにとって女王も同然。奴を倒せば、奴らの数は必ず減るだろう。\n\nCharred Valeへ戻れば、西の丘陵沿いに奴がいるはずだ。倒すのは容易ではないが、報酬は大きいぞ。", "Bloodfury Ripperは厄介な生き物だ! Charred Valeの西の丘沿いを探せば見つかるだろう。\n\nあいつがいなければbloodfuriesは無力になる……きっと奴らを永遠に打ち倒せるはずだ!", "すでに怒りが自分から離れていくのを感じる。この先の時をどう使えばよいのだろうな。悪しきものが我が土地の近くで動いていると知ることが、私の思いを動かし続けていた。だが今、その思いは静かだ。これはよいことなのかもしれん……今なら、すべてのトーレンがそうあるべきように、善きことに心を向けられるだろう。\n\nどうか、これを苦労への報酬として受け取ってくれ。", 0x6c41a89f, 0x8b79db61, 0x4c64b1d5, 0x056fd9cb, 0x6796f8ca, "....." },
  [6284] = { "Arachnophobia", "Besselethを殺し、Besseleth's FangをSun Rock RetreatにいるMaggranのところへ持って行ってください。", "警告：ここから西、Sishir Canyonに進んでください。安全は保障できません。\n\nBesselethと彼女の８脚の子供たちは、峡谷は自分達の巣であると主張しています。\n\nSun Rock RetreatのMaggran Earthbinderは、Besselethに賞金をかけました。彼女を殺し、その証明をMaggranに持ってきてください。８脚の厄介者を処分した報酬を受け取ることができます。", "Besselethは冷酷な捕食者だ……夜にWebwinder Pathを旅する者たちが心配でならない。その時間に、奴とその子らが罪のない旅人を襲うのだ。私自身も奴の2フィートもある死の牙の餌食になったが、運良く追い払って安全なところへ逃げられた。あの怪物が滅ぼされるのを見られるなら、何を差し出してもいい。", "見事な狩りだ、{name}! Besselethはこのあたりの古い捕食者だ……いなくなって寂しいとは思わん。森の勇者となった証として、この報酬を受け取れ。\n\n<MaggranがBesselethに負わされた傷をさする。>\n\nこれでもっと多くの者が、闇に潜むものを恐れずにSun Rock Retreatへ旅できるようになるだろう。", 0x1171fcc5, 0xcbae1752, 0xa1f2522d, 0x85b0f7df, 0x7e895fb4, "....." },
  [6285] = { "Lewisのもとへ", "グリフォン使いのDungar LongdrinkからSentinel Hillまでのグリフォン便を買い、Osric's CrateをSentinel HillのLewisのところへ持って行く。", "WestfallのグリフォンマスターはThorだ。前に彼と話したことがあるなら、私のグリフォンに乗って彼のところへ行ける。\n\nこれは覚えておくといい教訓だ。グリフォンはいつも自分たちの首都へ飛ぶよう訓練されているが、遠くのグリフォンマスターのところへは、すでにそこへ行ったことがある場合にしか連れていってくれないんだ。\n\n君はもうThorのところへ行ったことがあるから、Westfallへグリフォンで行く準備ができたら、また私に話しかけてくれ。向こうに着いたら、Osric's CrateをQuartermaster Lewisに届けてくれ。", "Stormwindから戻ったのか? Osricは鎧を送ってくれたか?", "よし、鎧を持ってきてくれたな! 必要としている者たちにすぐに配ろう。\n\nありがとう、{name}。君の尽力には大いに助けられた。これでgryphonsにも慣れただろうから、これからもSentinel Hillに力を貸しに来てくれるとありがたい!", 0x96f66445, 0x1c7c566e, 0xb428ac6f, 0x54a54947, 0xb877172b, "....." },
  [6301] = { "再生の環", "Sun Rock RetreatにいるTammra Windfieldは１０個のGaea Seedsを集める事を望んでいます。", "工業の貪欲さと絶え間ない戦争がStonetalonの地を荒廃させました。Earthmotherの祝福だけが、このような傷を癒やすことができます。\n\n{name}、特別な種Gaea Seedを持って来てください。それらはここStonetalon Mountainでだけ見つける事ができます。Sun Rock Retreat の北、Mirkfallon Lakeの湖畔です。\n\nあなたが種を持ってきてくれたら、私が種の成長を速めるシャーマンの力を吹き込みましょう。", "戦争や、材木で利益を得ようとする者たちがもたらす絶え間ない破壊に、私の心は深く痛みます。再生の循環を助け、大地を蘇らせるために、Gaea seedsが必要なのです。お持ちですか、{class}?", "ああ、{name}、Gaea seedsを持ってきてくれたのだな。Earthmotherの祝福が、この小さな命の粒さえも芽吹かせ、茂らせるさまを見ているがいい。\n\n<Tammraが詠唱を始める。>", 0x1ee45c42, 0x412fe15f, 0x8cfd01f8, 0x5760b342, 0xb389c0fe, "....." },
  [6321] = { "Sepulcherへの補給", "Podrig's OrderをKaros Razokに渡してください。", "Executor Hadrecから、Sepulcherにある我々の装備の在庫を調べるよう頼まれた。Scourgeや、それよりひどいものが森に潜んでいる以上、Deathguardsに必要な装備が欠けることがあってはならないとお考えなのだ。\n\n調べたところ、全体としては十分な蓄えがあるが、戦場で失われた分を補うための武器がもっと必要だ。\n\nこれは必要な物の要求書だ。Undercityの武器商人Gordon Wendham宛てのものだ。この要求書を我々のコウモリ使い、Karos Razokのところへ持って行き、Undercityへの移動について彼と話してくれ。", "公務で来たようだな……", "ああ、発注書かい。Undercityにそいつを届けたいんだろ？ちがうか？急ぐんだ。Sepulcherの備蓄を切らすことはできんからな。", 0xcfcc9350, 0xe5b2c631, 0x954541ad, 0x048ed251, 0x09aef9bb, "....." },
  [6322] = { "Michael Garrett", "Gordon's CrateをMichael Garrettのところへ持っていってください。", "Sepulcherへの補給品はこの箱の中に入れておいた。もうすでにSepulcherに行って、そこのバットマスターと話をしたかい？それならここからこうもりに乗ってあっちに戻れるよ。\n\nUndercityのバットマスター、Michael Garrettと話をしな。Sepulcherに戻るこうもりを用意してくれるよ。", "遠くまで旅をしなければならないなら、batが一番だ。", "こいつをSilverpineのSepulcherに持って行くのかい？お安い御用だね。うちのこうもりは年中無休であそこまで飛んでるよ。", 0x30ec3f6a, 0x230e74d9, 0xc7c7a93c, 0xd08ea5ce, 0x0dfb1564, "....." },
  [6323] = { "Undercityまで", "バット(フライト)マスターKaros Razokに話しかけUndercityまでこうもりに乗ってゆき、Podrig's OrderをUndercityにいるGordon Wendhamに渡してください。", "わずかな料金で、私のコウモリの一匹がお前をUndercityまで運んでやろう。準備ができたらもう一度話しかけてくれ。移動の手配をしよう。\n\nGordon WendhamはUndercityのTrade Quarterにいる。私のコウモリが降り立つのも、その同じ地区だ。", "私は武器を最高の状態に保っている。手入れが行き届いていて、いつでも使えるぞ。", "Sepulcherからの注文かい？よしよし。Dark Ladyに仕える人の役に立てるってのは名誉なことだね。", 0x5760d29a, 0x3400fc7c, 0x02b18c1a, 0xf820d1e4, 0x2b5a74f3, "....." },
  [6324] = { "Podrigのもとへ", "バットマスターMichael Garrettのところへ行きSepulcherまでこうもりで飛んでいってください(有料)。そしてSepulcherのDeathguard PodrigにGordon's Crateを渡してください。", "SepulcherのバットマスターはKaros Razokという。もうすでにあっているなら、ここから彼のもとへ飛んで帰ることができる。\n\n我らのこうもりを使えばいつでもUndercityに飛んで帰ってこれる。しかし離れた土地に行こうと思ったら、まずそこへ行きその土地のバットマスターと話をしなければならん。\n\nSepulcherでKarosとすでにあっているようだから、ここから飛んで帰ることができる。用意ができたら言ってくれ", "{name}、戻ったか。Undercityからの我々の物資は持っているか?", "よくやった、{name}。この武器があれば、俺たちDeathguardが不意を突かれることはない。\n\nお前はDark Ladyへの大事な貢献を行ったのだ。", 0xdb263293, 0x62f053a2, 0x2d4da181, 0x34df7e4c, 0x61e021f3, "....." },
  [6341] = { "Teldrassilの恵み", "Nessa's CollectionをVesprystusのところへ持って行って下さい。", "Rut'theranの村の漁師たちはとても景気がいいのです。ここの魚は並外れて大きく、数も豊富ですから。ここの恵みを本土のものと比べてみたいのです。\n\n魚の骨と鱗のコレクションがあるので、Darkshoreにいる私の同僚のところへ届けてほしいのです。彼の名はLaird、Auberdineの村で魚を売っています。\n\n私のコレクションを私たちのhippogryphの管理人、Vesprystusのところへ持って行き、Auberdineへの移動について彼と話してください。", "どのようなご用件でしょう? 移動手段をお求めですか?", "ああ、これをAuberdineへ届けたいのですね？わかりました……", 0xfdaa45cb, 0x849cfb5d, 0xeffe6b5d, 0x2fd3c26c, 0x82c592b4, "....." },
  [6342] = { "Auberdineへの飛行", "hippogryphの管理人VesprystusのところからhippogryphでAuberdineへ飛び、Nessa's CollectionをLairdのところへ持って行って下さい。", "Rut'theranからAuberdineへ行く方法は二つあります。連絡船とhippogryphです。どちらも速くて確実ですが、まだhippogryphでAuberdineへ飛んだことがないのなら、そうすることをお勧めします。\n\nhippogryphの管理人がいる町では、どこでもその管理人と話しておくのが賢明です。一度管理人と話しておけば、他の町からそこへ飛べるようになります。\n\nこれがNessa's collectionです。Auberdineへ飛ぶ準備ができたら、もう一度私に話しかけてください。そしてNessa's collectionをLairdに届けてください。", "Teldrassilから来たのかい? 教えてくれ、あそこの釣りはどうだい?", "Nessaからの荷物か? ありがとう、{name}! Rut'theran村の近くで獲れた魚の標本を送ってくれると彼女は言っていたんだ。ここで獲れる魚とはずいぶん違うかもしれないとな……\n\nおや! この顎の骨は、ここで見つかる同じ魚のほぼ二倍の大きさだ。それにこの鱗、握りこぶしほどもあるぞ! 驚きだ!", 0xdcb4055c, 0xedfc0608, 0xf7020ff1, 0x289d443c, 0xa33b905a, "....." },
  [6343] = { "Nessaのもとへ戻る", "Laird's ResponseをNessa Shadowsongのところへ持って行って下さい。", "Nessaに返事を送らなければ。ここの魚がTeldrassilの沿岸の魚とどれほど違うか、彼女はきっと強い興味を持つだろう。原因は推測するしかないが、私は世界樹そのものが周囲の生き物に影響を与えているのではないかと睨んでいる！\n\nどうか、この返事をNessaに届けてくれ。hippogryphでRut'theranへ戻りたいなら、hippogryphの管理人Caylais Moonfeatherに話しかけるといい。連絡船に乗りたいなら、北西の桟橋から定期的に出ている。", "{name}、Auberdineから戻ったのかい? Lairdとは話せたかい?", "これはとても興味深い。ここの魚は大きいが、ここと本土とで漁獲にこれほどの差があるとは思っていなかった。何か理由があるはずだ……\n\nさて、ありがとう、{name}。あなたが持ってきてくれた知らせを村人たちと話し合おう。いつか、この奇妙さの根源を突き止められるかもしれない。だがそれまでは、その恵みにあずかるとしよう!", 0xba10c9cf, 0x9efa6697, 0x2381f0ae, 0x47a9c3c4, 0x4e30b81a, "....." },
  [6344] = { "Nessa Shadowsong", "Nessa Shadowsongと話して下さい。", "私の友人のNessa Shadowsongは、Rut'theran Villageで魚を商っています。彼女はDarkshoreへ小包を届ける必要があって、手伝ってくれる人を探しているのです。\n\n興味があるなら、Nessaのところへ行くには、DarnassusのポータルからRut'theran Villageへ向かってください。ポータルはTemple Gardensの西にあります。", nil, "ああ、Darkshoreまで荷物を届けてくれる運び手が必要なんだ。手を貸してくれないか?", 0x1cde2001, 0x0db93fa5, 0x3d0373e4, nil, 0xaae17e8e, "...m." },
  [6361] = { "Bundle of Hides", "A Bundle of HidesをCrossroadsにいるwind rider masterのDevrakに持っていってください。", "ワシはBarrensの動物たちの皮をもっているが、これをThunder Bluffに届けなければならない・・  同僚のAhanuが皮製品を作るのに必要らしい。\n\nワシのためにこれを届けてくれんか？\n\n最短でThunder Bluffへ行くにはwind riderを利用するのがいいだろう。\n\nCrossroadsのwind rider masterであるDevrakにこのBundle of Hidesを持っていき、彼とThunder Bluffへの移動について相談してくれ。", "wind riderを使いに来たのか? 運ぶ物があるのか?", "Thunder Bluffへ皮を持っていかなきゃならないのなら、君、正しい場所へ来たね。", 0x5629a678, 0x83576182, 0x83c7dd76, 0xc0c44b7a, 0x5fdeeba3, "....." },
  [6362] = { "Thunder Bluffまで", "DevrakにThunder Bluff行きの運賃を払い、Bundle of HidesをThunder BluffのAhanuに渡して下さい。", "安い運賃でThunder Bluffまで乗せてやろう。Thunder Bluffまで行くのに、これより速い方法はないぞ!\n\nもしそうしたいなら、準備ができてからまた俺に話しかけてくれ。\n\n皮の束をAhanuのところへ持って行くんなら、彼はThunder Bluffのwind riderタワーのふもとにある、「Hewa's Armory」にいたと思う。wind riderタワーってのは、ちょうど着陸したところだ!", "肩についている埃は、Barrensのものに違いない。我が友Jahanと話したのか?", "ああ、新しい皮の束だね。すぐ仕事に取りかかろう!\n\nありがとう、兄弟。すごく助かったよ。手間賃と旅費として、いくらかお金を渡そう。", 0x17e56cf3, 0xdb3baab4, 0xa2c8ef96, 0x26fbf800, 0x24706f90, ".....", nil, nil, nil, nil, 0x6bd5e885 },
  [6363] = { "Wind Rider使いTal", "Ahanu's Leather GoodsをThunder BluffのTalのところへ持って行って下さい。", "JahanがCrossroadsで売る革製品を準備したんだ。これを持って行ってくれないか?\n\nもうCrossroadsへ行ってwind rider使いと話しているなら、Thunder Bluffのwind riderで飛んでいけるよ。\n\nこの革製品をThunder Bluffのwind rider使いTalに持って行って、Crossroadsへ運んでもらう手配をするといい。", "ようこそ、{class}。何かご用か?", "これ、Crossroadsへ持って行く必要があるんだろ?　お安いご用だ。あっちでDevrakと話をしてるなら、俺のwind riderに乗ってあいつのところに行けるぞ。", 0xf7fcbd33, 0xf87319fc, 0x14bf81fc, 0xaf415926, 0xd7505c5d, "....." },
  [6364] = { "Jahanのもとへ", "wind rider master TalにCrossroads行きの運賃を支払い、Ahanu's Leather GoodsをJahan Hawkwingのところへ持って行って下さい。", "街へ飛んでいくには、一度そこへ行ってその街のwind rider使いと話さなくちゃいけない。君はもうCrossroadsでwind rider使いのDevrakと話しているね。それじゃ、ほんのちょっとの運賃で彼のところへ行けるよ。\n\n準備できたらまた話しかけてくれ。Crossroadsについたら、その革製品をJahan Hawkwingに届けられる。", "{name}、Thunder Bluffから戻ったのか? Ahanuに皮を届けてくれたか?", "Ahanuが完成品を送ってくれたのか?　素晴らしいね。今Crossroadsはたくさんの狩人や冒険者たちがいて、商売も活発なんだ。この品物もあっという間に売れると思うよ。\n\n君のしてくれたことに感謝するよ、{name}。恩に着るよ。", 0x734dcf93, 0x7a7dc803, 0xca30143e, 0xfdd2709f, 0x30c7484a, "....." },
  [6365] = { "Orgrimmarに肉を", "Zargh's MeatsをCrossroadsのDevrakに持っていってください。", "選りすぐりのお肉があるんだけど、これを友人に送りたいんだ。彼女の名はGryshka、Orgrimmarで宿屋の女将をやってる。俺のためにお肉を運んでくれないか？\n\nOrgrimmarへの最速手段はwind riderに乗ることだ。このお肉をCrossroadsのwind rider使いDevrakに持っていって、Orgrimmarへ行けるように話をつけて欲しい。", "急いでどこかへ行きたいのか? なら、話しかけるオークを間違えてないぞ!", "Orgrimmarにこの肉を持ってかなきゃならないのか? 任せとけ。ほんの少しの運賃で、俺のwind riderが連れてってやるよ。", 0x192a86fc, 0x81387def, 0xb0f8daee, 0xb3f83d0e, 0x16ed8259, "....." },
  [6381] = { "新しい命", "Gaea Dirt MoundにGaea Seed 10個を植え、残ったEnchanted Gaea SeedをSun Rock RetreatのTammraに返して下さい。", "見てきたとおりです、{class}。大地は苦しんでいますが、生命の循環というものは力強いのです。今度は私たちがその手助けをする番です。西のCharred Vale、破壊の中心にこれらのseedsを植えてきてください。気をつけて。あの傷ついた土地には今もharpiesや怒れる炎のエレメンタルがはびこっています。\n\n{name}、このenchanted Gaea seedsを持って行き、肥えた土の盛り土に植えてください。生命の循環は続かねばならないのです！", "あなたが植えるこの種は強く、堕落に抗い、他の命の足がかりとなります。種はどんどん育ち、まず堕落を防いで傷ついた大地を癒やし、そしていつの日か、Stonetalonを再び緑豊かな森へと戻すでしょう。\n\nGaea seedsはすべて植えましたか?", "これは大地にとって大きな勝利だ。やがて、ほかのことも起こるだろう。Venture Co.は丸鋸と斧を片付け、怒れる炎の精霊は鎮まり、harpiesは大地に追い出される。\n\nそのときになって初めて、{name}、Stonetalonは真の安らぎを得るのだ。\n\nよくやった、{class}。今日ここで生み出した新たな命への礼として、この品の一つを受け取れ。", 0xd597138a, 0xe3c1961a, 0x8d150759, 0x14e0ce13, 0xf0f6254d, "....." },
  [6382] = { "Ashenvaleの探索", "AshenvaleのSplintertree PostにいるSenani Thunderheartと話をしてください。", "お前の強さには感心したぞ、{class}。狩りを受け入れるその意志を見れば、お前がより大きな獲物……そしてより大きな試練へ進めると確信できる。\n\nAshenvaleの森は広大な未開の原野であり、Hordeはそこに政治的にも精神的にも自らの意志を押し通そうとしている。未知の地で己を証明したいなら、Splintertree PostのSenani Thunderheartの導きを求めるがよい。その前哨地は、Barrensから続く道の真北にある。", nil, "新たな辺境へようこそ、{name}。Ashenvaleは好機の地だ。お前のような若い{class}が、自らの力量を示す機会をいくらでも見つけられる場所だ。この前哨地を見て回り、Zoram Strandにも必ず足を運ぶといい。そこにもHordeの前哨地があるからな。\n\nお前がここにいるということは、狩りについてもっと学びに来たのだろう。よく聞け、必要なことを喜んで教えてやろう。", 0x1bf465b8, 0x0a003978, 0xe968293f, nil, 0xedbc036b, "...m." },
  [6383] = { "Ashenvaleの狩り", nil, nil, nil, "Ashenvale Huntを構成する伝説の生き物は3体いる。それらを探し出し、その狡猾さと力に自らを試すといい。その過程で、あなたは自分自身について何かを学ぶことになるだろう。その生き物とは、熊のUrsangous、nightsaber猫のShadumbra、そしてhippogryphのSharptalonだ。\n\nAshenvale Huntの生き物たちは強力で、倒すには助けが必要だと気付くかもしれない。もし打ち負かしたなら、その証を私のもとへ持ってきてくれ。", 0x1bf465b8, nil, nil, nil, 0x91a48cae, ".mmm." },
  [6384] = { "Orgrimmarまで", "wind rider master DevrakからOrgrimmarまでのチケットを買って、OrgrimmarのGryshkaにZargh's Meatsを届けましょう。", "わずかなコインでOrgrimmarまでwind riderに乗せて運んでやろう。 着いたら、Zargh's MeatsをGryshkaに渡せるぞ。彼女の宿屋はSkytowerからそれほど離れてないValley of Strengthにある。そこに降ろしてやる。\n\n旅立つ準備ができたら、再び声をかけてくれ。", "何かいい匂いがするな! まさか生肉を持ってたりしないよな?", "まぁ、すごい！　ステキなお肉！これはZarghからね？　確かにあのオークは、女性を喜ばせる秘訣を知ってるみたいね……\n\nもう、料理するのを待ちきれないわ。でも、あまり焼きすぎないの! お肉の一番良い出し方って、生だと思いません？", 0x09e2c4f0, 0x68c9187c, 0x8879a481, 0x94e76fb4, 0x7fe221c3, "....." },
  [6385] = { "Wind Rider使いDoras", "OrgrimmarのDorasにGryshka's Letterを持って行きましょう。", "Zarghに感謝の手紙を書いたの。これを届けてくれない？　もうCrossroadsのwind rider使いを知ってるなら、wind riderで飛んで帰れるわ。\n\nOrgrimmarのwind rider使いDorasにこの手紙を見せて、Crossroadsまで乗せてもらえるように話してみて。", "wind riderが必要か?", "BarrensのCrossroadsに行きたいのかい？　ああいいよ、運んでやるよ……", 0x9897a748, 0x9e96cb95, 0x96a2b1e4, 0x4b572cc6, 0xf84cda5f, "....." },
  [6386] = { "Crossroadsへの帰還", "DorasからCrossroads行きのチケットを買って、CrossroadsのZarghにGryshka's Letterを届けよう。", "俺のwind riderは、いろいろな場所へ飛べるよう訓練されている。ただし、お前がすでにその場所へ行き、そこのwind rider使いと話していればの話だ。\n\nお前はCrossroadsへ行って、そこのwind rider使いのDevrakと話した。だから、ここから直接あいつのところへ飛んでいける。Crossroadsに着いたら、Gryshkaの手紙をZarghに届けてくれ。\n\n出発の準備ができたら俺に話しかけてくれ。", "Orgrimmarから戻ったのか? 私が送った肉を、Gryshkaは気に入ってくれたか?", "ハッハッハ! 気に入ってくれたみたいだな! 大きくて肉汁たっぷりのステーキ以外でレディの頬に赤みをもたらすものなんてないからな!\n\nありがとう、{name}。本当に助かったよ。これはちょっとした手間賃だ。それと、結婚式に招待しても驚かないでくれよ!", 0xb7e37b1d, 0xd651c4fc, 0x3d58c10b, 0x46394cd6, 0x69eb2cba, "....." },
  [6387] = { "優等生", "Brock's ListをThelsamarのThorgrum Borrelsonのところへ持って行って下さい。", "うちの戸口には、採掘の技を学びたがる若いドワーフがたくさんやって来る。そして鉱夫に何よりも必要なものが一つあるとすれば、それはつるはしだ！\n\n授業で高い成績を取って名誉のつるはしを勝ち取った、採掘の生徒たちのリストがある。このリストをIronforgeのGolnir Bouldertoeのところへ持って行ってくれ。彼がつるはしを用意してくれる。\n\nIronforgeへ行くいちばん早い方法はgryphonだから、リストをうちのgryphonの管理人Thorgrum Borrelsonのところへ持って行って、Ironforgeへの移動について話してくれ。", "もうThelsamarは堪能したのかい? 別の町へ出発する準備はできたかい?", "Ironforge にこれを持っていかなきゃいけないんだって? ほんの少し運賃を払えばgryphonに乗せて連れてってやるよ。どうだね?", 0x24e749d7, 0xf62403c1, 0x57e23adf, 0x093769d9, 0xedf1dc2f, "....." },
  [6388] = { "Gryth Thurden", "IronforgeのGryth ThurdenにHonorary Picksを持って行く。", "これがBrockの生徒たちのためのhonorary picksだ。すでにThelsamarへ行ったことがあるなら、gryphonでそこへ飛んで戻るといい！\n\nつるはしをうちのgryphonの管理人Gryth Thurdenのところへ持って行って、Thelsamarへ戻る便について話してくれ。", "どこか行くところがあるって顔をしてるな。gryphonが必要かい?", "こいつをThelsamarまで届けにゃならんのか? そいつは造作もない。すでにThelsamarへ行ってThorgrum Borrelsonと話しているなら、わしのgryphonの一頭に乗って彼のところへ戻れるぞ。", 0x3b5086d2, 0x029c72cb, 0xc7801ddb, 0x4e09c9af, 0x721a7bfa, "....." },
  [6389] = { "汝に疫病あれ", "Northridge Lumber MillでPlagueland Termitesを放ち、Barrel of Plagueland Termitesを持ってWestern PlaguelandsのChillwind CampにいるNathaniel Dumahのところへ戻って下さい。", "樽を開けるのに使えそうなものがないか、製材所の中を見回す。役に立ちそうなバールが見つかった。\n\n足を踏ん張り、シロアリに襲われる前に製材所から逃げ出せるよう祈る。", "やったのか、{name}？termitesを放してくれたか？Scarlet Crusadeが製材所とHearthglenの両方を押さえ続けるようなことになったら、光よ我らを救いたまえ。奴らにはどちらも渡すべきではない。奴らは前の戦争の犠牲者につけ込んでいるだけだ。狂犬のように始末されるべきなんだ！", "ははっ! ありがとう、{name}! やってくれたんだね! これで父の魂も安らかに眠れるし、私も平穏に暮らせる。\n\n改めてありがとう。何か私にできることがあったら、どうか遠慮なく言ってくれ。", 0x4a22873d, 0x9d77a7f5, 0xb7edccdd, 0x5d5f831c, 0x34e8f1fe, "....." },
  [6390] = { "ふりかかる災厄", "Northridge Lumber MillにPlagueland Termiteを放った後、Barrel of Plagueland Termitesを持ってTirisfal GladesのBulwarkにいるMickey Levineのもとへ戻ってください。", "樽を開けるのに適当なものがないかあたりを探し回った。ちょうどよさそうなバールを見つけた。\n\n足元を固め、シロアリに追いつかれる前に製材所を脱出できるよう祈った。", "やったのか、{name}？製材所にtermitesを放してくれたか？\n\n家族が仕事も命も失っただけでも十分ひどかったのに、子供時代を過ごした場所があの汚らわしい自称聖職者どもに乗っ取られるのを見るなんて……ちっ！！", "ありがとう、{name}。さあ、この金を持っていってくれ。少なくて申し訳ないが、Scarlet Crusadeの努力をぶち壊す手伝いをすることに喜びを見出すのだ！", 0x4a22873d, 0x6cc35569, 0xb7edccdd, 0x34476c17, 0x1d01326c, "....." },
  [6391] = { "Ironforge へ", "gryphonの管理人Thorgrum BorrelsonからIronforge行きのgryphonを買い、Brock's ListをIronforgeのGolnir Bouldertoeのところへ持って行って下さい。", "ほんの数枚の硬貨で、わしのgryphonがIronforgeまで運んでやる。そこからBrock's listをGolnir Bouldertoeに届けてくれ。Deep Mountain Mining Guildにいる。IronforgeのGreat Forge Districtで、ちょうどわしのgryphonがお前さんを降ろす場所だ！\n\n旅立つ準備ができたら、もう一度話しかけてくれ。", "何かご用でしょうか、お客様？", "ああ、Brockの優秀な弟子たちの最新の名簿だな。名誉のつるはしはひと揃い用意してある。あとは生徒たちの名前を刻み込むだけだ……", 0xd28081ed, 0x0477c979, 0x2cfa2e26, 0x92c650dc, 0xe778e783, ".....", nil, nil, nil, 0xd6deda79, nil },
  [6392] = { "Brockのもとへ戻る", "gryphonの管理人Gryth ThurdenからThelsamar行きのgryphonを買い、Honorary PicksをThelsamarのBrock Stoneseekerのところへ持って行って下さい。", "わずかな料金で、Thelsamarまでgryphonに乗れる……ただし、すでに行ったことがあればな。gryphonは行ったことのある場所にしか飛んでくれないから、見かけたgryphonの管理人には必ず話しかけておくといい。そうすれば後でその管理人のところへ飛べる。\n\nThelsamarのgryphonの管理人Thorgrumのところにはもう行ったことがあるから、今なら彼のところへ戻れる。Thelsamarに着いたら、つるはしをBrock Stoneseekerに届けてくれ。\n\n出発の準備ができたら話しかけてくれ。", "おお、{name}。Ironforgeから戻ったのか？", "picksを持ってきてくれたか。素晴らしい！これを採掘の生徒たちに届けよう。Loch Modanの鉱脈で早く使いたくてうずうずしているはずだ。\n\n手を貸してくれてありがとう、{name}。君には借りができたが、せめてこの金で旅費くらいは賄えるといいんだが。", 0xe9291a93, 0xd370798c, 0x72505319, 0x7b4723d5, 0xf9547062, "....." },
  [6393] = { "エレメンタル戦争", "１０個のIncendritesをSun Rock RetreatにいるTsunamanのところへ持って行ってください。", "Tribunal of the Tides はfire elementalsとの戦いを行うために私をここStonetalon Mountainへ派遣しました。すべてのwater elementalsの主君であるNeptulon the Tidehunterは、我々の燃えるような従兄弟たちが消されることに、個人的な興味を示しています。\n\n{name}、Charred Valeのfire elementalsを破壊して、私がTribunalの好感をえるのを手伝ってくれませんか。破壊されるとき、fire elementalsはIncendritesを残します。それらを持ってきていただければ、報酬を渡します。", "Tribunal of the Tidesは待ちきれずにいます。彼らは、永劫の時にわたってあらゆる次元で荒れ狂ってきたこの戦争を終わらせようとしているのです。私の同胞たちは、憎き火の精霊に対する輝かしい勝利の知らせを心待ちにしています。私が必要としているIncendritesは持っていますか？", "私の中の水が興奮に沸き立っています。{name}、あなたは私にTribunal of the Tidesへ報告する輝かしい勝利を与えてくれました。", 0x3a960821, 0xdd0e499d, 0x3bd6600f, 0xb2453512, 0xedacdfd1, "....." },
  [6394] = { "Thazz'ril's Pick", "Thazz'ril's PickをForeman Thazz'rilに渡してください。", "{name}、お前は頼りになる{race}だ。もひとつ仕事を頼まれてくれないか？\n\nしばらく前私は北の洞窟で鉱物調査をしていた。そのときお気に入りのつるはしを忘れてきてしまった。取りに戻ってみると、洞窟は邪悪な獣どもで満ち溢れていた！その洞窟、Burning Blade Covenへ行って私のつるはしをとってきてくれんか？\n\n滝の空洞のところに忘れてきた。暗闇でも見えるように呪文がかけてある。見つけるのはそう難しくはないだろう……問題はそれを守っているものだけだ！", "Burning Blade Covenには入ったか、{name}？私のpickは見つかったか？", "すばらしい、よくやった！感謝するぞ、{name}。お気に入りのつるはしだ！Peonたちが木を切る仕事を終えたなら、あのすばらしい洞窟で鉱脈を見つけられるだろう！", 0xcb16d6a3, 0x42cbea5f, 0x69e4753a, 0x8afd7942, 0x66e27461, "....." },
  [6395] = { "Marlaの最後の望み", "Samuel FippsのなきがらをMarlaの墓に届けてください。それからNovice Elrethのもとへ戻ってください。", "わが友Marla Fippsはあの災いが訪れる前は夫のSamuelとともに暮らしていました。しかしあの災いが訪れた時、Samuelは急死しScourgeの一員となったのです。\n\nMarlaはアンデッドになることは避けられたが、結局非情な夫の手にかかって死んでしまった。しかしながら彼女の愛情は強く、今わの際の願いも最愛の人Samuelとともに墓に入りたいというものでした。\n\nSamuel FippsはDeathknellの北東の道沿いにある朽ち果てた野営地にいます。彼を倒してMarlaの願いをかなえてあげてください。彼を墓地の最前列にある彼女の墓に埋葬してください。", "我々は死者を敬わねばならない、{name}。それが我々とScourgeとの違いの一つなのだ……", "とてもいい行いをしましたね、{name}。Scourgeに対する争いは続いていくけれども、MarlaとSamuelがともに平穏の時を迎えられることを願ってやみません。", 0x3ab505f6, 0x48105831, 0xe3b59356, 0xae4dd1f3, 0xfb9bd7b5, "....." },
  [6401] = { "Kayaの生存", "Sun Rock RetreatのTammra Windfieldによいニュースを伝えてください。", "すばらしいニュースをSun Rock RetreatにいるKayaの叔母Tammra Windfieldに伝えてください。Kayaは生きています！　私たちは、村への残虐な襲撃の後、彼女が死んでしまったと思っていました。Sun Rock Retreatへ行くためには、道にそって西へ進んでください。", nil, "嬉しい、姪のKayaが生きていたなんて！　本当によい知らせだわ。ありがとうございます、{name}。", 0x29fb8709, 0x1e4fb9d8, 0x9edc231d, nil, 0xce73e720, "...m." },
  [6402] = { "Stormwindでの落ち合い", "Stormwind Cityへ行き、街の門へ向かう。Squire Roweと話し、あなたが到着したことをMarshal Windsorに伝えてもらって下さい。", "Stormwindの門でWindsorと落ち合うのだ。\n\nWindsorがこれから明かすことは、王国の根幹そのものを揺るがすだろう！\n\n一人でそこへ向かおうとするな、{name}。軍を集めねばならん！仲間を集めろ。武器を取れ！", nil, "始める前に、まずは軍勢を集めてもらいたい。何しろ相手はドラゴンなのだからな!", 0x1af12cc7, 0x59fa1490, 0xdcffa17a, nil, 0x9b717b87, "...m." },
  [6403] = { "大仮面舞踏会", "Stormwindの中を行くReginald Windsorについて行く。彼を危険から守る！", "大した冒険だったな、友よ。君には大きな恩がある。すべてが終わった暁には、おそらく……\n\nもう察しがついているだろうが、Lady PrestorはOnyxiaだ。Deathwingの子にして、Spireの暴君Nefarianの双子の片割れだ。\n\nあまりにも長い間、彼女はその魅惑の眼差しで我らの王国を支配してきた。大君主でさえ彼女の策略に操られている――操り人形だ。それも今日で終わる……呪文は解かれるのだ。\n\n案ずるな。力を合わせれば、我らは勝利する！\n\n準備はいいか？", "わ……私……私には何もできなかった。", "<Bolvarは砕けたメダリオンを手にしている。>\n\n中に宿る魔力を再び灯さねばならない。ドラゴンの目を同調させねばならない。\n\nWindsorの犠牲によって我らの王国は解放された。だが、Onyxiaとその眷属の脅威は常に迫っている。\n\nこのメダリオンこそが、私の心と体を囚えていたものだ。そしてこれによって、私はOnyxia自身の心、彼女の秘密に触れることもできた。今となってはその幻視もおぼろげだが、覚えていることもある。", 0x21125223, 0x83f7ff7b, 0x5c12f001, 0x98e54ef8, 0x76253855, "....." },
  [6421] = { "Boulderslide Ravine", "Boulderslide Ravineの洞窟の奥深くまで探索し、調査のために１０個のResonite CrystalsをSun Rock RetreatのMor'rogalまで持って行って下さい。", "ここStonetalonで何かがおかしいのです。あなたは大気の緊張を感じられますか？　{name}。\n\nここから南東にBoulderslide Ravineという深い洞窟があります。そこのKoboldsは懸命にResoniteとよばれる珍しい結晶を採掘しています。その洞窟でなにが起きているか理解するために、いくらかの鉱石が必要です。また洞窟の深さも調査して下さい。\n\n行ってください、若き{class}。この山の下にどんな悪が潜んでいるかを一刻もはやく突き止めねば。", "Boulderslide Ravineで何か分かったか？Resoniteにまつわる伝説があったような気がするのだが……どうにも思い出せない。洞窟の底に何があるのかが分かれば、奴らの邪な企みも明らかになるかもしれん。", "ああ……そうだ! それだ。Resonite crystalsにはEarthenの魔力の痕跡がある。koboldsは地中深くを掘り進み、Earthenを掘り当てたに違いない。\n\n伝説によれば、EarthenはTitansが創り出した生き物だ。我々の足が踏みしめるこの大地を創るために使われたという。これは決して無視できない脅威だ。\n\n<Mor'rogalは首を横に振る。>\n\nこの鉱石のサンプルに魔力を付与して、koboldsの企みに対抗できるかもしれん。", 0xafc62dde, 0x052e328b, 0x4270ef12, 0x9806d736, 0x1da30e95, "....." },
  [6441] = { "Satyr Horns", "Splintertree PostのPixelのために、Satyr Hornを16本集めて下さい。", "ちょいとあんた! あたしAshenvaleを抜けてRatchetへ向かおうとしてたんだけど、このSplintertreeでひとやすみすることに決めたの。いつもチャンスを探してるんだけど、近頃Ratchetじゃsatyr hornsが大人気みたいね。\n\nここら辺で聞いてみたら、Night Run・Satyrnaar・Xavianにいるsatyrs全部、私が探してる角を持つ種類みたい。あたしはsatyrsには敵わないわ……でも、あんたならできそうだわ!\n\nどうかしら、角を集めてきてくれたら、その時間に見合うだけのお礼はするわよ。", "早くhornsを手に入れてきてくれるといいんだけど、{name}。もうすぐRatchetに戻るんだ！", "これ完璧じゃない、{name}! 手伝ってくれてありがとね!\n\nああ、あとこれはお礼ね……", 0x13e94a31, 0xa22e7d9d, 0xe3adeab3, 0x61d72bfb, 0x68f77641, "....." },
  [6442] = { "Zoram StrandのNaga", "Zoram Strand沿いにいるMarukaiに、Wrathtail Head 20個を渡して下さい。", "この海岸には邪悪な者が潜んでいるんだよ、{race}。\n\nここは崩壊した都市Zoramの墓場なんだ。Zoramは遠い昔に破壊され、海の下に沈んだ。失われ、ほとんど忘れ去られた都市なんだ。\n\n今は、私たちには理由など分からないけれど、nagaが戻ってきている。まあ、理由など大して重要じゃない。この地が自分たちのものだと主張するために一生懸命に戦い、守らねばならないんだ。\n\n奴らの頭を20個とってきてくれ! nagaを深みに投げ戻してやる!", "nagaは数を増している、{name}。どうかこの仕事をやり遂げてくれ。", "ここいらであんたみたいなのがもっといてくれるとありがたいね、{name}。助けてくれてありがとう。", 0x4fd49e58, 0x910e5478, 0x1629860a, 0x3e533dbd, 0x06b6f56f, "....." },
  [6461] = { "生き血を啜る者", "Malaka'JinのXen'zillaは、Deepmoss Creeper 10匹とDeepmoss Venomspitter 7匹を殺すよう求めています。", "Malaka'Jinにいる俺たちトロールは、この土地の恵みで栄えてきた。Stonetalon Mountainは俺たちが食っていくのにいい狩り場なんだ。\n\nだが近頃、招かれざる晩飯の客が来るようになってな……この山の蜘蛛どもが夜な夜な野営地を荒らして、俺たちの獲物を盗もうとしてやがる。\n\nあの気味の悪い獣どもを始末するのを手伝ってくれたら、Malaka'Jinの俺たちはお前に恩を返すぞ。蜘蛛はStonetalonのそこら中にいる。ここから北へ向かえば、俺の言ってることが分かるさ。", "よう兄弟、毛むくじゃらの吸血野郎どもは始末したか？ここStonetalonで怖いものなんてないが、夜にこの辺をうろつくことはしないんだ……分かるだろ、兄弟！\n\n奴らの晩飯にならなけりゃ、それで万事オーケーさ。\n\n幸運を祈るぜ、{class}！", "そいつはいいな! いい知らせだ、今夜は招かれざる夕食の客が少しは減るかもしれん。\n\n心から感謝する、{name}。俺たちはずっとお前に借りがあるぞ。", 0x290dc497, 0x3dbb349e, 0x44275372, 0xf8a245cd, 0x831e4ebe, "....." },
  [6462] = { "Troll Charm", "Zoram'gar OutpostのMitsuwaに、Troll Charm 8個を渡して下さい。", "俺の一族は神聖なTroll Charmを持ってここへ旅して来たんだが、Zoram'garへたどり着く前に、Thistlefur族furbolgが攻撃してきてみんなを殺したんだ! あの汚らわしいFurbolgどもめ!\n\n兄弟姉妹が殺されていなくなったのは寂しいけれど、俺たちは来世でまた会えるはずさ。だけど、あのTroll Charmはこの世でとても価値のあるものなんだ。furbolgどもがあれを持つなんて侮辱だ!\n\n{name}、是が非でもあの護符を取り戻してくれ! 護符はThistlefur Holdの収納箱に入ってる。Thistlefur Holdは、Astranaarの北、Thistlefur Villageの奥にある洞窟だ。", "charmsは見つかったか、{name}？furbolgどもがあの聖なる品を持っている間は、一瞬ごとに怒りで血が煮えたぎるのだ！", "護符を見つけてきてくれたんだ! どうもありがとう! ありがとう、{name}! 君のしてくれたことがどれだけ重要な事か、分かるまい。\n\n護符の無いトロルなんて、戦いの傷が無いオークみたいなもんだよ……。\n\n役立たずさ。", 0x1223bf18, 0xb6fd8480, 0xca22eb96, 0x9c67b26c, 0x762ff9ab, ".....", nil, nil, nil, nil, 0x8502d612 },
  [6481] = { "Earthenの目覚め", "Enchanted Resonite CrystalでResonite caskを開き、Goggerocを殺してください。新しい情報とEnchanted Resonite CrystalをもってMor'rogalのところへ戻ってください。", "あなたは大地に対する隠された脅威を暴きました、{class}。洞窟で見つけたResonite cask には、Goggerocという名の眠れるEarthenが含まれています。\n\n私はシャーマンとしての力であなたが集めたResonite crystalsの混合物を変えました。enchanted Resonite crystalを手に取り、EarthenのはいったResonite caskを叩き割ってください。\n\n目覚めたGoggerocは弱っているでしょう・・・殺してください、{name}！", "この脅威をすぐに取り除かなければ、Stonetalon全土が失われてしまうだろう。Earthenの力には、どんな手段でも太刀打ちできない。目覚めたばかりのGoggerocは長い眠りのせいで弱っているはずだ。それこそが君が突くべき好機なのだ……さあ行け、{name}！", "良い知らせを持ってきてくれたな、{class}! EarthenがKalimdorにとって何を意味しうるのか、恐れていたのだ。\n\nGoggerocを倒すのは、英雄にしか成し得ない務めだった。よくやった。StonetalonもKalimdorも、すべてが君に恩を負っている、高潔なる{class}よ。\n\nこれを報酬として受け取ってくれ、誉れ高き者よ。", 0xab18846e, 0xe822594e, 0x79cb0289, 0x6c9c4921, 0x50265ed0, "....." },
  [6482] = { "Ruulに自由を", "Ruulを護衛し、Splintertree PostのYama Snowhoofと話して下さい。", "え? あなた誰?\n\n{name}? furbolgじゃないのか。奴らは呪われてる! 奴ら、私を熊だと思って捕まえたんだが、飢え死にさせられそうだ! 力が衰えていってる……\n\n逃げるのを手伝ってくれ。そして、東のSplintertree Postにいる姉妹のYamaと話してほしい。\n\n{name}! 私は逃げなければ!", "兄弟のRuulを見かけなかったか？何日も前に森へ入ったきり、戻ってこないのだ……", "私の兄弟を見つけてくれたのですね! Thistlefur族に捕まっていたのですか? それは恐ろしい知らせです。多くのFurbolgたちは高貴な生き物なのですが、Thistlefur族は堕落していたのですね。\n\n兄弟を救い出してくれたことを感謝します、{name}。奴らが可哀想なRuulをどんな風に扱ったのか、考えたくありません。厳しい仕打ちの後、彼は長く眠ることでしょう……", 0x07e8ff56, 0xbbd83e57, 0x2a3becff, 0x07ac7df4, 0xa4fa8915, "....." },
  [6501] = { "Dragon's Eye", "Fragment of the Dragon's Eyeに力を取り戻させることのできる存在を、世界中から探し出さなければならない。そのような存在について分かっているのは、それが実在するということだけだ。", "私が差し出せるのは、砕けたメダリオンの欠片だけだ。\n\n新しい鍵を鍛えるのに力を貸してくれる、竜の血を引く者をもう一人探さねばならない。その鍵を手に入れたら、Dustwallow MarshのWyrmbogへ行かねばならない。そこに彼女の巣がある、{name}。\n\n力を貸してくれる他の竜の一族はどこにいるのか？残念ながら、私には分からない……存在するとは言われている。中には、人型の種族の一つに姿を変えて、我々の間で働き暮らしている者さえいるかもしれない。幸運を祈る。", "そなたから邪悪な気配が放たれているのを感じるぞ、{race}。そのような気配を放つとは、一体何を持っているのだ？", "気付くべきだった。黒いドラゴンの一族の母、Onyxiaの一部とは。なんとおぞましい……", 0x667cb580, 0xc8568b34, 0x01f50423, 0x28f8fcf6, 0xb8659b7f, "....." },
  [6502] = { "Drakefire Amulet", "General DrakkisathからBlood of the Black Dragon Championを取り戻さなければならない。DrakkisathはBlackrock SpireのHalls of Ascensionの奥にある玉座の間にいる。", "これは竜の一部だ。鱗だ――魔法をかけられ、姿を変えたものだ。完全な状態なら、その獣の巣へ入る手段となり得た。砕けてしまっては、役に立たない。\n\nこの品を修復することはできるが、そのためには黒竜の勇者の血が要る。一人いる……General Drakkisathと呼ばれ、Nefarianのdragonspawnの軍勢を統べる者だ。聞いたことがあるかな？\n\n彼の血を持って戻れ、{race}。そうすれば、欠片に魔法をかけて、Onyxiaの巣へ入れるものに変えてやろう。", "時の流れは止まりも緩みもせぬ、{race}。我が命は永遠なれど、そなたの命はそうではない。与えられた時を無駄にするでないぞ……", "このアミュレットが、そなたの求める道を開くであろう。Onyxiaの巣はDustwallow Marshにある。このアミュレットを持つ限り、彼女の結界がそなたの侵入を阻むことはできぬ。\n\nBlue Flightはそなたの幸運を祈っておるぞ、{name}。", 0xd4865526, 0x0799ee5c, 0x52080e65, 0xc80f986c, 0xb1ae724c, "....." },
  [6503] = { "Ashenvale Outrunner", "Ashenvale Outrunner 9人を殺し、Splintertree OutpostのKuray'binのもとへ戻って下さい。", "Ashenvale outrunnerがつい先ほどSilverwing Outpostを出て、今は森の中で我々の縄張りの近くをこそこそ動き回っているという報告を受けた。奴らに我々の防衛の情報を集めさせるわけにはいかん！\n\nこの前哨地の南、そしてAllianceのSilverwing前哨地の東にある森をひそかに抜けていけ。outrunnerを見つけて倒し、それから私のところへ戻れ。", "outrunnerを仕留めたという報告を待っているぞ、{name}。", "よくやった、{name}。お前の狩りの腕は見事だ……\n\nあの斥候どもを失ったことで、Allianceの目は塞がれる。情報が足りなければ、奴らが攻撃を仕掛けてくる可能性も低くなる。", 0xf39e3da0, 0x8183eec6, 0xa48ee277, 0xd2a0ba0a, 0x681f0b9e, "....." },
  [6504] = { "無くなったページ", "Shredder Operating Manualの無くなったページ12枚を見つけ、第一章・第二章・第三章にまとめて下さい。Splintertree Postの近くにいるGurda Ragescarにそのページを返して下さい。", "Ratchetでこのshredderを受け取って、持ち場のWarsong Lumber Campへ戻る途中だったんだ。shredderの動かし方の手引書を渡されてたんだが、帰り道で大風が吹いて手から飛ばされちまった。ページはあちこちに散らばって、残ったのは表紙だけさ。\n\nページは今ごろどこにあってもおかしくないだろうな……でも、あれがないとshredderの使い方が分からないんだ！探してきてくれないか？", "早くページが見つかるといいんだけど、{name}！本当に仕事に戻らなきゃいけないんだ！", "読むのは得意じゃないのよね……だけど、これで仕事へ戻れるわ! ありがとうね、{name}!", 0x7e77aef8, 0xb708cd13, 0xda8de124, 0x72e48f8c, 0xf9144af7, "....." },
  [6521] = { "不浄なる同盟", "Ambassador Malcin's HeadをUndercityのVarimathrasのところへ持って行って下さい。", "Malcinは自分がRazorfen Downsの外にいると言っている。この大使は討たねばならん――その任務はLich Kingの目から見て失敗に終わるのだ。\n\n奴がそこにいることで、あの一帯について我々が掴んだことの多くに説明がつく――quilboarの一部は恐ろしいほど強大になっていて、しかも奴ら独自の形でPlagueの兆候を見せている。奴らが結んだ何らかの取引の証に違いない。\n\nMalcinを見つけて討て、{name}。事を成したら私のもとへ戻れ。", "大使は見つけたのか、{name}? あの者は死んだのか?\n\nScourgeがKalimdorに足がかりを得ることを許すわけにはいかん。奴らは我々自身の国境にとってすら十分な脅威なのだ、2つの戦線で相手をするなど御免だ。\n\nお前が話してくれた出来事の中で唯一明るい兆しは、あの老婆が穢されていないように見えたことだ。Scourgeは大いなる力をもたらすかもしれんが、奴らの取引に応じればBarrensが真に自分のものにはならないと、彼女は魂の奥底で分かっているはずだ。", "よし。よくやった、{class}。\n\nMalcinが死んだ今、少なくともScourgeの侵攻が食い止められると分かる。Dark Ladyは君の働きに感謝し、褒美を授けたいとのことだ。\n\nDownsにおけるScourgeの影響がどこまで及んでいるのかは分からんが、奴らの企みもじきに突き止められるはずだ。", 0x53428ea7, 0xef1f9f41, 0xb67a641e, 0xa04317a5, 0xcfe31419, "....." },
  [6522] = { "不浄なる同盟", "Small ScrollをUndercityのVarimathrasのところへ持って行って下さい。", "奥方様\n\n我々が何を申し出ているかは、よくご存じのはずです。Barrensとその先の地を手に入れる機会は、実に大きなものです。我々はただ見返りとして、あなたのお力添えを望んでいるだけなのです。お力添えとは、この地域で我々に自由に行動させていただくこと、それ以上のものではございません。\n\nどうか、この件についてさらにお話しさせてください。我々には大いなる力があり、我らに加わる賢明な者たちとそれを分かち合う用意があります。当面の間、私はRazorfen Downsの外に留まっております。\n\n敬具\n\nAmbassador Malcin", "話したい用件とは何だ、{name}？しつこく付きまとうからには、よほど重要だと思っているのだろうな。", "この巻物の紋章には見覚えがある、{name}。Razorfen Kraulを支配しているあの老婆から見つけたのか? 興味深い。\n\nScourgeはひとつの大陸では満足していないようだ。このAmbassador Malcin――この書き付けを書いた者だ――はScourgeの疫病に冒された手下の一人で、事態が……変わる前は、Lordaeron王国の人間の外交官だった。\n\nScourgeがKalimdorに足場を築こうとしているなら、我々が動くしかない。", 0x53428ea7, 0x6a61a5a5, 0xd95a6bbf, 0x16f8387f, 0x29ba3722, "....." },
  [6523] = { "Kayaの保護", "Kaya FlathoofをCamp Aparajeまで護衛し、Stonetalonの南東端近くにいるMakaba Flathoofのところへ戻ってください。", "助けてくれてありがとうございます！\n\n見つかる前に急いで逃げなくては。どうかCamp Aparajeまで連れて行ってください。そこからなら道がわかります。\n\n私の父、 Makaba Flathoofがとても心配しているはずです。", nil, "Kayaが生きている！　{name}、彼女を助けて頂いたことに感謝します。", 0x15129e83, 0xe5af41d4, 0xd4cff830, nil, 0x59df4b81, "...m." },
  [6541] = { "Kadrakへの報告", "北Barrensの監視塔にいるKadrakに報告して下さい。", "北にあるAshenvaleへ行ったことはあるかい? Hordeが最近あそこのZoram Strandに前哨を設置したもんで、前線を守るのにいつでも新人を必要としてるんだ。\n\nもしその気があるなら、北Barrensの監視塔にいるKadrakと会ってくれ。彼はAshenvale作戦を任されているから、君にもっと指示を出せる。", nil, "AshenvaleはHordeとAllianceとがせめぎ合う場所だが、我々の直近の作戦は大いに成功を収めている。Zoram Strandに前哨を置いただけでなく、ちょうど北にSplintertreeという前哨も設置したのだ。", 0x76d74aab, 0x6b18afa9, 0xea704af2, nil, 0x79ee031c, "...m." },
  [6542] = { "Kadrakへの報告", "北Barrensの監視塔にいるKadrakに報告して下さい。", "北にあるAshenvaleへ行ったことはあるかい? Hordeが最近あそこのZoram Strandに前哨を設置したもんで、前線を守るのにいつでも新人を必要としてるんだ。\n\nもしその気があるなら、北Barrensの監視塔にいるKadrakと会ってくれ。彼はAshenvale作戦を任されているから、君にもっと指示を出せる。", nil, "AshenvaleはHordeとAllianceとがせめぎ合う場所だが、我々の直近の作戦は大いに成功を収めている。Zoram Strandに前哨を置いただけでなく、ちょうど北にSplintertreeという前哨も設置したのだ。", 0x76d74aab, 0x6b18afa9, 0xea704af2, nil, 0x79ee031c, "...m." },
  [6543] = { "Warsong報告書", "まずBundle of Reportsを開いて下さい。Warsong ReportsをWarsong Scout・Warsong Runner・Warsong Outriderへ渡して下さい。彼らから得た最新情報をbarrensの北監視塔にいるKadrakのところへ持ち帰って下さい。", "最近、偵察を数人Ashenvaleに配備したのだ。そこで、彼らへの指令を運び、偵察報告書を持ち帰る伝令を必要としている。\n\n一人目のrunnerを探すなら、最初の立ち寄り先はZoram'gar Outpostだ。Zoram Strandから西に向かったところにある海岸沿いだ。北のSplintertree Postにも立ち寄る必要がある。そしてAzshara付近までの、東へ向かう道沿いだ。そこでscoutとoutriderを見つけられるだろう。\n\n彼らにそれぞれ報告書を渡し、そして偵察結果の最新情報を受け取るのだ。", "急げ、{name}。彼らにreportsを届けねばならん。急を要するのだ。", "君が頼りになる奴だということが分かるな。この最新情報はAshenvale駐留の推進計画において、極めて重要なのだ。これで次の作戦が立てられる。", 0xf2bef2e2, 0xff13d2f5, 0x7d33a1a0, 0xe0ca1342, 0xd9ec4538, "....." },
  [6544] = { "Torekの攻撃", "Silverwing OutpostとDuriel Moonfireに攻撃を仕掛けるTorekを護衛し、その後、Splintertree PostのErtog Ragetuskに報告して下さい。", "おーい! {class}! こっちに来てくれ!\n\n俺と仲間たちとで、西にあるSilverwing Outpostをちょうど攻撃するところなんだ。標的は、指導者のDuriel Moonfire。偵察によると、前哨は見張りと戦士によって厳重に守られているらしい。この戦いは名誉になりそうだ!\n\n{name}、この栄誉を分かち合って、俺たちを手伝いたくないかい? もし手伝ってくれたら、これが終わった後で俺の上司、SplintertreeのErtog Ragetuskに成功を報告できるぞ。\n\nどうかな。一緒に行かないか?", "TorekはSilverwing Outpostへの任務に送り出された。攻撃は成功したか？", "ではTorekの攻撃は成功したのだな! よくやった、{name}。ナイトエルフはなかなかの敵だ。少々やせてはいるが、強くて猛々しい! さぞ見物な戦いだっただろう……\n\nそれに、傷跡の一つや二つは手に入れたことを願うぞ!", 0xfb0fc804, 0xc94c7a08, 0x19b8d053, 0x6063f367, 0x83edb91d, "....." },
  [6545] = { "Warsong Runner Update", nil, nil, "私への命令を持ってきたのか？元気があって意志の強い新兵は、いつ見てもいいものだ。\n\nここでついて来るつもりなら、早く覚えることだな。nagaの脅威は増している、{name}。ここに着任してから、この前哨地への攻撃を何度も目にし、防衛にあたってきた。\n\nだが、その任務に手を貸したいのなら、この前哨地にいる他の者と話してくれ。", "さて、この報告書でKadrakにすべて説明がつくはずだ。できるだけ早くこれを彼に届けてくれ。", 0x6770a57c, nil, nil, 0x51947fed, 0x7f206db5, ".mm.." },
  [6546] = { "Warsong Outrider Update", nil, nil, "この道には多くの危険が潜んでいる、{name}。この地を旅する間はそれを覚えておくがいい。allianceの脅威はすぐそこまで迫っている。\n\n我々はあらゆる戦線で敵に直面している。satyrはAshenvale東部にはびこる手強い勢力だ。さらに、nagaがAzsharaの地の広い範囲を支配したことも分かった。\n\nそれでも我々の数が増え続けているのは良いことだ。この先に待つものに備えておけ、{name}。", "この最新情報の報告書を Kadrak のところへ。急げ、{name} 。", 0x1f297912, nil, nil, 0x30116780, 0x6bdc5b6a, ".mm.." },
  [6547] = { "Warsong Scout Update", nil, nil, "油断するな、{race}。エルフどもはよく物陰に潜んでいる……\n\n常に見張っていなければならん。我々はこの地を手に入れるために懸命に戦ってきたが、エルフどもはそれを奪い取る機会をうかがっているのだ。\n\nKadrakから次の命令を預かってきたのだろう？", "我々がここでナイトエルフどもを食い止めることに成功していると、Kadrakに伝えてくれ。計画は順調だ。", 0x3bb2bdcc, nil, nil, 0xb90a3cda, 0x056a033a, ".mm.." },
  [6548] = { "村の復讐", "８体のGrimtotem Ruffiansと６体のGrimtotem Mercenariesを殺し、Stonetalonの南東端近くにいるMakaba Flathoofのところへ戻ってください。", "Grimtotem 一族は私の村を襲撃して、ほとんどの者を殺しました。\n\n私はできる限りの敵を殺し、かろうじて生き残りました。\n\n{name}、私が望むのは奴らの死だけです。奴らは、すぐ西でみつかるでしょう。", "もう奴らを倒したか？", "{name}、感謝します・・・しかし、私はGrimtotemが私の村にしたことをけして忘れないでしょう。", 0x7672b786, 0x3188b556, 0x2e43c3b5, 0x8436fd53, 0x3876ab77, "....." },
  [6561] = { "Blackfathomの悪事", "Thunder BluffのBashana RunetotemにTwilight Lord Kelrisの首を渡して下さい。", "力が……尽きてしまいました。あなたの助けが必要です！\n\n遠い昔、この地はEluneの偉大な神殿でした。けれど不運が破滅を招きました。Old Godの穢れが地の底から染み出し、聖なるMoon Wellを汚したのです。\n\nOld Godの僕であるAku'Maiが、水の中から現れました。\n\nTwilight's Hammerの信徒たちはnagaと手を組み、この地を占拠しています。Kelrisに率いられた信徒たちは、力を得るために罪なき者をAku'Maiへの生贄にしているのです。\n\nKelrisを討ち、その首をThunder BluffのBashanaのもとへ届けてください、{name}。お願いします。", "Earthmotherがあなたと共にありますように、{name}。\n\n大地とそのすべての民との平和こそ、私たちの目指すべきものです。彼女は自然のための壮大な計画をお持ちで、私たちは皆、その計画の中で果たすべき役割があるのです。", "Kelrisはしばらくの間、Argent Dawnの追跡をかわし続けてきた。\n\n長らく彼らは、あの男を死んだか行方知れずかと考えていた。\n\nその支配に終止符を打つことで、あなたは多くの罪なき人々の命を救ったのだ、{name}。\n\nEarthmotherに称えあれ! 己の利益のために、Old Godの下僕へ他者を生け贄として捧げるなど、嫌悪を超えている!\n\nあなたは今日、偉大なことを成し遂げた。Kelrisは邪悪な存在であり、Old Godsのような者どもを崇めることで、この世界を混沌の時代へと引き戻そうとしていた。感謝する、{name}。", 0x43ec82c9, 0xce4f2e26, 0x94ed4e5b, 0xb0ade819, 0x48004ea9, "....." },
  [6562] = { "Trouble in the Deeps", "AshenvaleのJe'neu Sancreaと話してください。", "Je'neu Sancreaは助けを必要としています。彼はAshenvaleのZoram'gar Outpostにいます。Night elfの森は、Stonetalon mountainsの北です。Windshear Cragを通り抜けるか、Barrensを通って北に向かえば着きます。Zoram Strandは森のずっと西です。気をつけてください、{name}。あなたの存在を良く思わない者たちがいます。", nil, "Tsunamanがあなたを派遣した？　素晴らしい。話し合わなければならないことがあります。", 0x307a4f6d, 0x9f861a77, 0x131c7400, nil, 0x87dd1bf2, "...m." },
  [6563] = { "Aku'Mai のエッセンス", "Ashenvale の Je'neu Sancrea に Sapphire of Aku'Mai 20個を渡して下さい。", "Blackfathom Deeps の洞窟内部の入口近くに、壁沿いに大きなサファイアの塊がある。最近nagaどもがその結晶を集めていることが分かった。理由はまだ定かでないが、nagaが目的を果たすのを止めねばならないことは分かる。その結晶は精霊の大きな力を秘めていて、もし悪用されれば強力な魔力を持つ素材を生み出すことができてしまう。\n\n手伝ってくれるかい、{name}? Blackfathom Deeps は、この基地から北へ向かった Zoram Strand沿いにある。", "結晶の捜索はどうだ、{name}？nagaがそれを採っているところは見たか？奴らがなぜそんなものを集めているのか、その理由が分かるよう先祖に祈っている。", "よくやった、{name}。これが俺の話した結晶だ。とても興味深い……。\n\nこの中から力を感じる。水の精霊がまとわりついているよ。nagaはこれを使うつもりだったとしたら……まあ、もう奴らの手にこの結晶が無いことを喜ぶとしよう。", 0xa4481d13, 0x4621729c, 0xb3c94759, 0xdbb5841e, 0x5b9d7398, "....." },
  [6564] = { "古き神々への忠誠", "AshenvaleのJe'neu SancreaにDamp Noteを渡して下さい。", "くしゃくしゃになったメモに、下手な字が走り書きされている：\n\n「そうだ、女司祭たち全員に、水晶を私のもとへ持ってくるよう伝えよ。水晶の中には水のエレメンタルの霊が強く宿っており、我らのaquamancerたちが自ら召喚を行う際の大きな助けとなるだろう。\n\n水晶の中の力を御することで、我らはAku'Maiを鎮めるのだ。いつの日か、Aku'Maiを我らのもとへ呼び戻せるだけの力が集まり、世界はその最も偉大な時代へと還るだろう！Old Godsが支配する時代へと！」", "何だ、{name}？何の用だ？nagaが集めている結晶について、まだ調べねばならんことが多いのだ。", "これは実に興味深い。私の目に留めてくれて助かった。\n\nこれで我々の悩みの種に名前がついたな……Lorgus Jettか。", 0xf45fe9ed, 0xe0c8139f, 0x719ece7a, 0x8ad48820, 0x0561038f, "....." },
  [6565] = { "古き神々への忠誠", "Blackfathom DeepsでLorgus Jettを殺し、AshenvaleのJe'neu Sancreaのところへ戻って下さい。", "このTwilight's Hammerの信奉者に計画を遂げさせるわけにはいかない。Twilight's Hammerは自然の霊を理解していない。奴らが信じるのはOld Gods――遠い昔に打ち倒された、混沌と破壊の存在だ。このLorgusを成功させてはならない。奴を止めてくれ、{name}。私自身ではできない――弱りすぎているのだ。\n\nBlackfathom Deepsへ入り、奴を見つけて殺せ。片が付いたら、ここZoram'garの私のもとへ戻ってきてくれ。", "もう奴を見つけたか、{name}？Lorgusを止めねばならん！", "実によい!! ありがとう、{name}。Twilight's Hammerを完全に止められたわけではないかもしれんが、少なくともOld Godsを再び権力の座へ戻そうという、やつらのもう一つの企みは食い止めた。\n\nやつらがほかにどんな企みを形にしつつあるかは分からんが、今はひとまず安心していられる。", 0xf45fe9ed, 0xfbcf40e9, 0x496bbaf9, 0x743f304b, 0x69b34095, "....." },
  [6566] = { "風が運んだもの", "Thrallの話を聞いて下さい。", "また会えて嬉しいぞ、{name}。風がEastern Kingdomからの知らせを運んできた。\n\n座って聞くがいい。", "焦るな、{name}。よく注意しておけ！", "この仕事にとりかかる準備はいいか?", 0x7ec308ae, 0xe453d7c1, 0xe7172974, 0xc7dd0473, 0x40959543, "....." },
  [6567] = { "Hordeの戦士", "Rexxarを探し出す。彼の居場所は大族長から教えられている。Stonetalon MountainsとFeralasの間にある、Desolaceの道を探して下さい。", "私の勇者の一人から、竜の巣へ入る道があるかもしれないとの知らせを受けた。お前は彼を探し出すのだ。\n\nRexxarはDesolaceの荒れ果てた砂漠をさまよい、StonetalonとFeralasの間を行き来している。彼はお前の到着を待っている。", nil, "ドラゴンの巣へ入る道はただ一つだ、{race}。\n\nいいか、群れの母の巣へ入ることを許されるのは、Black Dragonflightの中でも最強の者だけだ。数多くの試練を越えねばならず、中へ入るための鍵は、General Drakkisath自らが儀式によって魔法をかけるのだ！\n\nお前は黒いドラゴンの眷族ではないから、通行を得るのに少々苦労するかもしれん。\n\n<Rexxarはにやりと笑う。>", 0x9e62ab4c, 0x7c7eaae9, 0x53a737c9, nil, 0x643411c5, "...m." },
  [6568] = { "Rexxarの証言", "Rexxar's TestamentをWestern PlaguelandsのMyranda the Hagに届けて下さい。", "幻術について何を知っている、{name}？分かるか、Black Flightの守りを出し抜くために、お前は幻を作り出さねばならんのだ。\n\nこの欺きのクエストに手を貸してくれるかもしれない者を一人知っている。大義に値すると認めた時には、これまでも我らの同胞を助けてくれた女だ。\n\nWestern PlaguelandsへゆけばMyranda the Hagがいる。幻術の達人で、Lordaeron同盟からの追放者だ。そこへ行き、この伝言を持っていけ。", "Lordaeronのこのあたりで、Hordeの者を見かけることはめったにないわ。Myrandaに何を持ってきたのかしら？", "<Myrandaが手紙を手に取り、少し間を置いて、微笑む。>\n\nあの人は元気? Rexxarのことよ。あら、そんなに困った顔をしないで。あの手紙はわざと白紙のままにされていたの。それは書いた者の意図と思いを運んでいたのよ。中身から察するに、Rexxarがああしておいたのも無理はないわ。あなたが捕らえられるか殺されるかして、この情報が見つかっていたらと考えてごらんなさい!\n\nああ、気にしないで! Myrandaがあなたを助けてあげる、{race}。大族長には借りの一つや二つはあるのだから。\n\n<Myrandaが微笑む。>", 0x317e218f, 0x874610ed, 0x7eca30c4, 0x11f0f4f7, 0x9c079ebf, "....." },
  [6569] = { "眼の錯覚", "Blackrock Spireへ行き、Black Dragonspawn Eye 20個を集めて下さい。完了したら、Myranda the Hagのところへ戻って下さい。", "それで、この{race}がBlack Flightの一員になりたいというのかい？\n\nあんたに要る幻そのものを作るのは造作もないことさ。けれど占いに要る材料は手に入れるのがなかなか難しくてね。Rexxarと大族長がこの任務をあんたに託したんだから、Myrandaとしてもあんたが腕の立つ者だと見込むしかないさね。\n\nBlackrock Spireの上層の城塞へ行って、black dragonspawnをたっぷり倒し、そのeyesで袋の一つを満たしておいで。\n\n材料が十分に集まったら、Myrandaのところへ戻っておいで。", "どんな幻術でも、一番大事な材料は真似したい相手の目なのよ、{name}。\n\n<Myrandaは「Scarlet Crusade」と書かれた、目玉があふれんばかりに詰まった袋を指さす。>\n\n<Myrandaは笑う。>", "Myrandaに見せてごらんなさい、{race}。\n\nええ、これでよく間に合うわ。\n\nこの試薬があれば、Myrandaがあなたのために、black dragonflightの門番を欺く幻影を与えるメダルを作ってあげましょう。", 0x2bad6541, 0x5de63ab2, 0x4f4b0a78, 0x40106753, 0xc88c7071, "....." },
  [6570] = { "Emberstrife", "Dustwallow MarshのWyrmbogへ行き、Emberstrife's Denを探し出して下さい。中へ入ったら、Amulet of Draconic Subversionを身につけEmberstrifeと話して下さい。", "このメダリオンには、Emberstrifeの巣の内で幻を生み出し、保つのに必要な魔力を同調させておいた。\n\nEmberstrifeは古のdrakeだ。Nefarianの古き門番であり、Onyxiaの精鋭護衛の位へ昇ろうとするdragonspawnを試す務めを負っている。\n\nDustwallow MarshのWyrmbogへ行き、Emberstrifeの巣に入れ。そこでamuletを身に着け、運命の導くままに進むがよい！", nil, "Nefarian様がチビを送ってくるだなんて、有能な兵士が枯渇しているのか? お前では我が試練には通るまい、同胞よ。", 0x6e6c84be, 0x68462fdc, 0xeba39a80, nil, 0x9470e63e, "...m." },
  [6571] = { "Warsongの補給用物資", "Warsongの補給用物資を集めて下さい。Warsong Saw Blades・Logging Rope・Warsong Oil・Warsong Axe Shipmentを集めて、Splintertree PostのLocke Okarrに渡して下さい。", "Warsongの伐採キャンプでいくつかの品が不足してるんだ！\n\nSplintertree PostのPixelがうちのsaw bladesの荷を預かってる。axesの木箱はBooty BayまでいってWharfmaster Lozgilから受け取ってこなきゃならない。\n\noilとropeの荷はもっと厄介だ。ropeはThistlefurとFoulwealdのfurbolgsに盗まれた。oilの配送はsatyrsに横取りされて、今じゃNight Run、Satyrnaar、Xavianでの忌まわしい儀式に使われてるんだ！\n\n手を貸してくれるか？", "物資を何とか揃えてくれるといいんだけど！早く届けないと大変なことになるんだ！", "見事だ、{name}。おかげでずいぶん手間が省けた!\n\nだが、感謝していないなどとは思うなよ!", 0xa776f6d8, 0xe0a604fd, 0x0c3cfec5, 0x658fa1ea, 0x495630c4, "....." },
  [6582] = { "頭蓋骨の試し・Scryer", "青の竜族のドレイクの勇者、Scryerを見つけ出して倒さなければならない。その死体から頭蓋骨をもぎ取り、Emberstrifeのところへ持ち帰って下さい。\n\nScryerはWinterspringにいることが分かっている。", "我らはDeathwingの子らだ、雛よ。劣ったAspectsへの我らの支配は、知らしめられねばならぬ。\n\nそなたが真に昇格に値するなら、劣ったdragonflightはそなたの前で萎えしおれよう。\n\n奴らの勇士を見つけ出し、我らが父上の名のもとに打ち滅ぼせ！\n\nWinterspringへ赴き、強大なる青のdrake、Scryerを追え。奴と、行く手を阻むBlue Flightの者どもを叩き潰せ。奴の頭蓋を引き抜き、我がもとへ持ち帰るのだ。", "<Emberstrifeはシューッと息を漏らす。>", "試練のうちのひとつが達成された……", 0xd4e320f7, 0x1467aba3, 0xec99c5eb, 0x9b46d3b4, 0x6ad7b728, "....." },
  [6583] = { "頭蓋骨の試し・Somnus", "Green Flightの戦士Somnusを殺して下さい。Somnusの頭蓋骨をEmberstrifeの元に持ち帰って下さい。", "我らが父上がAspectsそのものを打ち砕くように、我らもまた、奴らの子らに混沌と破壊をもたらさねばならぬ。\n\n眠らぬ夢見る者ども――Green Flightの子らを相手に、そなたの武勇を試すのだ。\n\nSwamp of Sorrowsへ赴き、Green Flightのdrakeの勇士、Somnusを追え。憎しみを解き放て。虫けらを屈服させよ……奴の頭蓋を持って戻るのだ……", "敵の血を浴び、その苦しみを味わい尽くすまで、ここへ戻ってくるな。", "またひとつ達成……", 0xa6d94f8f, 0x82bcebf0, 0xd83cd2cf, 0xf12ea661, 0x5b0b6cfa, "....." },
  [6584] = { "頭蓋骨の試し・Chronalis", "Tanaris DesertのCaverns of Timeを守っているのは、Nozdormuの子、Chronalisです。Chronalisを殺して頭蓋骨をEmberstrifeに渡して下さい。", "時を見守る者ども、Nozdormuの子ら――Lord of the Centuriesss……\n\nCaverns of Timeを守るのは3体。だがBlack Flightにとって気にかけるべきは1体のみ。Time Shifter、Nozdormuお気に入りの仔竜、Chronalisだ。\n\nこの勇士を打てぇ、動じぬ時の砂さえ泣かせるほどの一撃を。奴の頭蓋を持って戻るのだ。", "皮肉なことだが、小童よ、時間こそが肝要なのだぁぁ。", "最も憎き死骸だ……", 0xc44aac34, 0x38263530, 0xfb25247f, 0xae0bd587, 0x2eb5587e, "....." },
  [6585] = { "頭蓋骨の試し・Axtroz", "Grim Batolへ行き、Red Flightのdrake champion Axtrozを見つけ出して下さい。Axtrozを殺して頭蓋を入手し、Emberstrifeに渡して下さい。", "我らが父上がAspectsの力を結集した軍勢と荒れ狂って戦ったのは、Grim Batolの山々の上であった。裏切り者Alexstraszaの卑怯な振る舞いが、他のAspectsに父上の怒りから逃れる時を与えたのだ。\n\nなぁんと恥ずべき行いよ……\n\n今やRed FlightがGrim Batolを守っておる。その副官、Axtrozを滅ぼさねばならぬ。Axtrozの頭蓋を我がもとへ持ち帰れ。父上のために、雛よ！", "変化ぁぁ……そなたの中で起きているのを感じるぞ、小童。この試練を越えれば、残るは儀式のみだ。", "お前の献身を疑っていたぞ、小僧。だがお前はやり遂げ、我らの敵を圧倒し、我らの一族に誉れをもたらした。\n\nでは今から、お前の昇格のために頭蓋を整えるとしよう。", 0x96788f83, 0x48284fc4, 0xc3500aed, 0xead6876b, 0x43cbef24, "....." },
  [6601] = { "昇進……", "謎かけ遊びは終わるようです。Myranda the Hagがあなたに作ったAmulet of Draconic SubversionはBlackrock Spire内では機能しません。Rexxarを見つけ、苦境について説明するとよいでしょう。彼にDull Drakefire Amuletを見せて下さい。彼ならば次に何をすべきか知っていることでしょう。", "我らが敵の頭蓋から、メダリオンが形作られる。このメダリオンを知っておろう、なぁ？そなたの年長者たちが身に着けているのを見たことがあるはずだ。\n\n受け取れ、雛よ。Spireへ戻り、これをGeneral Drakkisathに差し出すのだ。将軍がメダリオンに最後の魔法をかけ、この装身具をそなたの魂に同調させてくれよう。\n\n完成したメダリオンは誉れの証として身に着けるがよい。それは、我らの最も厳重に守られた位の一つ――brood motherの守護者への昇格の証なのだ。\n\n行け！", "慌てるな、{name}！", "竜のおしゃべりよりは価値のある錆びたコインなら持ってるぜ、{name}。奴らの話は信用しすぎるなよ。そういう類の虚勢は、竜どもにはありがちだからな。", 0x1b907c01, 0x74690080, 0x18fae3e7, 0x4ca8f04e, 0x53a0d258, "....." },
  [6602] = { "Blood of the Black Dragon Champion", "Blackrock Spireへ行き、General Drakkisathを討ち取って下さい。彼の血を集めてRexxarに渡して下さい。", "将軍のもとを訪ねてもらうが、Black Dragonflightの一員としてではない。\n\nいいか、Black Flightにとって儀式とは、血を流すことの言い換えにすぎないのだ。\n\n眠っているamuletが力を得るには、将軍の血さえあればよい。奴らの粗雑な安全装置の一つだ。\n\nBlackrock Spireへ戻り、Drakkisathを滅ぼせ。その血をここへ持ち帰れば、Onyxiaの巣への鍵を目覚めさせてやろう。", "Drakkisathを侮ってはならんことは、言うまでもないだろう。\n\n奴の手にかかって死んだ幾千もの者たちが、それを物語っている。", "長年にわたって記憶される勝利だ、{name}。Drakefire AmuletがOnyxiaの巣を開くだろう。仲間を集めて、Hordeに勝利をもたらしてくれ。", 0x9d1c3849, 0x5a67aea8, 0xa400dac9, 0x1b4339bd, 0x86d61907, "....." },
  [6603] = { "Winterspringでの厄介事!", "Winterspringで、温泉の傍にいるDonova Snowdenを見つけて下さい。", "Winterspringで厄介事だ！\n\nいやあ、俺は荒野で過ごすことが多いから、そういうことには詳しいのさ……胸を張ってそう言えるね。あの丘で過ごす時間は黄金だと思ってる。素早い反射神経、冷静な頭、鋭い目を養ってくれるからな……\n\n俺みたいに荒野のありがたみが分かるには、判断力と頭脳と成熟が要るんだよ。\n\nさて、何の話をしてたっけ？\n\nああそうだ、厄介事だ。温泉にいるDonova Snowdenに会えば、詳しく教えてくれるさ。", nil, "ちょっと、そこのあなた! 私が見つけた問題についてはMeggiが話してくれたんでしょう?", 0x44414ba6, 0x059fbcc2, 0xaea9e1fd, nil, 0x0dd5e9d1, "...m." },
  [6604] = { "怒り狂うWildkin", "Starfall VillageのJaron Stoneshaperと話して下さい。", "ここから南にある、見捨てられた野営地に気づいたかい？wildkinが暴れ回って、見つけられるものをほとんど全部壊してしまったみたいなんだ！\n\n襲撃の生存者の一人が、ここから西のStarfall Villageで休んでいるって噂を聞いたよ。何があったのか気になって仕方ない……君もそうだろう？", nil, "ああ、何か用かい?", 0x79149705, 0xb52378e8, 0x474f0700, nil, 0x40303f26, "...m." },
  [6605] = { "変な奴", "FelwoodのWinna Hazzardと話して下さい。", "Felwoodから戻ってきたところなんだ、{name}。通りがかりにBloodvenom Postに寄ったら、とても変わった人に会ってね……何か一つのことに夢中みたいだった。それが何なのか教えてあげてもいいんだけど、きっと彼女は自分の口から説明したがると思うんだ。\n\n興味があるなら、Felwoodの西にあるBloodvenom Postへ行って、Winna Hazzardを探してごらん。\n\nもしかしたら、君の助けが必要かもしれないよ……", nil, "ああ、{class}。まだ望みがあるようですね。私を手伝いにきてくれたのでしょう?", 0xbfd601ab, 0x658a1b4a, 0xd570b6ad, nil, 0xd546ad0d, "...m." },
  [6606] = { "ちょっとした幸運", "OrgrimmarのWitch Doctor Mau'ariと話して下さい。", "少しばかりの運は、いつだってありがたいもんだろ？ちょっとした強みさえあれば、物事を自分に有利に運べるのさ……\n\nしばらく前に、かなり風変わりな呪術医と知り合いになってね。彼女が幸運のお守りを作ってくれたんだ……代金と引き換えにね。でも本当に、それだけの価値はあったよ！\n\n自分用のが欲しいかい？OrgrimmarのWitch Doctor Mau'ariに会ってみな。俺のは譲らないからね！", nil, "ほう、Harloがあんたをよこしたってか? で、あんたは誰なんだい? おれの助けが欲しいってわけか?", 0x01480ede, 0x36ee0ee3, 0xfb04d024, nil, 0x7da942c3, "...m." },
  [6607] = { "釣りの達人、Nat Pagle", "Nat Pagleは以下の魚を釣ってくることを望んでいます。\n\nSwamp of SorrowsのMisty Reed Strandで釣れるMisty Reed Mahi Mahi。\n\nDesolaceのSar'theris Strandで釣れるSar'theris Striker。\n\nFeralasのVerdantis Riverで釣れるFeralas Ahi。\n\nStranglethorn ValeのSavage Coastで釣れるSavage Coast Blue Sailfin。\n\n全部釣れたならNat Pagleの元へ戻ってください！", "本当に釣りを楽しんでるとはいえないだろうね。20年も30年もずっと釣りをしてきたことを考えてごらん。\n\n人が何かをすることの理由なんてさまざまだからね。\n\nさて、熟練した漁師になるには30年も釣りをする必要もないし、世界中の魚を釣り上げる必要もない。ただ決意だけが必要だ。何もせず浮きを見つめたままずっと座り続ける決意があれば十分だ。\n\n何が言いたいかって言うと、珍しい魚をいくつか釣ってきてくれたら、一つ二つ教えてあげよう。何を釣ってほしいかは、リストにしておいたよ。", "今日は何か食いついたかい？", "よく釣れたね！\n\nこっちへおいで。釣りの極意を伝授しよう。", 0xac59e2e5, 0x36b6358f, 0x5aa64309, 0xd57a7a65, 0x3941c747, "....." },
  [6608] = { "良すぎる。", "もう自分ではあなたの釣りスキルを伸ばすことはできない、とLumakは言おうとしているようです。彼の友人Nat Pagleを探した方がよいでしょう。Nat Pagleは人間で、Theramore南のある島で釣りをしています。(少なくとも、Lumakが言わんとしていたと思われる内容です)", "Lumak、もう{name}教えられない。良すぎ! Lumakの友達探して。Nat Pagle。人間だけど、食べるダメ! Lumak友達! Nat、釣りもっと良く教える。\n\nNatはDustwallow Marshにいる。南の人間の町。Thermoroとか何とかいうとこ。Natたぶん釣りしてる。行け!", nil, "もちろん、君はLumakの友達だろ。\n\n釣り? 釣りのすべてを教えてあげるよ。", 0x369612ab, 0x6f08769c, 0x21ec23cf, nil, 0xab959ea7, "...m." },
  [6609] = { "何も残ってないんだ!", "Kalimdorの港町Theramoreへ行って下さい。そこから、街の南にある島を探さなくてはなりません。Nat Pagleがあなたの来訪を待っています!", "俺はドワーフなんだ、なんてこったい! 釣りをするようには作られてないのさ! 俺を見てくれって言ってるんだよ! 実際に石から作られてるんだ。\n\n俺には何も残されてない……あんたが使い果たしたのさ。知ってることは全部教えてやったんだよ、バタバタとね!\n\n分かったか? ああ、よし。Kalimdorの向こうに古い友人がいるんだが、そいつなら手伝ってくれるだろ。そいつの名はNat Pagle、いい奴さ。\n\nTheramoreの南の島にいる。さあ行け!", nil, "お客さん用のスペースはいつも確保してあるよ……たぶんね……", 0x7469ef5c, 0x359ead0c, 0x3456ca82, nil, 0xf4e96883, "...m.", nil, nil, 0x7b35d4f4, nil, nil },
  [6610] = { "Clamlette Surprise", "Dirge Quikcleave は下記のものを持ってきてくれると幸せになれるらしい。\n\n12個のGiant Eggs。\n\nTanarisならRocsっていう奴から手に入る、もしくは他のでかい鳥なら持ってるはず。\n\n10個のZesty Clam Meat  普通にそこら辺の貝からみつかるはず！\n\n20個のAlterac Swiss  汝、チーズショップにて取得すべし！\n\n全部手に入れたらDirge様の元へ戻りなさい。", "Clamletteって聞いたことあるか？　もちろん知らないよな！？\n\n最新かつ、最強の料理の最高傑作・・。\n\nっと、おー{name}。ちょっとClamletteのこと考えていたらヨダレでまくりでなー。\n\nいやしかし、残念だなー。今ちょっと材料まったくねーんだわ。\n\nそうだ、こうしないか？\n\nお前がClamlette作るのに必要な素材をとってきて、んで、俺がお前にエキゾチックな料理の詳細を教える。\n\nそして、二人分つくって二人ともハッピー！！\n\nってどうよ？\n\nとりあえず、必要なものここに書いとくからな。", "この食欲のせいで身を滅ぼしそうだ！急いでくれ、{name}。自分の蓄えに手を出しちまう前に。", "特別なお楽しみが待ってるぜ、{name}。よく見て学びな！\n\n<Dirgeはclamlette surpriseの準備を始める。>", 0xed5328d0, 0xd4e9b30a, 0x337c0659, 0x2d9a164d, 0x177f9dfe, "....." },
  [6611] = { "Gadgetzanへ行け!", "Tanaris砂漠のGadgetzanへ行き、料理人としての経歴を発展させることについてDirge Quikcleaveと話して下さい。", "何か教えてくれるとでも思ったかい? あたしの料理の魔法を全部手に入れたってのに、まだこれ以上欲しいってのかい!\n\nあたしじゃご希望に添えないね。太っちょ{race}はGadgetzanへ行きな。あそこにDirgeって名前のちびゴブリンがいる……あいつなら叶えてくれるよ、おでぶさん。\n\n有名な料理人になったら、戻ってきてあたしに教えとくれ。いいかい? じゃあ行きな!", nil, "<Dirgeは革サンダルのかけらを吐き出した。>\n\nペッペッ……\n\n<Dirgeは盛大に咳をした。>\n\n何か? 革はプロテインが驚くほど高くて、炭水化物は少ないってことを教えてやるよ。", 0x287c6197, 0x103eb5ec, 0x3bc2d5e9, nil, 0xeebeedd7, "...m." },
  [6612] = { "ある男を知ってる……", "Tanaris砂漠のGadgetzanへ行き、料理人としての経歴を発展させることについてDirge Quikcleaveと話して下さい。", "料理スプーンを見れば、あんたが料理の何を理解してるか分かるぜ。残念ながら、俺に教えられることは何もない。\n\nあんたにゃラッキーなんだが、俺はある男を知ってる。そいつはゴブリンで、恐らくKalimdorで最高の料理人だ。\n\nおっと、こいつは悪い知らせだが……Kalimdorへ行かなきゃなんねえぞ。Gadgetzanへ行ってDirge Quikcleaveを探しな。あいつなら解決してくれるだろ。", nil, "<Dirgeは革を吐き出した。>\n\nペッペッ……\n\n<Dirgeは盛大に咳をした。>\n\n何か? 革はプロテインが驚くほど高くて、炭水化物は少ないってことを教えてやるよ。{race}。", 0x805c2ee8, 0x103eb5ec, 0xd2dad20c, nil, 0xf54e38b8, "...m.", nil, nil, 0xd7c7d16a, nil, nil },
  [6621] = { "Foulweald族の王", "Foulweald Totem MoundにKarang's Bannerを掲げて下さい。furbolgにその旗を破壊させてはいけません。Chief Murgutを倒し、Murgut's TotemをZoram'garのKarang Amakkarに渡して下さい。", "{name}、Furbolgの別の部族、FoulwealdがAstranaarの南東に住んでいる。Thistlefurほど数は多くないが、その凶暴さは将来の脅威となる。力を見せつければ、その脅威を取り除けるだろう。\n\nこの旗を持ってFoulwealdの村へ行き、奴らのトーテムの塚に立てろ。奴らは旗を壊そうとするだろうが、族長のMurgutが部族の面子を保とうと現れるまで持ちこたえろ。奴が持っているトーテムを俺のところへ持ってこい。\n\n仲間を集めろ、{name}。これは{class}一人でこなせる仕事ではない。", "Chief Murgutは倒したか、{name}？奴のFoulweald Totemは取り戻したか？", "よくやりましたね、{name}。Foulweald族の者に挑み族長を倒したことは、furbolgsに警告を叩きつけたことでしょう。\n\nHordeを侮ってはならない、と。\n\nあの部族が長い間面倒を起こすようなことはなくなるでしょう。", 0x72c799c0, 0x7662f59e, 0x2ca45fcc, 0x6f018d4b, 0x73b4797f, "....." },
  [6622] = { "重症度判定検査", "Triage Bandageを使って傷の治療をし、負傷者を救って下さい。傷によって6人が死亡する前に15人の負傷者を救わなければなりません。\n\n重症度判定の順を忘れないで下さい! Critically Injured Soldierが最も早く死亡し、Badly Injured Soldierがそれに続きます。Injured Soldierは死亡するまでの時間が最も長いので、Critically Injured SoldierとBadly Injured Soldierの後で助けるべきであると判定されます。", "こんにちは、先生。今日の午後、あなたが患者を適切にトリアージできるかどうかの試験を行います。試験に合格すれば、名誉あるHorde Traumaの一員となります。\n\nでは、よく聞いてください！重篤な負傷者から先に手当てしなければなりません。重篤な者の次は重傷の者です。負傷者は最後に手当てしてください。この試験に合格するには、15人の患者を救わなければなりません。トリアージ中に患者が6人死亡した場合は不合格です。\n\nTriage Bandageは支給されます。\n\n幸運を祈ります、先生。", "奇跡のような腕前ですね、先生。本当に奇跡です。", "{name}先生、Horde Traumaへようこそ。", 0x66af70c6, 0x24b63d90, 0x2c30b239, 0xe7bd87ac, 0x63620819, "....." },
  [6623] = { "Horde Trauma", "Arathi Highlands の Hammerfall へ行き、Horde Trauma への仲間入りについて Doctor Gregory Victor と話して下さい。", "{name}先生、ですね。お会いできて光栄です。\n\n素敵なお知らせがありますよ! Hammerfall にいらっしゃる Horde Trauma 医師会会長の Gregory Victor が個人的に参加依頼をしているんです。一生に一度のチャンスになるかもしれませんよ! 偉大な医師 Gregory Victor 先生の元で研究する機会が与えられるのなら、私なら何だってやりますね! この機会を無駄にしないで下さいね、先生!", nil, "素晴らしい。手術着を着たまえ、すぐ始めねばならん!", 0x800e34de, 0x827dcf0e, 0x0849290c, nil, 0xd23a5cab, "...m." },
  [6624] = { "重症度判定検査", "Triage Bandageを使って傷の治療をし、負傷者を救って下さい。傷によって6人が死亡する前に15人の負傷者を救わなければなりません。\n\n重症度判定の順を忘れないで下さい! Critically Injured Soldierが最も早く死亡し、Badly Injured Soldierがそれに続きます。Injured Soldierは死亡するまでの時間が最も長いので、Critically Injured SoldierとBadly Injured Soldierの後で助けるべきであると判定されます。", "ご機嫌よう、先生。本日午後、負傷兵の重症度判定能力によって試されることになる。試験に合格すれば、Alliance Traumaの一流医師の仲間入りをすることになる。\n\nそれではよく聞きたまえ! 危篤状態の負傷者を真っ先に治療しなければならん。危篤者の後が重傷者となる。通常の負傷者の治療は最後にすべきだ。試験に合格するには15人の負傷者を救わねばならない。重傷度判定で6人の負傷者を死なせたら不合格だ。\n\n頑張ってくれたまえ、先生。", "奇跡のような腕前ですね、先生。本当に奇跡です。", "{name}先生、Alliance Traumaへようこそ。", 0x66af70c6, 0x24b63d90, 0xa3779d84, 0xe7bd87ac, 0xd31dbaee, "....." },
  [6625] = { "Alliance Trauma", "Dustwallow MarshのTheramoreへ行き、Alliance Traumaへの仲間入りについてDoctor Gustaf VanHowzenと話して下さい。", "{name}先生、ですよね。お会いできて光栄です。\n\nあなたに素敵なお知らせがあるんです! TheramoreにいらっしゃるAlliance Trauma医師会会長のGustaf VanHowzenが個人的に参加依頼をしているんです。一生に一度のチャンスになるかもしれませんよ! 偉大な医師VanHowzen先生の元で研究する機会が与えられるのなら、何だってやりますわ! この機会を無駄にしないで下さいね、先生!", nil, "素晴らしい。手術着を着たまえ、すぐ始めねばならん!", 0x3640cfdf, 0x8c4e1cd1, 0x64adb09e, nil, 0xd23a5cab, "...m." },
  [6626] = { "邪悪の軍勢", "Razorfen Battleguardを$N1体、Razorfen Thornweaversを$N2体、Death's Head Cultistsを$N3体倒し、Razorfen Downsの入口近くにいるMyriam Moonsingerのところへ戻って下さい。", "私の見たところ、Forsakenは自分たちの……病を……他者にうつしたりはしない。この外交官は、信奉者になろうとする者たちに不死を与えているようだ。奴はScourgeの一員なのではないかと思い始めている。\n\nとはいえ、今のところ私の関心は奴ではなく、奴の周りで膨れ上がっている手勢のほうだ。奴らは毎日影から這い出してきて、奴にさらなる力をせがまんばかりだ。\n\n私一人で奴らと戦えるほどの力はない、{name}。どうだ？狩りに付き合う気はあるか？", "狩りの具合はどうだ、{name}？この外交官の力をほんの少し目にしただけで、Scourgeがこの世界にかつて現れた中でも最大級の脅威だということに、もはや疑いはなくなった。", "ありがとう、{name}! あなたがしてくれた仕事は、きっと大いに役立つでしょう。\n\n私はこの外交官と、ここにいる残りのquilboarの研究を続けます。もっと大きな冒険を求めるなら、友を何人か集めて、すぐそこにある巨大な猪の口のような洞窟に入ってみるといいでしょう。中に入れば、もっと手ごわい試練が待っているはずです。", 0xa6ad637c, 0x1d953fc6, 0x50ddd7c3, 0x416675bc, 0x196700d7, "....." },
  [6627] = { "知恵の試し", "Braug Dimspiritの問いに正しく答えた後、また話しかけて下さい。彼はStonetalon Mountainsに留まっているでしょう。", "本を持ってきてくれたから、試しを始めよう。準備はいいかな?\n\n{class}、時間は気にしなくていいから、焦らずにな。答えたい時まで好きなだけ時間をとって構わない。", "人生は問いに満ちています、{class}。そのすべてに答えることは決してできませんが、時間をかけて学べば、少しは物知りになれるかもしれません。", "よくやったな、{class}。私が問うた文献について学んできたのだね。もう君は別の試しに通ったのだ。", 0xdf27dbbd, 0xf6917aca, 0xec0ad382, 0x516e97bd, 0x80548961, "....." },
  [6628] = { "知恵の試し", "Parqual Fintallasの問いに答えた後、再度話しかけて下さい。用意ができるまで彼はUndercityに留まっているでしょう。", "今一度、試しの時がきた。知恵を学ぶ者として、私の課した仕事を引き受けて大いなる不屈の心を示した。\n\nそれでは、問いを出そう。用意ができたなら再び話しかけるがいい。いくらでも時間をかけていいぞ、{name}。早く答えようと焦る必要などない。", "この世界で生き延びたいのなら、知っておくべき決まりが1つだけあります。知れば知るほど、多くのものが見えてくる、ということです。\n\nよく学び、よく観察すれば、他のどの{race}にも見えないものが、この世界に見えてくるでしょう。", "よくやった、{name}。持ってくるよう頼んだ文献について学んできたか疑問だったが、お前は正しく答えた。", 0xdf27dbbd, 0xb665516e, 0x01337379, 0xa493f15e, 0x242f01c9, "....." },
  [6629] = { "Grundig Darkcloudを殺せ", "Grundig Darkcloudと６体のGrimtotem Brutesを殺し、Stonetalonの南東端近くにいるMakaba Flathoofのところへ戻ってください。", "{name}、あなたはGrimtotem族を殺してくれました。もし勇気があるなら、Grundig Darkcloudとその取り巻きが、数いるけだものの中で最もたちが悪いです。あいつは私の村にたいする残忍な攻撃の先頭に立っていました。\n\n少し西にいったところのGrimtotem Postで、あいつを見つけられるでしょう。\n\nやつを殺してください。一生のお願いです。", "Grundig Darkcloudと、奴の手下のBrutesは倒したか？", "Grundig Darkcloudが死んだ！　{name}、あなたが今日ここでしてくださったことは、一生忘れません。", 0x9168fe63, 0x410c3d4d, 0x726195b3, 0x20857c13, 0xa13011e8, "....." },
  [6641] = { "Vorsha the Lasher", "火桶に向かうMuglashを守って下さい。火桶の火を消すのを手伝い、Nagaと戦って彼を守って下さい。\n\n無事に終えたらZoram'gar Outpostへ戻って、Vorsha the Lasherの死をWarsong Runnerに知らせて下さい。", "Vorsha the Lasher……この海をうろつく凶悪なヒドラだ……\n\nVorshaは前哨を毎回理由もなく攻撃し、行く手にあるものすべてを荒らして回るんだ。\n\nだが準備が整ったぞ、{name}。あのヒドラを倒し、Zoram'garへの攻撃を止める用意ができた。\n\nnagaは海岸のはずれにある島にある火桶を使って、Vorshaという邪悪な存在を崇拝している。その火を消してしまえば、Vorshaは怒り狂って姿を現すはず。\n\n助けが必要になるだろうから、忘れずに強い仲間を連れてくるんだぞ。", nil, "ここへやって来たときから、私はnagaの攻撃をたくさん見てきた。もう二度と自由気ままにVorshaがうろつき回ることが無くなって、ほっとしている。\n\n我々は皆、恩を感じているよ。{name}。", 0x3efe9ea2, 0x8d14a546, 0xf9fcb52d, nil, 0xec24fd21, "...m." },
  [6661] = { "Deeprun Rat捕獲", "Rat Catcher's Fluteを使ってDeeprun Ratを5匹捕まえてください。ネズミたちをMontyのところまで連れて帰ってください。終わったらRat Catcher's Fluteを返すのを忘れないようにしてください。", "やめろ、野郎ども。あー……あー、仕事を探してんのか? ここじゃ深刻なネズミの問題に頭抱えててよ、船尾楼甲板の手が足りねえんだ。\n\nどうだい? やることは害獣の周りでRat Catcher's Flute吹くだけだ。世界の果てまで着いてくるぜ!\n\n5匹捕まえてここまで持ち帰るだけでいい。生きてるのが必要なんだ。\n\nあー……。", "ヤーッ……おい下っ端、何をそんなにもたもたしてやがる？", "よさそうだぜ、相棒。俺の兄弟がこいつらを必要としてんだ。駄目になった奴以外をな……。酸っぱくなったラットケバブなんて味わいたかねえだろ。", 0x058b4f5c, 0xc9e92c7d, 0x5a7d2f9f, 0x43339737, 0xa19d5900, "....." },
  [6662] = { "俺の兄弟 Nipsy", "Stormwind Deeprun Tram Depotにいる Nipsy に Carton of Mystery Meat を渡して下さい。", "俺の兄弟 Nipsy が Deeprun の向こう側でラットケバブの商売やってんだ。駄目になる前にネズミの箱を持ってってくれよ。とっとと頼むぜ!\n\nもうトラムには乗ったのかい? 簡単だぜ。トラムが到着したらぽんと乗って、後は旅を楽しむだけだ。乗ってる間は手や足を外に出すなよ。一生義足になりたくなきゃな。", "<Nipsyは人差し指をcartonの空気穴の1つに差し込む。>\n\n生きがいい……しかもちょうど間に合った！", "可哀相な Monty 。Gnomeregan の事故以来、おかしくなっちまったんだ。あいつはいまだに海を見たことが無いんだ。ましてや海賊なんて。\n\n<Nipsy は溜息をついた。>\n\n何はともあれ、あいつはネズ公をこっちに流し続けてくれてるよ。", 0xfb9ecfec, 0x87d7d034, 0xb75e7e9d, 0x3088e5a6, 0x9f0f0959, "....." },
  [6681] = { "The Manor, Ravenholdt", "Seal of Ravenholdtを、Hillsbradの丘陵に隠れたRavenholdt ManorのFahradのところへ持って行って下さい。\n\n道中、あなたの機転が試されるだろう。覚悟しておくこと。", "{name}へ\n\nRavenholdtはお前に興味を持っている、若き盗賊よ。我々は見ていた。お前の身のこなしはいささかぎこちないが、我々に直せないほどではない。\n\nMaster Ravenholdtの弟子として、またAssassin's Leagueの一員としての道を歩む覚悟があるなら、Seal of Ravenholdt（この手紙に同封）をRavenholdt Manorへ持ってくるだけでいい。\n\n最初の任務は、Hillsbradの丘に隠された館を見つけ出し、お前の狡猾さを示すことだ。\n\n敬具\n\nFahrad", "Miltonには会ったか？\n\n<Fahradは笑う。>", "実に見事だ、若き盗人よ。\n\n少々痛めつけられたようだが、大事はなさそうだな。\n\n長い旅がお前を待っている。長く、そして実りある旅がな。ついにRavenholdtの師たちの中で己の運命を受け入れる覚悟はできているか?\n\n外にいる衛兵と話せ。彼らが手ほどきをしてくれる。", 0x0b732c16, 0xad30c642, 0x8b5efb3f, 0x86bc2b9c, 0x29310286, "....." },
  [6721] = { "ハンターの道", "DolanaarのDazalarと話す。", "こんにちは、若きハンターよ。あなたは獣を扱い、相棒として訓練できるだけの腕を持っているように見えます。\n\nDolanaarのDazalarに会わなければなりません。彼があなたを自分のペットを手に入れる道へと導いてくれるでしょう。", nil, "そうだ、時が来たぞ、{class}。", 0xe59cef47, 0xacb77771, 0x57c4b6af, nil, 0xca92f25f, "...m." },
  [6722] = { "ハンターの道", "DolanaarのDazalarと話す。", "こんにちは、若きハンターよ。あなたは獣を扱い、相棒として訓練できるだけの腕を持っているように見えます。\n\nDolanaarのDazalarに会わなければなりません。彼があなたを自分のペットを手に入れる道へと導いてくれるでしょう。", nil, "そうだ、お前を鍛える時が来た……", 0xe59cef47, 0xacb77771, 0x57c4b6af, nil, 0x6d03693e, "...m." },
  [6761] = { "新たなる辺境", "DarnassusのCenarion EnclaveにいるMathrengyl Bearwalkerと話して下さい。", "Moongladeからの救援要請には、私の副官Mathrengyl Bearwalkerに対処させることにした。この件については彼と話せ――私では「ない」。\n\n少しばかり……親切な……助言をしてやろう。我らの種族がすべてを失った時、我らを闇から導き出したのはこの私だ――MoongladeのCenarion Circleでは「ない」。Teldrassilは我ら皆に新たな命を与えてくれる！奴らはお前に別のことを信じさせようとするだろうが、奴らの宣伝を信じるなど愚か者のすることだ。\n\nお前が愚か者かどうかは、お前自身に判断を任せよう。", nil, "ええ、{class}、来てくれてありがとうございます。誤解があったことをお詫びします……ここの大ドルイドとMoongladeのKeeper Remulosの間には、不信感が満ちているのです。互いに相手が策略を巡らせていると疑っていますし、Teldrassilの奇妙な穢れが衰えることなく続いているという事実も、ここではいまだに問題です。それが不信を和らげることはほとんどありません。\n\nいずれにせよ、Cenarion Circleへの私たちの務めは変わりません……それを率いる者たちが、互いに意見を異にしていようとも。", 0x980efd04, 0xc843270f, 0x3b0ebeda, nil, 0x1a73fafa, "...m." },
  [6762] = { "Rabine Saturna", "MoongladeのNighthavenの村にいるRabine Saturnaと話して下さい。MoongladeはFelwoodとWinterspringの間にあり、Timbermaw Holdから出る道を通って行ける。", "この務めについては、MoongladeにいるKeeper Remulosの執事、Rabine Saturnaが、Tanarisのはるか西……そしてUn'Goroのさらに西に広がる広大な荒れ地の探索に力を貸してくれる者を求めています。Moongladeの主要な村、Nighthavenで彼に会えるはずです。\n\nあなたの働きは間違いなく私たち皆にとって大きな益となるでしょうが、慎重に振る舞うよう忠告しておきます。DarnassusとMoongladeの間には緊張があるのです……時とともに高まっていくかもしれない緊張が。", nil, "私はRabine Saturnaです。Keeper Remulosと、この聖なる森に住むすべての者に代わり、あなたを歓迎します。\n\nCenarion Circleを助けようというあなたの関心と熱意に感謝します。Darnassusの大ドルイドが、あなたが私たちに力を貸すことに不満を示したことも知っています。ですが、それはより大きな善のためであり、あなたが向けられるかもしれない浅はかな報復からは守られますから、安心してください。\n\nここにいるのはあなたの友ばかりですよ、{name}。", 0x53da4216, 0x2d1faec5, 0xf45142aa, nil, 0xbe6728af, "...m." },
  [6804] = { "毒された水", "Eastern Plaguelandsの毒に侵されたエレメンタルにAspect of Neptulonを使う。Discordant Bracersを$N1個とAspect of NeptulonをAzsharaのDuke Hydraxisのところへ持って行って下さい。", "エレメンタルの斥候の一団がLordaeronのeastern plaguelandsへ送られたが、その地の病が彼らを歪め、蝕んだ。Waterlordsは、我らの純粋さに対するこの侮辱を許すわけにはいかぬ！\n\nこの小瓶を持っていけ。中にはaspect of Neptulonがいくらか入っている。疫病に冒されたエレメンタルに使えば、彼らの体内の毒と戦い、癒やすであろう！だが、その内なる葛藤が彼らを荒れ狂う狂気へと駆り立てるであろう。\n\ndiscordant surgesを倒し、そのbracers of bindingを我のもとへ持ってこい。", "bracersは持っているか？", "よくやった、{class}。そなたが癒した穢れたelementalたちは、あらゆる水にとって許しがたい冒涜であった。我らの力は純粋さにこそある。他の者どもとの戦に勝つには、我らは強くあり続けねばならぬ。", 0x8166e516, 0xa750443e, 0x2a5ec42b, 0x9a94795d, 0xdcea2c7a, "....." },
  [6805] = { "StormersとRumblers", "Dust Stormersを$N1体とDesert Rumbersを$N2体倒し、AzsharaのDuke Hydraxisのところへ戻って下さい。", "我ら水のエレメンタルは、劣った元素の者どもと戦を繰り広げている。そなたがこの戦いにおいて真に我らの味方であるなら、その信念を示してみせよ！\n\nはるか南、砂漠の地Silithusで、風と大地の従者どもがCrystal Valeという岩場の一角をうろついている。奴らは、小さき者ども、すなわち定命の者たちから力ある品々を守っている。奴らがなぜそうするのかは知らぬが、我はその企てを挫きたいのだ。\n\nSilithusのCrystal Valeへ行き、我らの敵を倒し、そして我のもとへ戻れ。", "臆病さなど、我々は認めぬ、{class}。Silithusへ行き、勇気を示すがいい。", "そなたの勇気は証明された。我らにとってのそなたの価値もな。いずれそなたに任せる務めがあるやもしれぬ。Waterlordsの大切な盟友にこそふさわしい務めがな。", 0x05d4b511, 0x008195fd, 0x85ab9517, 0x893965e3, 0xd9b082da, "....." },
  [6821] = { "Eye of the Emberseer", "Eye of the EmberseerをAzsharaのDuke Hydraxisのところへ持って行って下さい。", "そなたは、我らの敵を倒し、Waterlordsの大義のために任務を果たせることを示した。だが、これまでそなたが相手にしてきたのは劣った敵のみ……強大な敵と対峙した時、そなたは勝てるか？\n\nそれがそなたの新たな務めだ。\n\nBlackrock Spireの高みで、オークどもが炎の従者、Pyroguard Emberseerを捕らえている。奴が囚われている場所を見つけ、看守どもを倒し、そしてemberseerを倒せ。奴の目を我のもとへ持ってこい。それがそなたの価値を示すであろう。", "Eyeは持っているか、{class}？Blackrock Spireに入る力はあるか？", "ほう、やはり力はあるようだな。そして知恵もある。Blackrock Spireは力任せだけで太刀打ちできる場所ではないのだから。\n\nまことに、{name}、そなたはいずれ我らの大切な盟友となるやもしれぬ……", 0x8318aac6, 0x6e3b7202, 0x4bc3b5c3, 0xf8a387b0, 0xe9a520af, "....." },
  [6822] = { "Molten Core", "Fire Lordを$N1体、Molten Giantを$N2体、Ancient Core Houndを$N3体、Lava Surgerを$N4体倒し、AzsharaのDuke Hydraxisのところへ戻って下さい。", "{name}、そろそろそなたに真の試練を与える時かもしれぬ。準備はよいか？\n\nBlackrock Depthsの底に、Molten Coreへの通路がある。そこは我らの敵の拠点であり、この世界で最も強大な炎の従者どもが守っている。\n\nMolten Coreへ行け、{name}。そこで待ち受けるものを倒す力と意志があることを、我に示せ。\n\nそして、そなたの同胞に味方がいるなら、彼らを結集させよ。軍勢でもなければ、Molten Coreに入って生きて帰ることなど望めぬ。", "Molten Coreでのそなたの成功を待っているぞ、{name}。", "そなたは、同族の大半が不可能と考えることを成し遂げた。Molten Coreの者どもに立ち向かい、勝利したのだ!\n\nそれほど小さき生き物でありながら、そなたは大いなる機知を示した。\n\nいつの日か、そなたの種族とWaterlordsの間に真の盟約を結べるやもしれぬ。", 0x65404883, 0xa634f4a5, 0x20707849, 0xc50496a5, 0x1cf1aca1, "....." },
  [6823] = { "Hydraxisの代理人", "Hydraxian WaterlordsとHonoredの友好度を得てから、AzsharaのDuke Hydraxisと話して下さい。", "そなたが真に我らとの盟約を望むなら、我らの敵、風と大地と炎の従者どもに戦を仕掛けるがよい。そなたが奴らに敗北を重ねるたびに、この地での奴らの足場は弱まり、我らの大義へのそなたの忠誠はさらに証明されるであろう。\n\n戦いは長くなろう。だが、耐え抜けば、そなたの栄光と名誉は大いなるものとなろう。", "そなたの戦いはまだ終わっておらぬ、{name}。出向いて我らの敵、風と大地と炎の僕どもを打ち倒すのだ。さすればいつの日か、Waterlordsの広間に席を得られるやもしれぬ。", "我らの敵に対するそなたの功績は、Waterlordsの広間に響き渡っておるぞ、{name}。そなたの体は我らの戦で戦うには小さくもろすぎると考える者もいたが、そなたは大きな戦果を上げた。そなたは我らの間で敬意を勝ち得たのだ。信じがたい偉業よ。", 0xf0c62cfa, 0xa57d2952, 0xba6762ec, 0xa7b43f6f, 0xe468742e, "....." },
  [6824] = { "敵の手", "Hands of Lucifron、Sulfuron、Gehennas、ShazzrahをAzsharaのDuke Hydraxisのところへ持って行って下さい。", "{name}、そなたの働きは我らにとって大いに価値がある。ゆえに、これほど役に立つ者を失いたくはなく、この最後の任務にそなたを送り出すのはためらわれる。\n\nだが、その成功は我らの戦いを大いに前進させるであろう……そなたを危険にさらす価値があると判断されたのだ。\n\nMolten Coreにいるこれらの隊長ども、Lucifron、Sulfuron、Gehennas、Shazzrahを滅ぼしてほしい。奴らを殺し、その手を我のもとへ持ってこい！\n\nこの務めには、そなたの持てるすべての力が必要となろう、{name}。だが、成し遂げられれば、Firelordsに痛烈な一撃を与えられるのだ。", "Lucifronとその他の者どもは倒したか、{name}？敵の手は持っているか？", "手を持ってきたか! 炎の隊長どもを倒したのだな! そなたとその力を知らなければ、可能とは思わなかったであろう。\n\n{name}、そなたの功績は数え切れぬが、この度の偉業の知らせはWaterlordsの間に波紋を広げるであろう。そなたの名はいつの日か、我らにとって伝説となるやもしれぬ。\n\nまた我に話しかけるがよい、{name}。さらに別の務めがあるやもしれぬ……", 0x6ed69526, 0x1128609f, 0x77ece8a4, 0x9200e18f, 0x143ecfe9, "....." },
  [6843] = { "Da Foo", nil, nil, nil, nil, 0x7a326c5c, nil, nil, nil, nil, ".mmmm" },
  [6844] = { "古記録管理人Umber", "Encrusted Silithid Objectを、Moongladeのvillage of NighthavenにいるUmber(Cenarion Circleの古記録管理人)のところへ持って行って下さい。", "ここではまだやることが山ほどあるが、これをCircleへ持ち帰って分析してもらうのが肝心だと思う。信じてくれ――全部片がついても、仕事はここに残ってるさ。このべたつくキチン質の中にあるのが日誌なら、Circleはついに過去を覗く窓を手に入れることになる！\n\nこれをNighthavenのCircleの記録係のところへ持っていってくれ。名前はUmber、天才だ。ちょっとイカれてるのは確かだが、それでも天才さ！Umberはこれよりずっとひどい状態の書物を救い出してきた。救えるものなら、あいつが救ってくれる。", "おや、こんにちは！ふうむ……\n\n少し正直に言わせてもらうよ、友よ……君はちょっと臭うね。ぷんぷんする、とでも言おうか。いや、君という人を個人的に攻撃しているわけじゃないんだ。ただね……今後は、外から戻ってきたら少しさっぱりしたほうがいいかもしれない。第一印象がもう少し好ましく印象的になるからね！\n\nまあそれはさておき……何か用かな？", "こりゃたまげた！何を持ってきたんだい？本みたいな形をしてるような……この殻を割ってみるとしよう。\n\nLayoがSilithusから君をよこしたって？あそこで起きている恐ろしいことについては、ひそひそとした噂しか聞いたことがないんだ。まあ、考えてみればそれほどひそひそでもないんだがね。それに私は虫みたいなものがどうにも好きじゃない。そうなりゃ、私はここで本と一緒にいるしかないってわけさ！", 0xc0c48fe8, 0x110cbec8, 0xe16f6b67, 0x757645c2, 0xcd6bf57e, "....." },
  [6845] = { "明かされた過去の秘密", "Moongladeのvillage of NighthavenにいるRabine Saturnaと話して下さい。", "とにかく、近いうちにまた顔を出してくれ……中に何が入っていたか知りたいならな。これが何なのか、そして本当に本なのかがわかりしだい、喜んで教えるよ。\n\nそれまでの間、この小さな熊の野営地の世話役、Rabineに顔を出しておくといい。君がどんな無茶をしてきたか、きっと知りたがるはずだ。世話役を待たせちゃいけないぞ、{name}……蜂蜜まみれにされたいなら別だけどな。\n\n実際にあったことさ、信じてくれ。", nil, "ああ、{name}、立ち寄ってほしいと思っていた。会えてよかった。\n\nあなたがSilithusからやってくるという知らせを受けて、これまでに受けた支援に対するCenarion Circleの感謝を直接伝えたかったのだ。間違いなく、Silithusから発見される秘密は多い。Umberに届けてくれた物は、今までに発見された中で最も興味深いと判明するだろう。あなたの援助に対する感謝の印として、これを受け取って欲しい。\n\nありがとう、親切な{class}よ。", 0xeabb3200, 0x5071bbe4, 0x9bb68a79, nil, 0xa03acc7f, "...m." },
  [6846] = { "攻撃開始！", nil, nil, "我が部隊は補給を終え、攻撃の準備ができている。あとはNoreg Stormpikeからの命令さえあれば、奴らを戦場へ送り込むぞ！", "おお、命令書か! 好きな時に攻撃せよとある。そして俺の意志は……今だと言っている!", 0x80850fde, nil, nil, 0x1801510b, 0x3ee75b62, ".mm.." },
  [6901] = { "攻撃開始！", nil, nil, "我が部隊は補給を終え、攻撃の準備ができている。あとはFrostwolf Quartermasterからの命令さえあれば、奴らを戦場へ送り込むぞ！", "やっとか! これでAllianceに、Alterac Valleyへ来たことの愚かさを思い知らせてやれるぞ!", 0x6ce8c6de, nil, nil, 0x2a18344c, 0x48b87d80, ".mm.." },
  [6921] = { "遺跡の中に", "AshenvaleのZoram'gar OutpostにいるJe'neu Sancreaに、Fathom Coreを渡して下さい。", "Twilight's HammerがBlackfathom DeepsのMoonshrine Ruinsに入り込んだ。奴らがいれば、エレメンタルは我々に背くよう強いられるばかりだ。放っておけば、この地は永遠に奴らのものになってしまう。\n\n{name}、Blackfathomへ入り、遺跡のfathom stoneを見つけてくれ。水の中のどこか近くにあるはずだ。その中にfathom coreがある。正しく読み取れば、あらゆるエレメンタルの活動の歴史を語ってくれる装置だ。それが手に入れば、私とEarthen Ringで奴らを止められるかもしれない!", "fathom coreは見つかりましたか? それがなければ、Twilight's Hammerがあそこで一体何を企んでいるのか見当もつきません。", "まさにこれが必要だったのだ! fathom coreは、我々が多くの恵みを引き出せる、途方もない情報の泉だ。Twilight's Hammerがあの中で何を企んでいようと――よいことであるはずがないのは請け合う――仲間たちと私が今こそ暴いてみせる。\n\nお前は今日ここでよく働いた。Earthen Ringは、我々を助けてくれたお前を温かく見ている。お前はHorde全体をも助けたのだ。そのことは誇ってよい。", 0x09596e4f, 0xedf98535, 0x8b83bfb4, 0x55331311, 0x22dfd3c7, "....." },
  [6922] = { "Baron Aquanis", "Strange Water Globe を Ashenvale の Zoram'gar Outpost の Je'neu Sancrea に渡して下さい。", "倒された水のエレメンタルは、奇妙な水の球を残していった。この物体が何らかの形であの怪物に力を与えていたのだろう、と推測できる。球の中では、腐ったような水がちゃぷちゃぷと揺れている。球そのものは、どんな物理的な力も受けつけないようだ。\n\nこの品の正体を突き止められる者がいるとすれば、Earthen RingのJe'neu Sancreaだろう。彼はAshenvaleにあるHordeのZoram'gar Outpostにいる。", "ああ、また会いましたね、{name}。ちょうどいつものように海の波を読んでいたところです。この前哨地へは何の用で?", "これは……大発見だぞ、{name}。\n\nBlackfathom の Baron Aquanis から手に入れたと言ったか? 長い間、Baron Aquanis は腐敗した精霊の力だと考えられてきた。この玉は、Aquanis がいったい何によって堕落させられたのかを証明するだろう。これが Twilight's Hammer によるものと判明してもおかしくはない。我々の研究によって、奴らがどのようにこれを成功させたかが明らかになるはずだ。\n\nよく持ってきてくれた。どうぞ、これを持っていってくれ。Earthen Ring の心からの感謝だ。", 0x6317c3fa, 0x5afab460, 0xeafedd21, 0xd1397112, 0x5fa18944, "....." },
  [6961] = { "Great-father Winterがやってきた!", "Greatfather Winterと話して下さい。彼はOrgrimmarのSmokywood Pastures露天商市場にいます。", "友よ、素晴らしいWinter Veilを! 必ずGreatfather Winterに挨拶して下さいね! 今年あなたが親切だったなら、Winter Veil祝祭日の素晴らしいご馳走を受け取れるでしょう。今年欲しい物を彼に伝えるのもお忘れ無く!\n\nあと、今年親切にしてくれた人にあげるご馳走を買い込むのもお忘れ無きよう。選ぶ物は豊富に取り揃えていますよ。私たちの農場から、あなたのお皿まで新鮮なものを……それがSmokywood Pasturesの健康に良い美味しさ!", nil, "はいどう、どう。こんにちは。私はGreatfather Winter。それと、気の良いSmokywood Pasturesの人々からの厚意……「私たちの農場からあなたのお皿へ新鮮なものを。それがSmokywood Pasturesの健康に良い美味しさ」……Winter Veilの素晴らしい祝祭があなたに訪れますように。\n\n今年あなたが良い人だったなら、Winter Veil祝祭のご馳走としてSmokywood Pasturesのご馳走を受け取れるでしょう。ばんざい。", 0x9a9ce503, 0x591cc909, 0xba4aa7ab, nil, 0x296b27e3, "...m." },
  [6962] = { "Great-father Winterへのおやつ", "Gingerbread Cookie 5枚とIce Cold MilkをOrgrimmarのGreatfather Winterに渡して下さい。", "やあ、頼んでいいかな? ええと、おちびさん。\n\nわざわざ自分のことを三人称で言うつもりはないけど、Greatfather Winterは一日中ここにいて腹ぺこだから、自分で食べるおやつが必要なんだ。gingerbread cookiesを少し、それとクッキーを流し込むice cold milkがあったらいいなあ。君がGreatfatherの友達だと思うなら、いくつか取ってきてくれないかな?", "お菓子の話ばかりしていたら、自分でも食べたくなってきたよ。うーん……gingerbread cookiesとmilk……", "{name}、君はGreatfather Winterじいさんのいいお手伝いさんだね。素敵なWinter Veil祝祭を楽しんでね。\n\nささやかなものだけど……そうだよ、お礼にあげよう。", 0xf3a28acd, 0xf01a51da, 0x6341ef2b, 0x11c73f24, 0x004980cd, ".....", nil, nil, 0xcc6e16c8, nil, nil },
  [6963] = { "盗まれたWinter Veilのご馳走", "Alterac Mountainsの雪国で行方不明になったSmokywood Pastures捜査官を捜して下さい。", "聞いて下さい……ここで季節の魔法を壊さないために。でも、Smokywood Pasturesには少し手助けが……あなたのような冒険型の人に助けてもらう類の手助けが、必要なんです。\n\nこの季節のために私たちが仕入れ直した、大事なご馳走の積荷が無くなってしまいました。そして、積荷を探すために送り出したSmokywood Pasturesの者までが行方不明になってしまったんです! お願いします……積荷が最後に報告されたのはAlterac Mountainsでした。積荷を探しに行った者がいるのもそこなんです。\n\n両方ともそこで無事で元気にしているかどうか、見てきて下さい!", nil, "き、き、聞こえるのか！も、も、儲けの神に感謝だ！\n\nお、俺は本当はゆ、ゆ、雪だるまなんかじゃない。な、な、名前はSacksで、Smokywood PasturesのOrgrimmarし、し、支店で働いてるんだ……な、な、なくなった荷物を探しにここへ送られたんだが、い、今まで見たこともない、い、生き物に襲われたんだ！\n\nす、す、すごく寒い……", 0x3874de93, 0xfed7fa48, 0x497a89c9, nil, 0x377efbe5, "...m." },
  [6964] = { "祝祭の季節の由来", "Winter Veilの祝祭について、OrgrimmarのValley of WisdomにいるSagorne Creststriderと話して下さい。", "贈り物に、ご馳走に、プレゼント……ふん。ちょっとあんた!\n\nあのゴブリンたちはこの季節の本当の意味を汚しているよ。……Winter Veilの祝祭を。これは再生の時なんだ。大地はGreatfather Winterによって生み出された雪の毛布の下でまどろむ。……Greatfather Winterは、赤い衣装を着てあっちでブツブツ言ってる馬鹿なんかじゃないんだ!\n\nこの祝祭に関するすべてのことを知りたいと思ったなら、Sagorne Creststriderに聞いてみるといい。プレゼントをもらうことより歴史のことを知りたいという者に驚くに違いないよ。", nil, "Winter Veilの祝祭だって? ああ……昔、それは我々トーレンにとって深い意味を持ったものだったんだ。今では、再生の季節の伝説も飴玉やプレゼントを売るのに役立つ日か何かに誰かが変えてしまったようだがな。\n\nそういう変わり方に対して、Furmundが苦々しく思っていたとしても不思議じゃない。そういったトーレンたちは、戦旗のように過去にしがみついているんだ。ちょっとしたお祝いってのは、いつもいいものだ。だが、祝祭の起源を覚えておくことは大切だよ。", 0x64e6e152, 0x9b2211a9, 0x0a5d9d35, nil, 0x100c2eb2, "...m." },
  [6981] = { "Glowing Shard", "Ratchetへ行き、輝く欠片についてもっと詳しく教えてくれる人を探して下さい。\n\nその後、指示どおりに欠片を届けて下さい。", "その欠片は鮮やかな緑色で、固いのに、表面のすぐ下で煙のようなものが渦巻いている。結晶の奥をつい見つめてしまうが、同時に、どこかひどく不穏なものがあると分かる。\n\nRatchetに、この奇妙な欠片についてもっと教えてくれる者がいないか確かめてみるべきかもしれない。", "こんにちは、{race}。何かご用ですか？", "なんという……このような物は見たこともありませんよ……。", 0x855951c0, 0x9db6d7f4, 0xf1eddfb4, 0x60aba222, 0xcb5cd7b9, "....." },
  [6983] = { "あんたは意地悪な奴だ……", "Stolen Treatsを探してOrgrimmarのKaymard Copperpinchに返して下さい。最終的に所持していると思われるのはAbominable Greenchです。その獣はAlterac Mountainsの雪国のどこかにいます。", "「Abominable Greench」というそのいいい生き物は、積荷のごごごご馳走を盗んだややや奴なんだ、{name}。だがききき気をつけろ! ああああいつ、私をゆゆゆ雪だるまにしやがったんだ!\n\n奴にたたた立ち向かうのに、手伝いがいるだだだだろう。私は奴がイイイイエティがいるそこら中をあああ歩き回ってるのを見たんだ。奴はたたた確かにここのどどどどこかにいる! ご馳走をみみみ見つけてくれ、{name}。ご馳走をOrgrimmarのSmokywood Pasturesにかかか返して、解凍してほほほほしいと言っていたとつつつ伝えてくれ!", "{name}、補充するtreatsがなければ、私たちのFeast of Winter Veilは台無しだ！今シーズンはGraccu本人も、いい子のみんなにおいしいミートパイを分けてあげられなくなってしまう……", "見つけてくれたのですか! あなたはSmokywood PastureのWinter Veilのご馳走を守って下さった!\n\n可哀想なSacks……私たちはチームを送って、確実に彼の凍結を解除する方法を見つけ出すつもりです。うまくいけば、彼は祝祭日に間に合うように戻ってこられるはず。もっとも、失った時間は働きながら取り戻す必要があるでしょうけど。でも、あなたがいなかったら、それすら不可能だったでしょうね!", 0xdc4f5e6e, 0x02350e7e, 0x390e1fd2, 0x5cb087ef, 0x84619c0c, "....." },
  [6984] = { "Smokywood Pasturesのありがとう!", "OrgrimmarでGreat-father Winterと話して下さい。", "私たちSmokywood Pasturesの者は、盗まれたご馳走を取り戻して下さったことに感謝しています、{name}。それで、あなたに特別な贈り物を差し上げたいのです……他ならぬ、Great-father Winterその人から!\n\nどうぞGreat-father Winterと話して下さい。Smokywood PasturesからのWinter Veil祝祭の贈り物をあなたにくれるでしょう。私たちの農場から皆さんのお皿まで、それはいつもSmokywood Pasturesの健康に良い美味しさ。……あなたのおかげです、もちろん!", nil, "はいどう、どう。こんにちは、冒険者さん!\n\n休暇シーズンの特別な贈り物はあなたが獲得したとゴブリンから聞きました。これを贈ることができて嬉しいですよ。お待ちどお。……今後とも、今年も来年も再来年も、毎年Winter Veilの素晴らしい祝祭を楽しんで下さいね。", 0xfdb1c16f, 0xd0fa8c0a, 0x37044edc, nil, 0xc8c04af1, "...m." },
})
